    "Loading your usage… If this stays empty, tap Refresh.": "ଆପଣଙ୍କ ବ୍ୟବହାର ଲୋଡ୍ ହେଉଛି… ଖାଲି ରହିଲେ ରିଫ୍ରେସ୍ ଦବାନ୍ତୁ।",
    "Insights needs Screen Time access.": "ଅନ୍ତର୍ଦୃଷ୍ଟିକୁ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆକ୍ସେସ୍ ଦରକାର।",
    "You can turn it on from Today.": "ଆପଣ ଏହାକୁ ଆଜି ରୁ ଚାଲୁ କରିପାରିବେ।",
    "Go to Today": "ଆଜି କୁ ଯାଆନ୍ତୁ",
    "What you see": "ଆପଣ ଯାହା ଦେଖୁଛନ୍ତି",
    "Your Screen Time from the last 28 days plus today, as iOS reports it. Today is shown on its own and never counts in weekly comparisons.": "ଗତ ୨୮ ଦିନ ଓ ଆଜିର ସ୍କ୍ରିନ୍ ଟାଇମ୍, iOS ଯେପରି ଜଣାଏ। ଆଜି ଅଲଗା ଦେଖାଯାଏ ଓ ସାପ୍ତାହିକ ତୁଳନାରେ କେବେ ଗଣାଯାଏ ନାହିଁ।",
    "Missing isn't zero": "ନଥିବା ମାନେ ଶୂନ୍ୟ ନୁହେଁ",
    "iOS sometimes reports late or only part of a day. Days without data are marked, never counted as zero. If Insights looks empty, tap Refresh.": "iOS କେବେ କେବେ ବିଳମ୍ବରେ କିମ୍ବା ଦିନର କେବଳ ଏକ ଅଂଶ ଜଣାଏ। ଡାଟା ନଥିବା ଦିନ ଚିହ୍ନିତ ହୁଏ, କେବେ ଶୂନ୍ୟ ଗଣାଯାଏ ନାହିଁ। ଅନ୍ତର୍ଦୃଷ୍ଟି ଖାଲି ଲାଗିଲେ ରିଫ୍ରେସ୍ ଦବାନ୍ତୁ।",
    "Apps and totals": "ଆପ୍ ଓ ମୋଟ",
    "App times overlap, so they won't add up to your total screen time.": "ଆପ୍ ସମୟ ପରସ୍ପର ସହ ମିଶିଯାଏ, ତେଣୁ ସେଗୁଡ଼ିକ ଯୋଗ କଲେ ଆପଣଙ୍କ ମୋଟ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ମେଳ ଖାଏ ନାହିଁ।",
    "Other devices": "ଅନ୍ୟ ଡିଭାଇସ୍",
    "If Screen Time is shared over iCloud, other devices of the same kind may be included.": "iCloud ରେ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ସେୟାର୍ ଥିଲେ ସମାନ ପ୍ରକାରର ଅନ୍ୟ ଡିଭାଇସ୍ ମଧ୍ୟ ଅନ୍ତର୍ଭୁକ୍ତ ହୋଇପାରେ।",
    "Private by design": "ଆରମ୍ଭରୁ ହିଁ ବ୍ୟକ୍ତିଗତ",
    "Your usage stays inside Apple's Screen Time report. Demora can't read, save or send it.": "ଆପଣଙ୍କ ବ୍ୟବହାର Apple ର ସ୍କ୍ରିନ୍ ଟାଇମ୍ ରିପୋର୍ଟ ଭିତରେ ହିଁ ରହେ। Demora ତାହା ପଢ଼ିପାରେ ନାହିଁ, ରଖିପାରେ ନାହିଁ କି ପଠାଇପାରେ ନାହିଁ।",
    // Insights: comparison sentences, coverage and week names (report).
    "%@ h": "%@ ଘ",
    "%@ less than the week before": "ପୂର୍ବ ସପ୍ତାହ ଠାରୁ %@ କମ୍",
    "%@ more than the week before": "ପୂର୍ବ ସପ୍ତାହ ଠାରୁ %@ ଅଧିକ",
    "%@: %@ less than your estimate.": "%@: ଆପଣଙ୍କ ଅନୁମାନ ଠାରୁ %@ କମ୍।",
    "%@: %@ more than your estimate.": "%@: ଆପଣଙ୍କ ଅନୁମାନ ଠାରୁ %@ ଅଧିକ।",
    "%@: about the same as your estimate.": "%@: ଆପଣଙ୍କ ଅନୁମାନ ପ୍ରାୟ ସମାନ।",
    "(%@%%)": "(%@%%)",
    "About the same as the week before": "ପୂର୍ବ ସପ୍ତାହ ପ୍ରାୟ ସମାନ",
    "Day": "ଦିନ",
    "Last 7 full days": "ଶେଷ ୭ ପୂର୍ଣ୍ଣ ଦିନ",
    "No comparison yet: both weeks need full data.": "ଏପର୍ଯ୍ୟନ୍ତ ତୁଳନା ନାହିଁ: ଦୁଇ ସପ୍ତାହକୁ ପୂର୍ଣ୍ଣ ଡାଟା ଦରକାର।",
    "No data": "ଡାଟା ନାହିଁ",
    "No earlier week to compare.": "ତୁଳନା କରିବାକୁ ପୂର୍ବ ସପ୍ତାହ ନାହିଁ।",
    "No full week yet": "ଏପର୍ଯ୍ୟନ୍ତ ପୂର୍ଣ୍ଣ ସପ୍ତାହ ନାହିଁ",
    "Partly reported": "ଆଂଶିକ ଭାବେ ଜଣାଯାଇଛି",
    "The week before": "ପୂର୍ବ ସପ୍ତାହ",
    // Trend dashboard.
    "Trends": "ଧାରା",
    "Weekday patterns": "ସପ୍ତାହର ଦିନ ଧାରା",
    "Biggest app changes": "ଆପ୍ ର ସବୁଠାରୁ ବଡ଼ ବଦଳ",
    "%d days": "%d ଦିନ",
    "No comparable app changes yet.": "ଏପର୍ଯ୍ୟନ୍ତ ତୁଳନୀୟ ଆପ୍ ବଦଳ ନାହିଁ।",
    "Selected period": "ବାଛିଥିବା ସମୟ",
    // Usage dashboard navigation, chart hints, and duration totals.
    "Previous week": "ଗତ ସପ୍ତାହ",
    "Next week": "ଆସନ୍ତା ସପ୍ତାହ",
    "No trend yet": "ଏପର୍ଯ୍ୟନ୍ତ ଧାରା ନାହିଁ",
    "%@ h %@ min": "%@ ଘ %@ ମି",
    // Usage & trends and the practical Guide.
    "%@ min": "%@ ମି",
    "%@ – %@": "%@ – %@",
    "A blank Screen Time report does not mean no usage. Try the refresh arrow, wait for iOS to load, and check access if it stays blank. If a schedule, daily reset or due change seems late, open Demora to reconcile state. An enforcement warning means monitoring needs attention; if a new rule exceeds capacity, reduce overlapping schedules rather than assuming it was saved.": "ଖାଲି ସ୍କ୍ରିନ୍ ଟାଇମ୍ ରିପୋର୍ଟର ଅର୍ଥ ବ୍ୟବହାର ନାହିଁ ଏପରି ନୁହେଁ। ରିଫ୍ରେସ୍ ତୀର ଚେଷ୍ଟା କରନ୍ତୁ, iOS ଲୋଡ୍ କରିବା ପର୍ଯ୍ୟନ୍ତ ଅପେକ୍ଷା କରନ୍ତୁ, ଏବଂ ଖାଲି ରହିଲେ ଆକ୍ସେସ୍ ଯାଞ୍ଚ କରନ୍ତୁ। କୌଣସି ସମୟସୂଚୀ, ଦୈନିକ ରିସେଟ୍ କିମ୍ବା ପ୍ରାପ୍ୟ ବଦଳ ବିଳମ୍ବ ଲାଗିଲେ ସ୍ଥିତି ମିଳାଇବାକୁ Demora ଖୋଲନ୍ତୁ। ପ୍ରୟୋଗ ଚେତାବନୀର ଅର୍ଥ ନଜରଦାରୀକୁ ଧ୍ୟାନ ଦରକାର; ନୂଆ ନିୟମ କ୍ଷମତା ଅତିକ୍ରମ କଲେ ଏହା ସେଭ୍ ହୋଇଛି ବୋଲି ନଧରି ଓଭରଲାପ୍ ହେଉଥିବା ସମୟସୂଚୀ କମାନ୍ତୁ।",
    "A free period suspends daily limits within its scope, and usage during it is credited back using Screen Time checkpoints, not an exact live stopwatch. An unblock makes its selected apps usable but is not the same as free usage. Other overlapping rules can still block them. Recurring free periods live alongside recurring blocks. Edit apps on a recurring block keeps its identity and timing; the old selection stays active through the less-strict delay.": "ମୁକ୍ତ ସମୟ ତାହାର ପରିସରରେ ଦୈନିକ ସୀମା ସ୍ଥଗିତ ରଖେ, ଏବଂ ସେହି ସମୟର ବ୍ୟବହାର ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଚେକ୍‌ପଏଣ୍ଟ ଦ୍ୱାରା ଫେରି ଜମା ହୁଏ, ସଠିକ୍ ଷ୍ଟପ୍‌ୱାଚ୍ ଦ୍ୱାରା ନୁହେଁ। ଅନବ୍ଲକ୍ ବାଛିଥିବା ଆପ୍‌କୁ ବ୍ୟବହାରଯୋଗ୍ୟ କରେ କିନ୍ତୁ ମୁକ୍ତ ବ୍ୟବହାର ସହ ସମାନ ନୁହେଁ। ଅନ୍ୟ ଓଭରଲାପ୍ ହେଉଥିବା ନିୟମ ସେମାନଙ୍କୁ ବ୍ଲକ୍ କରିପାରେ। ପୁନରାବୃତ୍ତ ମୁକ୍ତ ସମୟ ପୁନରାବୃତ୍ତ ବ୍ଲକ୍ ପାଖରେ ରହେ। ପୁନରାବୃତ୍ତ ବ୍ଲକ୍‌ରେ ଆପ୍ ବଦଳାଇଲେ ତାହାର ପରିଚୟ ଓ ସମୟ ସମାନ ରହେ; ପୁରୁଣା ବାଛିବା କମ୍ କଡ଼ା ଅପେକ୍ଷା ପର୍ଯ୍ୟନ୍ତ ଚାଲୁ ରହେ।",
    "About how much time do you spend on your phone each week?": "ପ୍ରତି ସପ୍ତାହ ଫୋନ୍‌ରେ ଆପଣ ପ୍ରାୟ କେତେ ସମୟ ବିତାନ୍ତି?",
    "Add an optional weekly estimate": "ଏକ ବୈକଳ୍ପିକ ସାପ୍ତାହିକ ଅନୁମାନ ଯୋଡ଼ନ୍ତୁ",
    "App choices and usage stay on-device. Demora has no accounts, advertising or analytics. Optional contact invitations and approval requests relay the names, descriptions and notes you send through CloudKit or Cloudflare and Resend; the email provider receives the readable message and code. Time checks contact Apple's website, and email requests use App Attest verification. Widgets use a small local summary, not app-selection tokens or raw usage.": "ଆପ୍ ବାଛିବା ଓ ବ୍ୟବହାର ଡିଭାଇସ୍‌ରେ ହିଁ ରହେ। Demora ରେ କୌଣସି ଖାତା, ବିଜ୍ଞାପନ କିମ୍ବା ଆନାଲିଟିକ୍ସ ନାହିଁ। ବୈକଳ୍ପିକ ଯୋଗାଯୋଗ ନିମନ୍ତ୍ରଣ ଓ ଅନୁମୋଦନ ଅନୁରୋଧ ଆପଣ ଦେଇଥିବା ନାମ, ବିବରଣୀ ଓ ନୋଟ୍ CloudKit କିମ୍ବା Cloudflare ଓ Resend ମାଧ୍ୟମରେ ପଠାଏ; ଇମେଲ୍ ପ୍ରଦାତା ପଢ଼ିବା ଯୋଗ୍ୟ ବାର୍ତ୍ତା ଓ କୋଡ୍ ପାଏ। ସମୟ ଯାଞ୍ଚ Apple ର ୱେବସାଇଟ୍‌କୁ ଯାଏ, ଏବଂ ଇମେଲ୍ ଅନୁରୋଧ App Attest ଯାଞ୍ଚ ବ୍ୟବହାର କରେ। ୱିଜେଟ୍ ଛୋଟ ସ୍ଥାନୀୟ ସାରାଂଶ ବ୍ୟବହାର କରେ, ଆପ୍ ବାଛିବା କିମ୍ବା କଞ୍ଚା ବ୍ୟବହାର ନୁହେଁ।",
    "Blocking needs Screen Time permission. You may finish setup after declining it; Demora respects denial and does not automatically redirect you to iOS Settings. If you want to enable access later, use Demora's permission prompt or open iOS Settings yourself. iOS controls authorization and background callbacks, so blocking is not an unbypassable guarantee.": "ବ୍ଲକ୍ କରିବାକୁ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଅନୁମତି ଦରକାର। ମନା କଲେ ମଧ୍ୟ ସେଟଅପ୍ ଶେଷ କରିପାରିବେ; Demora ମନାକୁ ସମ୍ମାନ କରେ ଓ ନିଜେ ନିଜେ ଆପଣଙ୍କୁ iOS ସେଟିଂସ୍‌କୁ ପଠାଏ ନାହିଁ। ପରେ ଆକ୍ସେସ୍ ଚାଲୁ କରିବାକୁ ଚାହିଁଲେ Demora ର ଅନୁମତି ପ୍ରମ୍ପ୍ଟ ବ୍ୟବହାର କରନ୍ତୁ କିମ୍ବା ନିଜେ iOS ସେଟିଂସ୍ ଖୋଲନ୍ତୁ। ଅନୁମତି ଓ ବ୍ୟାକ୍‌ଗ୍ରାଉଣ୍ଡ୍ କଲ୍‌ବ୍ୟାକ୍ iOS ନିୟନ୍ତ୍ରଣ କରେ, ତେଣୁ ବ୍ଲକ୍ ଏଡ଼ାଇ ହେବ ନାହିଁ ବୋଲି ନିଶ୍ଚିତତା ନୁହେଁ।",
    "Change: %@%%": "ବଦଳ: %@%%",
    "Choose approval permissions separately for each contact. Extra-time permission is opt-in, including for existing contacts, and a limit's extra-time step must also require contact approval. Demora-user contacts accept an invitation before approving in their app. For email approval, enter the short code in your Demora. Permission edits are delay-gated; an approval skips only the eligible request's wait, not every rule.": "ପ୍ରତ୍ୟେକ ଯୋଗାଯୋଗ ପାଇଁ ଅଲଗା ଭାବେ ଅନୁମୋଦନ ଅନୁମତି ବାଛନ୍ତୁ। ଅତିରିକ୍ତ ସମୟର ଅନୁମତି ନିଜେ ବାଛିବାକୁ ହୁଏ, ବିଦ୍ୟମାନ ଯୋଗାଯୋଗ ପାଇଁ ମଧ୍ୟ, ଏବଂ ସୀମାର ଅତିରିକ୍ତ-ସମୟ ଧାପରେ ମଧ୍ୟ ଯୋଗାଯୋଗର ଅନୁମୋଦନ ଲାଗିବ। Demora ବ୍ୟବହାରକାରୀ ଯୋଗାଯୋଗ ନିଜ ଆପ୍‌ରେ ଅନୁମୋଦନ କରିବା ପୂର୍ବରୁ ନିମନ୍ତ୍ରଣ ଗ୍ରହଣ କରନ୍ତି। ଇମେଲ୍ ଅନୁମୋଦନ ପାଇଁ ଛୋଟ କୋଡ୍ ଆପଣଙ୍କ Demora ରେ ଦିଅନ୍ତୁ। ଅନୁମତି ବଦଳ ବିଳମ୍ବିତ; ଅନୁମୋଦନ କେବଳ ସେହି ଅନୁରୋଧର ଅପେକ୍ଷା ଏଡ଼ାଏ, ସବୁ ନିୟମ ନୁହେଁ।",
    "Completed-day comparison": "ସମ୍ପୂର୍ଣ୍ଣ ଦିନର ତୁଳନା",
    "Couldn't save your estimate. Try again.": "ଆପଣଙ୍କ ଅନୁମାନ ସେଭ୍ କରାଯାଇପାରିଲା ନାହିଁ। ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Delay policy": "ଅପେକ୍ଷା ନିୟମ",
    "Expand Split daily budget to divide the allowance into time-of-day portions, with optional carryover of unused early minutes. New limits can use three portions; existing two-portion limits remain editable. Spending an early portion blocks until its next boundary, even if later portions have minutes left. Editing a spent limit does not give it a fresh daily allowance. Selection edits follow the less-strict delay and can discard free-period credit tied to the old selection.": "ଦିନର ସମୟ ଅନୁସାରେ ଭାଗ କରିବାକୁ ଭାଗ ହୋଇଥିବା ଦୈନିକ ବଜେଟ୍ ଖୋଲନ୍ତୁ; ଅବ୍ୟବହୃତ ପ୍ରାରମ୍ଭିକ ମିନିଟ୍ ଚାହିଁଲେ ଆଗକୁ ନିଆଯାଇପାରେ। ନୂଆ ସୀମାରେ ତିନୋଟି ଭାଗ ରହିପାରେ; ବିଦ୍ୟମାନ ଦୁଇ-ଭାଗ ସୀମା ଏବେ ବି ସମ୍ପାଦନ ହୋଇପାରେ। ପ୍ରାରମ୍ଭିକ ଭାଗ ଶେଷ ହେଲେ ପରବର୍ତ୍ତୀ ଭାଗରେ ମିନିଟ୍ ବାକି ଥିଲେ ମଧ୍ୟ ପରବର୍ତ୍ତୀ ସୀମା ପର୍ଯ୍ୟନ୍ତ ବ୍ଲକ୍ ରହେ। ଶେଷ ହୋଇଥିବା ସୀମା ସମ୍ପାଦନ କଲେ ନୂଆ ଦୈନିକ ବରାଦ ମିଳେ ନାହିଁ। ବାଛିବା ବଦଳ କମ୍ କଡ଼ା ଅପେକ୍ଷା ମାନେ ଓ ପୁରୁଣା ବାଛିବା ସହ ଯୋଡ଼ା ମୁକ୍ତ-ସମୟ କ୍ରେଡିଟ୍ ହରାଇପାରେ।",
    "Hours and minutes per week, not per day.": "ସପ୍ତାହ ପ୍ରତି ଘଣ୍ଟା ଓ ମିନିଟ୍, ଦିନ ପ୍ରତି ନୁହେଁ।",
    "Notifications & widgets": "ବିଜ୍ଞପ୍ତି ଓ ୱିଜେଟ୍",
    "Partial source coverage": "ଆଂଶିକ ଉତ୍ସ କଭରେଜ୍",
    "Passwords & phrases": "ପାସୱାର୍ଡ ଓ ବାକ୍ୟ",
    "Privacy": "ଗୋପନୀୟତା",
    "Screen Time reports and a personal baseline": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ରିପୋର୍ଟ ଓ ବ୍ୟକ୍ତିଗତ ଆରମ୍ଭ ବିନ୍ଦୁ",
    "Self-reported weekly baseline": "ନିଜେ ଜଣାଇଥିବା ସାପ୍ତାହିକ ଆରମ୍ଭ ବିନ୍ଦୁ",
    "Sleep starts on the selected evening and ends at the following morning's wake-up start, using that morning's custom time. Group edits follow your delay policy. Wake timing edits preserve spent usage, split accounting, extra-time grants and a running wait's deadline; a new wait applies to the next tap. A delayed latest-time change can end today's gate once it applies. Turning the gate off is delay-gated too.": "ନିଦ୍ରା ବାଛିଥିବା ସନ୍ଧ୍ୟାରେ ଆରମ୍ଭ ହୁଏ ଓ ପରବର୍ତ୍ତୀ ସକାଳର ଉଠିବା ଆରମ୍ଭରେ ଶେଷ ହୁଏ, ସେହି ସକାଳର କଷ୍ଟମ୍ ସମୟ ବ୍ୟବହାର କରି। ଗ୍ରୁପ୍ ବଦଳ ଆପଣଙ୍କ ଅପେକ୍ଷା ନିୟମ ମାନେ। ଉଠିବା ସମୟ ବଦଳ ଖର୍ଚ୍ଚ ହୋଇଥିବା ବ୍ୟବହାର, ଭାଗ ହୋଇଥିବା ହିସାବ, ଅତିରିକ୍ତ ସମୟ ଓ ଚାଲୁଥିବା ଅପେକ୍ଷାର ଶେଷ ତାରିଖ ବଜାୟ ରଖେ; ନୂଆ ଅପେକ୍ଷା ପରବର୍ତ୍ତୀ ଟ୍ୟାପ୍ ଠାରୁ ଲାଗୁ ହୁଏ। ବିଳମ୍ବିତ ଶେଷ-ସମୟ ବଦଳ ଲାଗୁ ହେଲେ ଆଜିର ଗେଟ୍ ଶେଷ କରିପାରେ। ଗେଟ୍ ବନ୍ଦ କରିବା ମଧ୍ୟ ଅପେକ୍ଷାଧୀନ।",
    "The app deletion lock asks iOS to prevent deleting apps, including Demora. Turning it off is a less-strict change. It discourages one bypass route but does not make Screen Time permissions or the device impossible to change. Notifications and widgets are optional aids, not the enforcement mechanism.": "ଆପ୍ ମାଡ଼ିବା ଲକ୍ iOS କୁ Demora ସମେତ ଆପ୍ ମାଡ଼ିବାରୁ ରୋକିବାକୁ କହେ। ଏହାକୁ ବନ୍ଦ କରିବା କମ୍ କଡ଼ା ବଦଳ। ଏହା ଗୋଟିଏ ଏଡ଼ାଇବା ବାଟକୁ କଷ୍ଟକର କରେ କିନ୍ତୁ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଅନୁମତି କିମ୍ବା ଡିଭାଇସ୍ ବଦଳାଇବା ଅସମ୍ଭବ କରେ ନାହିଁ। ବିଜ୍ଞପ୍ତି ଓ ୱିଜେଟ୍ ବୈକଳ୍ପିକ ସହାୟକ, ପ୍ରୟୋଗ ବ୍ୟବସ୍ଥା ନୁହେଁ।",
    "Today is not included in this comparison.": "ଏହି ତୁଳନାରେ ଆଜି ଗଣାଯାଏ ନାହିଁ।",
    "Today so far": "ଆଜି ଏପର୍ଯ୍ୟନ୍ତ",
    "Troubleshooting": "ସମସ୍ୟା ସମାଧାନ",
    "Usage reports": "ବ୍ୟବହାର ରିପୋର୍ଟ",
    "Most used apps": "ସବୁଠାରୁ ଅଧିକ ବ୍ୟବହୃତ ଆପ୍",
    "All apps": "ସମସ୍ତ ଆପ୍",
    "Use Prioritize this to apply a rule after rules at default priority, or Restore default priority to undo that choice. Both actions always queue a less-strict change, even if you expect a stricter result. Among prioritized rules, the last one promoted applies last. Priority changes ordering, not a rule's app selection or your spent daily allowance.": "ଡିଫଲ୍ଟ ପ୍ରାଥମିକତା ନିୟମ ପରେ କୌଣସି ନିୟମ ଲାଗୁ କରିବାକୁ ଏହାକୁ ପ୍ରାଥମିକତା ଦିଅନ୍ତୁ ବ୍ୟବହାର କରନ୍ତୁ, ଏବଂ ତାହା ଫେରାଇବାକୁ ଡିଫଲ୍ଟ ପ୍ରାଥମିକତା ଫେରାନ୍ତୁ। ଦୁଇଟି କାମ ସବୁବେଳେ କମ୍ କଡ଼ା ବଦଳ ଭାବେ ଧାଡ଼ିରେ ଯାଏ, କଡ଼ା ଫଳ ଆଶା କଲେ ମଧ୍ୟ। ପ୍ରାଥମିକତା ପାଇଥିବା ନିୟମ ମଧ୍ୟରୁ ଶେଷରେ ପ୍ରାଥମିକତା ଦିଆଯାଇଥିବା ଶେଷରେ ଲାଗୁ ହୁଏ। ପ୍ରାଥମିକତା କ୍ରମ ବଦଳାଏ, ନିୟମର ଆପ୍ ବାଛିବା କିମ୍ବା ଆପଣଙ୍କ ଖର୍ଚ୍ଚ ହୋଇଥିବା ଦୈନିକ ବରାଦ ନୁହେଁ।",
    "Weekly baseline": "ସାପ୍ତାହିକ ଆରମ୍ଭ ବିନ୍ଦୁ",
    "Your starting point": "ଆପଣଙ୍କ ଆରମ୍ଭ ବିନ୍ଦୁ",
    "choose a policy, manage pending changes": "ଏକ ନିୟମ ବାଛନ୍ତୁ, ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ସମ୍ଭାଳନ୍ତୁ",
    "optional reminders and privacy": "ବୈକଳ୍ପିକ ସ୍ମାରକ ଓ ଗୋପନୀୟତା",
    "overlaps, scopes and priority": "ଓଭରଲାପ୍, ପରିସର ଓ ପ୍ରାଥମିକତା",
    "permissions, blank reports and false blocks": "ଅନୁମତି, ଖାଲି ରିପୋର୍ଟ ଓ ଭୁଲ ବ୍ଲକ୍",
    "wake waits, latest times and sleep": "ଉଠିବା ଅପେକ୍ଷା, ଶେଷ ସମୟ ଓ ନିଦ୍ରା",
    "Latest wake-up: %@": "ଉଠିବାର ଶେଷ ସମୟ: %@",
    // Home report controls and default wake-up timing.
    "Expand": "ବିସ୍ତାର କରନ୍ତୁ",
    "Collapse": "ସଂକୁଚିତ କରନ୍ତୁ",
    "Expanded": "ବିସ୍ତାରିତ",
    "Compact": "ସଂକ୍ଷିପ୍ତ",
    "Start your morning": "ଆପଣଙ୍କ ସକାଳ ଆରମ୍ଭ କରନ୍ତୁ",
    "Usage stays in the Screen Time report. Scroll to see more groups. If it looks empty, try Refresh; an empty report does not mean zero usage.": "ବ୍ୟବହାର ସ୍କ୍ରିନ୍ ଟାଇମ୍ ରିପୋର୍ଟ ଭିତରେ ହିଁ ରହେ। ଅଧିକ ଗ୍ରୁପ୍ ଦେଖିବାକୁ ସ୍କ୍ରୋଲ୍ କରନ୍ତୁ। ଖାଲି ଲାଗିଲେ ରିଫ୍ରେସ୍ କରନ୍ତୁ; ଖାଲି ରିପୋର୍ଟର ଅର୍ଥ ଶୂନ୍ୟ ବ୍ୟବହାର ନୁହେଁ।",
    "Days without custom times use the default start, wait and latest time above.": "କଷ୍ଟମ୍ ସମୟ ନଥିବା ଦିନ ଉପରର ଡିଫଲ୍ଟ ଆରମ୍ଭ, ଅପେକ୍ଷା ଓ ଶେଷ ସମୟ ବ୍ୟବହାର କରେ।",
    "Wake-up overlaps are estimates until you tap Wake up. Allowlisted apps still obey other specific blocks and daily limits.": "ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ନକରିବା ପର୍ଯ୍ୟନ୍ତ ଉଠିବା ଓଭରଲାପ୍ ଅନୁମାନ। ଅନୁମୋଦିତ ତାଲିକାର ଆପ୍ ଏବେ ବି ଅନ୍ୟ ନିର୍ଦ୍ଦିଷ୍ଟ ବ୍ଲକ୍ ଓ ଦୈନିକ ସୀମା ମାନେ।",
    "Restore default priority": "ଡିଫଲ୍ଟ ପ୍ରାଥମିକତା ଫେରାନ୍ତୁ",
    // Migration delay choices, wake-up ceilings, and schedule priority.
    "Optional. Keep separate waits, use one shared wait, or tighten immediately and wait only when loosening rules. If you skip this, your delay settings stay unchanged.": "ବୈକଳ୍ପିକ। ଅଲଗା ଅପେକ୍ଷା ରଖନ୍ତୁ, ଗୋଟିଏ ଅପେକ୍ଷା ବ୍ୟବହାର କରନ୍ତୁ, କିମ୍ବା ତୁରନ୍ତ କଡ଼ା କରନ୍ତୁ ଓ କେବଳ ନିୟମ ଢିଲା କଲାବେଳେ ଅପେକ୍ଷା କରନ୍ତୁ। ଛାଡ଼ିଦେଲେ ଆପଣଙ୍କ ଅପେକ୍ଷା ସେଟିଂସ୍ ବଦଳେ ନାହିଁ।",
    "Your saved rules and pending changes are retained. Unless you queue a change, your existing delay settings stay unchanged.": "ଆପଣଙ୍କ ସେଭ୍ ହୋଇଥିବା ନିୟମ ଓ ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ରହେ। ବଦଳ ଧାଡ଼ିରେ ନ ରଖିଲେ ଆପଣଙ୍କ ବିଦ୍ୟମାନ ଅପେକ୍ଷା ସେଟିଂସ୍ ବଦଳେ ନାହିଁ।",
    "Demo only. Try the delay choices here; nothing is queued or saved. Go back to keep exploring the welcome.": "କେବଳ ଡେମୋ। ଏଠାରେ ଅପେକ୍ଷା ବିକଳ୍ପ ଚେଷ୍ଟା କରନ୍ତୁ; କିଛି ଧାଡ଼ିରେ ଯାଏ ନାହିଁ କି ସେଭ୍ ହୁଏ ନାହିଁ। ସ୍ୱାଗତ ଆଉ ଦେଖିବାକୁ ପଛକୁ ଯାଆନ୍ତୁ।",
    "A new wait applies to the next tap. A latest wake-up time can end today's gate once this delayed change applies. Turning this off still follows your less-strict delay.": "ନୂଆ ଅପେକ୍ଷା ପରବର୍ତ୍ତୀ ଟ୍ୟାପ୍ ଠାରୁ ଲାଗୁ ହୁଏ। ଏହି ବିଳମ୍ବିତ ବଦଳ ଲାଗୁ ହେଲେ ଉଠିବାର ଶେଷ ସମୟ ଆଜିର ଗେଟ୍ ଶେଷ କରିପାରେ। ଏହାକୁ ବନ୍ଦ କରିବା ମଧ୍ୟ ଆପଣଙ୍କ କମ୍ କଡ଼ା ଅପେକ୍ଷା ମାନେ।",
    "A running wait keeps its deadline, but never extends past its configured latest wake-up time. Other blocks still apply.": "ଚାଲୁଥିବା ଅପେକ୍ଷା ତାହାର ଶେଷ ତାରିଖ ରଖେ, କିନ୍ତୁ ଠିକ୍ କରାଯାଇଥିବା ଉଠିବାର ଶେଷ ସମୟ ଅତିକ୍ରମ କରେ ନାହିଁ। ଅନ୍ୟ ବ୍ଲକ୍ ଏବେ ବି ଲାଗୁ।",
    "Set a latest wake-up time": "ଉଠିବାର ଶେଷ ସମୟ ଠିକ୍ କରନ୍ତୁ",
    "Wake blocking ends by": "ଉଠିବା ବ୍ଲକ୍ ସୁଦ୍ଧା ଶେଷ ହୁଏ",
    "At this time, this wake-up block ends even if you haven't tapped Wake up or its wait is still running.": "ଏହି ସମୟରେ ଏହି ଉଠିବା ବ୍ଲକ୍ ଶେଷ ହୁଏ, ଆପଣ ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ନକଲେ କିମ୍ବା ଅପେକ୍ଷା ଚାଲିଥିଲେ ମଧ୍ୟ।",
    "Choose a latest time after the wake-up day begins.": "ଉଠିବା ଦିନ ଆରମ୍ଭ ପରର ଏକ ଶେଷ ସମୟ ବାଛନ୍ତୁ।",
    "Prioritize %@": "%@ କୁ ପ୍ରାଥମିକତା ଦିଅନ୍ତୁ",
    "Restore default priority for %@": "%@ ପାଇଁ ଡିଫଲ୍ଟ ପ୍ରାଥମିକତା ଫେରାନ୍ତୁ",
    "Schedule conflicts": "ସମୟସୂଚୀ ସଂଘର୍ଷ",
    "Potential overlaps": "ସମ୍ଭାବ୍ୟ ଓଭରଲାପ୍",
    "No conflicting schedules found.": "କୌଣସି ସଂଘର୍ଷକାରୀ ସମୟସୂଚୀ ମିଳିଲା ନାହିଁ।",
    "Default order: wake-up → recurring → planned → sessions.": "ଡିଫଲ୍ଟ କ୍ରମ: ଉଠିବା → ପୁନରାବୃତ୍ତ → ଯୋଜିତ → ସେସନ୍।",
    "Prioritize this": "ଏହାକୁ ପ୍ରାଥମିକତା ଦିଅନ୍ତୁ",
    "Default priority": "ଡିଫଲ୍ଟ ପ୍ରାଥମିକତା",
    "Prioritized": "ପ୍ରାଥମିକତା ପ୍ରାପ୍ତ",
    "Priority changes follow your less-strict delay.": "ପ୍ରାଥମିକତା ବଦଳ ଆପଣଙ୍କ କମ୍ କଡ଼ା ଅପେକ୍ଷା ମାନେ।",
    "When several rules are prioritized, the last one promoted is applied last.": "ଅନେକ ନିୟମକୁ ପ୍ରାଥମିକତା ଦିଆଗଲେ ଶେଷରେ ପ୍ରାଥମିକତା ଦିଆଯାଇଥିବା ଶେଷରେ ଲାଗୁ ହୁଏ।",
    "These rules overlap in time. Apple hides category membership, so some app overlaps cannot be confirmed.": "ଏହି ନିୟମ ସମୟରେ ଓଭରଲାପ୍ ହୁଏ। Apple ଶ୍ରେଣୀ ସଦସ୍ୟତା ଲୁଚାଏ, ତେଣୁ କେତେକ ଆପ୍ ଓଭରଲାପ୍ ନିଶ୍ଚିତ କରାଯାଇପାରେ ନାହିଁ।",
    "Next occurrence": "ପରବର୍ତ୍ତୀ ଘଟଣା",
    "Possible overlap": "ସମ୍ଭାବ୍ୟ ଓଭରଲାପ୍",
    "Applies last": "ଶେଷରେ ଲାଗୁ",
    "Priority": "ପ୍ରାଥମିକତା",
    "See overlapping rules": "ଓଭରଲାପ୍ ହେଉଥିବା ନିୟମ ଦେଖନ୍ତୁ",
    "Change wake-up schedule for %@": "%@ ପାଇଁ ଉଠିବା ସମୟସୂଚୀ ବଦଳାନ୍ତୁ",
    "Customize wake-up by day": "ଦିନ ଅନୁସାରେ ଉଠିବା କଷ୍ଟମାଇଜ୍ କରନ୍ତୁ",
    "Days without custom times use the default start and wait above.": "କଷ୍ଟମ୍ ସମୟ ନଥିବା ଦିନ ଉପରର ଡିଫଲ୍ଟ ଆରମ୍ଭ ଓ ଅପେକ୍ଷା ବ୍ୟବହାର କରେ।",
    "A wake-up wait already in progress keeps its original deadline.": "ଆଗରୁ ଚାଲୁଥିବା ଉଠିବା ଅପେକ୍ଷା ତାହାର ମୂଳ ଶେଷ ତାରିଖ ରଖେ।",
    "Give each limit or group its own wake-up start, wait and weekdays. One Wake up tap starts all eligible waits. Overlapping rules still apply.": "ପ୍ରତ୍ୟେକ ସୀମା କିମ୍ବା ଗ୍ରୁପ୍‌କୁ ନିଜସ୍ୱ ଉଠିବା ଆରମ୍ଭ, ଅପେକ୍ଷା ଓ ସପ୍ତାହର ଦିନ ଦିଅନ୍ତୁ। ଗୋଟିଏ ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ସମସ୍ତ ଯୋଗ୍ୟ ଅପେକ୍ଷା ଆରମ୍ଭ କରେ। ଓଭରଲାପ୍ ହେଉଥିବା ନିୟମ ଏବେ ବି ଲାଗୁ।",
    "Sleep ends at the following wake-up start, using that day's custom time if set.": "ନିଦ୍ରା ପରବର୍ତ୍ତୀ ଉଠିବା ଆରମ୍ଭରେ ଶେଷ ହୁଏ, ସେହି ଦିନର କଷ୍ଟମ୍ ସମୟ ଥିଲେ ତାହା ବ୍ୟବହାର କରି।",
    "Custom wake-up times by day": "ଦିନ ଅନୁସାରେ କଷ୍ଟମ୍ ଉଠିବା ସମୟ",
    "Discard day/night drafts": "ଦିନ/ରାତି ଡ୍ରାଫ୍ଟ ପ୍ରତ୍ୟାଖ୍ୟାନ କରନ୍ତୁ",
    // Named day/night groups, shared wake-up, and additive setup.
    "%d apps, %d categories, %d websites": "%d ଟି ଆପ୍, %d ଟି ଶ୍ରେଣୀ, %d ଟି ୱେବସାଇଟ୍",
    "%d day/night groups": "%d ଟି ଦିନ/ରାତି ଗ୍ରୁପ୍",
    "%d limits · %d apps, %d categories, %d websites": "%d ଟି ସୀମା · %d ଟି ଆପ୍, %d ଟି ଶ୍ରେଣୀ, %d ଟି ୱେବସାଇଟ୍",
    "A change for this group is pending. Its current rules stay in place until that change applies.": "ଏହି ଗ୍ରୁପ୍‌ର ଏକ ବଦଳ ଅପେକ୍ଷାରେ ଅଛି। ତାହା ଲାଗୁ ନହେବା ପର୍ଯ୍ୟନ୍ତ ଏହାର ବର୍ତ୍ତମାନର ନିୟମ ରହେ।",
    "Add a group to give its apps their own wake-up wait and sleep time.": "ଗ୍ରୁପ୍‌ର ଆପ୍‌କୁ ନିଜସ୍ୱ ଉଠିବା ଅପେକ୍ଷା ଓ ନିଦ୍ରା ସମୟ ଦେବାକୁ ଏକ ଗ୍ରୁପ୍ ଯୋଡ଼ନ୍ତୁ।",
    "Add day/night group": "ଦିନ/ରାତି ଗ୍ରୁପ୍ ଯୋଡ଼ନ୍ତୁ",
    "All other apps except…": "ଅନ୍ୟ ସମସ୍ତ ଆପ୍, ଏଗୁଡ଼ିକ ବ୍ୟତୀତ…",
    "An all-other-apps fallback automatically excludes apps targeted by your named selected groups. Category-based groups cannot be combined with this fallback.": "ଅନ୍ୟ-ସମସ୍ତ-ଆପ୍ ଫଲବ୍ୟାକ୍ ଆପଣଙ୍କ ନାମିତ ଗ୍ରୁପ୍‌ର ଆପ୍ ନିଜେ ନିଜେ ବାଦ୍ ଦିଏ। ଶ୍ରେଣୀ-ଆଧାରିତ ଗ୍ରୁପ୍ ଏହି ଫଲବ୍ୟାକ୍ ସହ ମିଶାଯାଇପାରେ ନାହିଁ।",
    "App scope": "ଆପ୍ ପରିସର",
    "App selection is unavailable until Screen Time access is allowed.": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଅନୁମତି ନମିଳିବା ପର୍ଯ୍ୟନ୍ତ ଆପ୍ ବାଛିବା ଉପଲବ୍ଧ ନୁହେଁ।",
    "Apps to exclude": "ବାଦ୍ ଦେବାକୁ ଥିବା ଆପ୍",
    "Category exceptions are not supported. Choose individual apps or limits without categories; choosing a category cannot allow all of its apps.": "ଶ୍ରେଣୀ ବ୍ୟତିକ୍ରମ ସମର୍ଥିତ ନୁହେଁ। ଶ୍ରେଣୀ ବିନା ଅଲଗା ଆପ୍ କିମ୍ବା ସୀମା ବାଛନ୍ତୁ; ଶ୍ରେଣୀ ବାଛିଲେ ତାହାର ସମସ୍ତ ଆପ୍‌କୁ ଅନୁମତି ଦିଆଯାଇପାରେ ନାହିଁ।",
    "Check existing limits and choose extra apps for this group's boundaries.": "ବିଦ୍ୟମାନ ସୀମା ଦେଖନ୍ତୁ ଓ ଏହି ଗ୍ରୁପ୍‌ର ସୀମା ପାଇଁ ଅତିରିକ୍ତ ଆପ୍ ବାଛନ୍ତୁ।",
    "Choose a name, at least one boundary, weekdays and a valid app scope. Sleep and wake-up times must differ.": "ଏକ ନାମ, ଅତି କମରେ ଗୋଟିଏ ସୀମା, ସପ୍ତାହର ଦିନ ଓ ବୈଧ ଆପ୍ ପରିସର ବାଛନ୍ତୁ। ନିଦ୍ରା ଓ ଉଠିବା ସମୟ ଅଲଗା ହେବା ଜରୁରୀ।",
    "Contains categories — cannot be a fallback exception.": "ଶ୍ରେଣୀ ଅଛି — ଫଲବ୍ୟାକ୍ ବ୍ୟତିକ୍ରମ ହୋଇପାରିବ ନାହିଁ।",
    "Day/night group": "ଦିନ/ରାତି ଗ୍ରୁପ୍",
    "Demo: select sample limits above. The real app picker is not opened.": "ଡେମୋ: ଉପରେ ନମୁନା ସୀମା ବାଛନ୍ତୁ। ପ୍ରକୃତ ଆପ୍ ପିକର୍ ଖୋଲେ ନାହିଁ।",
    "Existing limits": "ବିଦ୍ୟମାନ ସୀମା",
    "Existing sleep settings": "ବିଦ୍ୟମାନ ନିଦ୍ରା ସେଟିଂସ୍",
    "Existing wake-up settings": "ବିଦ୍ୟମାନ ଉଠିବା ସେଟିଂସ୍",
    "Existing wake/sleep settings": "ବିଦ୍ୟମାନ ଉଠିବା/ନିଦ୍ରା ସେଟିଂସ୍",
    "Extra apps": "ଅତିରିକ୍ତ ଆପ୍",
    "Give each group its own wake-up wait and sleep time.": "ପ୍ରତ୍ୟେକ ଗ୍ରୁପ୍‌କୁ ନିଜସ୍ୱ ଉଠିବା ଅପେକ୍ଷା ଓ ନିଦ୍ରା ସମୟ ଦିଅନ୍ତୁ।",
    "Limits to exclude": "ବାଦ୍ ଦେବାକୁ ଥିବା ସୀମା",
    "No existing limits. You can choose apps below.": "କୌଣସି ବିଦ୍ୟମାନ ସୀମା ନାହିଁ। ତଳେ ଆପ୍ ବାଛିପାରିବେ।",
    "Not selected": "ବଛା ହୋଇ ନାହିଁ",
    "One Wake up tap on Today starts every eligible group's wait together. Each group unlocks after its own wait; sleep blocking ends at its wake-up start time.": "ଆଜି ରେ ଗୋଟିଏ ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ସମସ୍ତ ଯୋଗ୍ୟ ଗ୍ରୁପ୍‌ର ଅପେକ୍ଷା ଏକାଠି ଆରମ୍ଭ କରେ। ପ୍ରତ୍ୟେକ ଗ୍ରୁପ୍ ନିଜ ଅପେକ୍ଷା ପରେ ଖୋଲେ; ନିଦ୍ରା ବ୍ଲକ୍ ତାହାର ଉଠିବା ଆରମ୍ଭ ସମୟରେ ଶେଷ ହୁଏ।",
    "Only one all-other-apps fallback is allowed.": "ଅନ୍ୟ-ସମସ୍ତ-ଆପ୍‌ର କେବଳ ଗୋଟିଏ ଫଲବ୍ୟାକ୍ ଅନୁମୋଦିତ।",
    "Optional — add day/night groups now, or set them up later in Rules.": "ବୈକଳ୍ପିକ — ଏବେ ଦିନ/ରାତି ଗ୍ରୁପ୍ ଯୋଡ଼ନ୍ତୁ, କିମ୍ବା ପରେ ନିୟମ ରେ ସେଟ୍ କରନ୍ତୁ।",
    "Overlapping rules use the strictest boundary. An exception here does not bypass another group or limit.": "ଓଭରଲାପ୍ ହେଉଥିବା ନିୟମ ସବୁଠାରୁ କଡ଼ା ସୀମା ବ୍ୟବହାର କରେ। ଏଠାର ବ୍ୟତିକ୍ରମ ଅନ୍ୟ ଗ୍ରୁପ୍ କି ସୀମାକୁ ଏଡ଼ାଏ ନାହିଁ।",
    "Remove category exceptions": "ଶ୍ରେଣୀ ବ୍ୟତିକ୍ରମ ହଟାନ୍ତୁ",
    "Remove category exceptions before saving this fallback group.": "ଏହି ଫଲବ୍ୟାକ୍ ଗ୍ରୁପ୍ ସେଭ୍ କରିବା ପୂର୍ବରୁ ଶ୍ରେଣୀ ବ୍ୟତିକ୍ରମ ହଟାନ୍ତୁ।",
    "Remove day/night group?": "ଦିନ/ରାତି ଗ୍ରୁପ୍ ହଟାଇବେ?",
    "Remove group": "ଗ୍ରୁପ୍ ହଟାନ୍ତୁ",
    "Remove missing limits": "ନଥିବା ସୀମା ହଟାନ୍ତୁ",
    "Review these groups: choose valid apps, timings and exceptions before continuing.": "ଏହି ଗ୍ରୁପ୍ ଦେଖନ୍ତୁ: ଆଗକୁ ବଢ଼ିବା ପୂର୍ବରୁ ବୈଧ ଆପ୍, ସମୟ ଓ ବ୍ୟତିକ୍ରମ ବାଛନ୍ତୁ।",
    "Selected": "ବଛା",
    "Selected limits and extra apps": "ବଛା ସୀମା ଓ ଅତିରିକ୍ତ ଆପ୍",
    "Sleep %@–%@": "ନିଦ୍ରା %@–%@",
    "Some selected limits no longer exist. Remove their references before saving.": "କେତେକ ବଛା ସୀମା ଆଉ ନାହିଁ। ସେଭ୍ କରିବା ପୂର୍ବରୁ ସେଗୁଡ଼ିକର ଉଲ୍ଲେଖ ହଟାନ୍ତୁ।",
    "The all-other-apps fallback cannot exclude whole categories used by these groups: %@. Choose individual apps instead, or remove the fallback.": "ଅନ୍ୟ-ସମସ୍ତ-ଆପ୍ ଫଲବ୍ୟାକ୍ ଏହି ଗ୍ରୁପ୍ ବ୍ୟବହାର କରୁଥିବା ସମ୍ପୂର୍ଣ୍ଣ ଶ୍ରେଣୀ ବାଦ୍ ଦେଇପାରେ ନାହିଁ: %@। ବଦଳରେ ଅଲଗା ଆପ୍ ବାଛନ୍ତୁ, କିମ୍ବା ଫଲବ୍ୟାକ୍ ହଟାନ୍ତୁ।",
    "The fallback automatically excludes apps targeted by your other named day/night groups. Check limits and choose individual apps for additional exceptions. Other rules still apply.": "ଫଲବ୍ୟାକ୍ ଆପଣଙ୍କ ଅନ୍ୟ ନାମିତ ଦିନ/ରାତି ଗ୍ରୁପ୍‌ର ଆପ୍ ନିଜେ ନିଜେ ବାଦ୍ ଦିଏ। ସୀମା ଦେଖନ୍ତୁ ଓ ଅତିରିକ୍ତ ବ୍ୟତିକ୍ରମ ପାଇଁ ଅଲଗା ଆପ୍ ବାଛନ୍ତୁ। ଅନ୍ୟ ନିୟମ ଏବେ ବି ଲାଗୁ।",
    "These existing settings still apply alongside your day/night groups.": "ଏହି ବିଦ୍ୟମାନ ସେଟିଂସ୍ ଆପଣଙ୍କ ଦିନ/ରାତି ଗ୍ରୁପ୍ ପାଖରେ ଏବେ ବି ଲାଗୁ।",
    "This group could not be saved. Review pending changes and your app selection, then try again.": "ଏହି ଗ୍ରୁପ୍ ସେଭ୍ କରାଯାଇପାରିଲା ନାହିଁ। ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ଓ ଆପଣଙ୍କ ଆପ୍ ବାଛିବା ଦେଖି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Use a name of 80 characters or fewer.": "୮୦ ଅକ୍ଷର କିମ୍ବା କମ୍ ନାମ ବ୍ୟବହାର କରନ୍ତୁ।",
    "Wait for the pending day/night change before adding, editing or removing another group.": "ଅନ୍ୟ ଏକ ଗ୍ରୁପ୍ ଯୋଡ଼ିବା, ସମ୍ପାଦନ କରିବା କିମ୍ବା ହଟାଇବା ପୂର୍ବରୁ ଅପେକ୍ଷାରେ ଥିବା ଦିନ/ରାତି ବଦଳ ପାଇଁ ଅପେକ୍ଷା କରନ୍ତୁ।",
    "Wake from %@ · wait %d minutes after tap": "%@ ରୁ ଉଠନ୍ତୁ · ଟ୍ୟାପ୍ ପରେ %d ମିନିଟ୍ ଅପେକ୍ଷା",
    "Weekdays apply to the wake-up morning and the evening when sleep begins.": "ସପ୍ତାହର ଦିନ ଉଠିବା ସକାଳ ଓ ନିଦ୍ରା ଆରମ୍ଭ ସନ୍ଧ୍ୟାରେ ଲାଗୁ ହୁଏ।",
    "You can create up to five day/night groups.": "ଆପଣ ସର୍ବାଧିକ ପାଞ୍ଚଟି ଦିନ/ରାତି ଗ୍ରୁପ୍ ବନାଇପାରିବେ।",
    "e.g. Social apps at night": "ଯଥା ରାତିରେ ସୋସିଆଲ୍ ଆପ୍",
    "Wake-up tap needed": "ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ଦରକାର",
    "Wake-up could not be saved. Try again.": "ଉଠିବା ସେଭ୍ କରାଯାଇପାରିଲା ନାହିଁ। ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Make room for your mornings and nights.": "ଆପଣଙ୍କ ସକାଳ ଓ ରାତି ପାଇଁ ଜାଗା କରନ୍ତୁ।",
    "Optional: choose your limit groups and extra apps, then give each day/night group its own timing. One Wake up tap starts all eligible waits.": "ବୈକଳ୍ପିକ: ଆପଣଙ୍କ ସୀମା ଗ୍ରୁପ୍ ଓ ଅତିରିକ୍ତ ଆପ୍ ବାଛନ୍ତୁ, ତା’ପରେ ପ୍ରତ୍ୟେକ ଦିନ/ରାତି ଗ୍ରୁପ୍‌କୁ ନିଜସ୍ୱ ସମୟ ଦିଅନ୍ତୁ। ଗୋଟିଏ ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ସମସ୍ତ ଯୋଗ୍ୟ ଅପେକ୍ଷା ଆରମ୍ଭ କରେ।",
    "Review your day/night groups after changing your limits.": "ସୀମା ବଦଳାଇବା ପରେ ଆପଣଙ୍କ ଦିନ/ରାତି ଗ୍ରୁପ୍ ଦେଖନ୍ତୁ।",
    "You can change this later in Rules → Day & night. Later changes follow your delays.": "ଏହା ଆପଣ ପରେ ନିୟମ → ଦିନ ଓ ରାତି ରେ ବଦଳାଇପାରିବେ। ପରବର୍ତ୍ତୀ ବଦଳ ଆପଣଙ୍କ ଅପେକ୍ଷା ମାନେ।",
    "One Wake up tap starts all eligible groups together. Give each group its own wait and sleep time.": "ଗୋଟିଏ ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ସମସ୍ତ ଯୋଗ୍ୟ ଗ୍ରୁପ୍ ଏକାଠି ଆରମ୍ଭ କରେ। ପ୍ରତ୍ୟେକ ଗ୍ରୁପ୍‌କୁ ନିଜସ୍ୱ ଅପେକ୍ଷା ଓ ନିଦ୍ରା ସମୟ ଦିଅନ୍ତୁ।",
    "You can add your initial day/night groups now without waiting. Existing rules and wake-up countdowns stay unchanged. Later changes follow your delays.": "ଆପଣ ଏବେ ଅପେକ୍ଷା ନକରି ଆପଣଙ୍କ ପ୍ରଥମ ଦିନ/ରାତି ଗ୍ରୁପ୍ ଯୋଡ଼ିପାରିବେ। ବିଦ୍ୟମାନ ନିୟମ ଓ ଉଠିବା କାଉଣ୍ଟଡାଉନ୍ ବଦଳେ ନାହିଁ। ପରବର୍ତ୍ତୀ ବଦଳ ଆପଣଙ୍କ ଅପେକ୍ଷା ମାନେ।",
    "Your day/night groups are ready.": "ଆପଣଙ୍କ ଦିନ/ରାତି ଗ୍ରୁପ୍ ପ୍ରସ୍ତୁତ।",
    "Add or change day/night group: %@": "ଦିନ/ରାତି ଗ୍ରୁପ୍ ଯୋଡ଼ନ୍ତୁ କିମ୍ବା ବଦଳାନ୍ତୁ: %@",
    "Remove day/night group: %@": "ଦିନ/ରାତି ଗ୍ରୁପ୍ ହଟାନ୍ତୁ: %@",
    "more powerful, more intuitive": "ଅଧିକ ଶକ୍ତିଶାଳୀ, ଅଧିକ ସହଜ",
    // Wake/sleep schedules, group gates, and one-time math-to-phrase replacement.
    "Wake-up for %@: %d minutes": "%@ ପାଇଁ ଉଠିବା: %d ମିନିଟ୍",
    "Turn off wake-up for %@": "%@ ପାଇଁ ଉଠିବା ବନ୍ଦ କରନ୍ତୁ",
    "Review a limit when you're ready; edits still follow your delays.": "ପ୍ରସ୍ତୁତ ହେଲେ ଏକ ସୀମା ଦେଖନ୍ତୁ; ବଦଳ ଏବେ ବି ଆପଣଙ୍କ ଅପେକ୍ଷା ମାନେ।",
    "Add a limit group first.": "ପ୍ରଥମେ ଏକ ସୀମା ଗ୍ରୁପ୍ ଯୋଡ଼ନ୍ତୁ।",
    "Add replacement phrases": "ବଦଳି ବାକ୍ୟ ଯୋଡ଼ନ୍ତୁ",
    "An excluded group still keeps its normal daily limit.": "ବାଦ୍ ଦିଆଯାଇଥିବା ଗ୍ରୁପ୍ ତାହାର ସାଧାରଣ ଦୈନିକ ସୀମା ରଖେ।",
    "Blocking schedule": "ବ୍ଲକ୍ ସମୟସୂଚୀ",
    "Choose what each phrase can approve. This one-time offer covers pending changes, not extra time. Later additions and edits follow your delays.": "ପ୍ରତ୍ୟେକ ବାକ୍ୟ କ’ଣ ଅନୁମୋଦନ କରିପାରିବ ବାଛନ୍ତୁ। ଏହି ଏକ-ଥରର ପ୍ରସ୍ତାବ ଅପେକ୍ଷାରେ ଥିବା ବଦଳକୁ ଆବରେ, ଅତିରିକ୍ତ ସମୟକୁ ନୁହେଁ। ପରବର୍ତ୍ତୀ ଯୋଗ ଓ ବଦଳ ଆପଣଙ୍କ ଅପେକ୍ଷା ମାନେ।",
    "Create a group in Limits & blocks first.": "ପ୍ରଥମେ ସୀମା ଓ ବ୍ଲକ୍ ରେ ଏକ ଗ୍ରୁପ୍ ବନାନ୍ତୁ।",
    "Day & night": "ଦିନ ଓ ରାତି",
    "Days": "ଦିନ",
    "Enable sleep blocking": "ନିଦ୍ରା ବ୍ଲକ୍ ଚାଲୁ କରନ୍ତୁ",
    "Enable wake-up blocking": "ଉଠିବା ବ୍ଲକ୍ ଚାଲୁ କରନ୍ତୁ",
    "Ends at %02d:00, when the wake-up day begins.": "%02d:00 ରେ ଶେଷ ହୁଏ, ଯେତେବେଳେ ଉଠିବା ଦିନ ଆରମ୍ଭ ହୁଏ।",
    "Exclude limit groups from this boundary": "ଏହି ସୀମାରୁ ସୀମା ଗ୍ରୁପ୍ ବାଦ୍ ଦିଅନ୍ତୁ",
    "From math to phrases": "ଗଣିତରୁ ବାକ୍ୟକୁ",
    "General blocks": "ସାଧାରଣ ବ୍ଲକ୍",
    "General wake-up schedule": "ସାଧାରଣ ଉଠିବା ସମୟସୂଚୀ",
    "Get extra time": "ଅତିରିକ୍ତ ସମୟ ପାଆନ୍ତୁ",
    "Give each group its own daily wake-up tap and wait. These group gates begin at midnight; the general schedule has its own start time and weekdays. If both cover an app, both waits apply.": "ପ୍ରତ୍ୟେକ ଗ୍ରୁପ୍‌କୁ ନିଜସ୍ୱ ଦୈନିକ ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ଓ ଅପେକ୍ଷା ଦିଅନ୍ତୁ। ଏହି ଗ୍ରୁପ୍ ଗେଟ୍ ମଧ୍ୟରାତ୍ରିରେ ଆରମ୍ଭ ହୁଏ; ସାଧାରଣ ସମୟସୂଚୀର ନିଜସ୍ୱ ଆରମ୍ଭ ସମୟ ଓ ସପ୍ତାହର ଦିନ ଅଛି। ଦୁହିଁ କୌଣସି ଆପ୍‌କୁ ଆବୃତ କଲେ ଦୁଇ ଅପେକ୍ଷା ଲାଗୁ ହୁଏ।",
    "Group wake-up": "ଗ୍ରୁପ୍ ଉଠିବା",
    "Group wake-up waits": "ଗ୍ରୁପ୍ ଉଠିବା ଅପେକ୍ଷା",
    "Hour": "ଘଣ୍ଟା",
    "Math problems have been replaced with phrases. Since you used math overrides, you can add replacement phrases now without waiting.": "ଗଣିତ ପ୍ରଶ୍ନ ବାକ୍ୟ ଦ୍ୱାରା ବଦଳାଯାଇଛି। ଆପଣ ଗଣିତ ଓଭରରାଇଡ୍ ବ୍ୟବହାର କରିଥିବାରୁ ଏବେ ଅପେକ୍ଷା ନକରି ବଦଳି ବାକ୍ୟ ଯୋଡ଼ିପାରିବେ।",
    "Minute": "ମିନିଟ୍",
    "Next use: %d usage minutes after entering %@": "ପରବର୍ତ୍ତୀ ବ୍ୟବହାର: %2$@ ଟାଇପ୍ କରିବା ପରେ %1$d ବ୍ୟବହାର ମିନିଟ୍",
    "Optional. After this welcome, adding phrases follows your delay settings.": "ବୈକଳ୍ପିକ। ଏହି ସ୍ୱାଗତ ପରେ ବାକ୍ୟ ଯୋଡ଼ିବା ଆପଣଙ୍କ ଅପେକ୍ଷା ସେଟିଂସ୍ ମାନେ।",
    "Recurring session": "ପୁନରାବୃତ୍ତ ସେସନ୍",
    "Refresh": "ରିଫ୍ରେସ୍",
    "See all": "ସବୁ ଦେଖନ୍ତୁ",
    "Selected apps stay usable; other apps are blocked.": "ବଛା ଆପ୍ ବ୍ୟବହାରଯୋଗ୍ୟ ରହେ; ଅନ୍ୟ ଆପ୍ ବ୍ଲକ୍।",
    "Set the usage minutes and gate for each use. Extra time is available only after the full daily limit is spent, and resets at midnight.": "ପ୍ରତ୍ୟେକ ବ୍ୟବହାର ପାଇଁ ବ୍ୟବହାର ମିନିଟ୍ ଓ ଗେଟ୍ ଠିକ୍ କରନ୍ତୁ। ଅତିରିକ୍ତ ସମୟ ସମ୍ପୂର୍ଣ୍ଣ ଦୈନିକ ସୀମା ଶେଷ ହେଲା ପରେ ହିଁ ମିଳେ, ଓ ମଧ୍ୟରାତ୍ରିରେ ରିସେଟ୍ ହୁଏ।",
    "Set weekday allowances. Manage wake-up and sleep in Schedules → Day & night.": "ସପ୍ତାହର ଦିନ ଅନୁସାରେ ବରାଦ ଠିକ୍ କରନ୍ତୁ। ଉଠିବା ଓ ନିଦ୍ରା ସମୟସୂଚୀ → ଦିନ ଓ ରାତି ରେ ସମ୍ଭାଳନ୍ତୁ।",
    "Sleep": "ନିଦ୍ରା",
    "Sleep begins": "ନିଦ୍ରା ଆରମ୍ଭ",
    "Sleep blocking ends at this time, even if the wake-up tap is off.": "ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ବନ୍ଦ ଥିଲେ ମଧ୍ୟ ନିଦ୍ରା ବ୍ଲକ୍ ଏହି ସମୟରେ ଶେଷ ହୁଏ।",
    "The current day's wake-up countdown stays unchanged. A new wait applies to the next tap. Turning this off still waits through your less-strict delay.": "ଆଜିର ଉଠିବା କାଉଣ୍ଟଡାଉନ୍ ବଦଳେ ନାହିଁ। ନୂଆ ଅପେକ୍ଷା ପରବର୍ତ୍ତୀ ଟ୍ୟାପ୍ ଠାରୁ ଲାଗୁ ହୁଏ। ଏହାକୁ ବନ୍ଦ କରିବା ମଧ୍ୟ ଆପଣଙ୍କ କମ୍ କଡ଼ା ଅପେକ୍ଷା ଦେଇ ଯାଏ।",
    "This week": "ଏହି ସପ୍ତାହ",
    "Unavailable password": "ଅନୁପଲବ୍ଧ ପାସୱାର୍ଡ",
    "Usage already spent, split budgets and extra-time grants are not reset by this change.": "ଏହି ବଦଳ ଦ୍ୱାରା ଆଗରୁ ଖର୍ଚ୍ଚ ହୋଇଥିବା ବ୍ୟବହାର, ଭାଗ ହୋଇଥିବା ବଜେଟ୍ ଓ ଅତିରିକ୍ତ-ସମୟ ବରାଦ ରିସେଟ୍ ହୁଏ ନାହିଁ।",
    "Use these phrases now": "ଏହି ବାକ୍ୟ ଏବେ ବ୍ୟବହାର କରନ୍ତୁ",
    "Wait": "ଅପେକ୍ଷା",
    "Wait after tapping Wake up": "ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ପରେ ଅପେକ୍ଷା",
    "Wait for the pending wake/sleep change before editing another.": "ଅନ୍ୟ ଏକ ସମ୍ପାଦନ ପୂର୍ବରୁ ଅପେକ୍ଷାରେ ଥିବା ଉଠିବା/ନିଦ୍ରା ବଦଳ ପାଇଁ ଅପେକ୍ଷା କରନ୍ତୁ।",
    "Wait for this group's pending change before editing its wake-up wait.": "ଏହି ଗ୍ରୁପ୍‌ର ଉଠିବା ଅପେକ୍ଷା ସମ୍ପାଦନ ପୂର୍ବରୁ ଏହାର ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ପାଇଁ ଅପେକ୍ଷା କରନ୍ତୁ।",
    "Wake-up day begins": "ଉଠିବା ଦିନ ଆରମ୍ଭ ହୁଏ",
    "Wake-up time must differ from when sleep begins.": "ଉଠିବା ସମୟ ନିଦ୍ରା ଆରମ୍ଭ ସମୟ ଠାରୁ ଅଲଗା ହେବା ଜରୁରୀ।",
    "Wake-up wait": "ଉଠିବା ଅପେକ୍ଷା",
    "What to block": "କ’ଣ ବ୍ଲକ୍ କରିବେ",
    "Wrong password or this extra-time use is no longer available.": "ଭୁଲ ପାସୱାର୍ଡ, କିମ୍ବା ଅତିରିକ୍ତ ସମୟର ଏହି ବ୍ୟବହାର ଆଉ ଉପଲବ୍ଧ ନୁହେଁ।",
    "Your replacement phrases are ready.": "ଆପଣଙ୍କ ବଦଳି ବାକ୍ୟ ପ୍ରସ୍ତୁତ।",
    "block only or block except": "କେବଳ ବ୍ଲକ୍ କିମ୍ବା ଏଗୁଡ଼ିକ ବ୍ୟତୀତ ବ୍ଲକ୍",
    "iOS cannot exempt an entire app category from 'block except'; category-based groups cannot be excluded here.": "iOS ସମ୍ପୂର୍ଣ୍ଣ ଆପ୍ ଶ୍ରେଣୀକୁ 'ଏଗୁଡ଼ିକ ବ୍ୟତୀତ ବ୍ଲକ୍' ରୁ ବାଦ୍ ଦେଇପାରେ ନାହିଁ; ଶ୍ରେଣୀ-ଆଧାରିତ ଗ୍ରୁପ୍ ଏଠାରେ ବାଦ୍ ଦିଆଯାଇପାରିବ ନାହିଁ।",
    "repeat a break from limits": "ସୀମାରୁ ବିରତି ପୁନରାବୃତ୍ତ କରନ୍ତୁ",
    "start time, weekdays, apps and default wait": "ଆରମ୍ଭ ସମୟ, ସପ୍ତାହର ଦିନ, ଆପ୍ ଓ ଡିଫଲ୍ଟ ଅପେକ୍ଷା",
    // Demora 2.0: delay modes, setup, welcome, and safe recovery.
    "%d of %d": "%d / %d",
    "A change can wait without taking away your ability to choose.": "ବାଛିବାର କ୍ଷମତା ନକାଢ଼ି ଏକ ବଦଳ ଅପେକ୍ଷା କରିପାରେ।",
    "A clearer place for your intentions.": "ଆପଣଙ୍କ ଉଦ୍ଦେଶ୍ୟ ପାଇଁ ଅଧିକ ସ୍ପଷ୍ଟ ସ୍ଥାନ।",
    "A new layout. The same idea: your considered choices deserve time to hold.": "ନୂଆ ବିନ୍ୟାସ। ସମାନ ଭାବନା: ଆପଣଙ୍କ ଭାବି ନେଇଥିବା ପସନ୍ଦ ଟିକିବାକୁ ସମୟ ପାଇବା ଉଚିତ।",
    "A note about older features": "ପୁରୁଣା ସୁବିଧା ବିଷୟରେ ଏକ ଟିପ୍ପଣୀ",
    "A pause, on your terms.": "ଆପଣଙ୍କ ସର୍ତ୍ତରେ ଏକ ବିରତି।",
    "App color": "ଆପ୍ ର ରଙ୍ଗ",
    "Blue": "ନୀଳ",
    "Carried with you": "ଆପଣଙ୍କ ସହ ସବୁଠାରେ",
    "Change delays: %@": "ଅପେକ୍ଷା ବଦଳାନ୍ତୁ: %@",
    "Changes still wait": "ବଦଳ ଏବେ ବି ଅପେକ୍ଷା କରେ",
    "Changing your delay mode follows your current delays. Countdowns already running keep their original deadline.": "ଆପଣଙ୍କ ଅପେକ୍ଷା ଧରଣ ବଦଳାଇବା ଆପଣଙ୍କ ବର୍ତ୍ତମାନର ଅପେକ୍ଷା ମାନେ। ଚାଲୁଥିବା କାଉଣ୍ଟଡାଉନ୍ ସେମାନଙ୍କ ମୂଳ ଶେଷ ତାରିଖ ରଖେ।",
    "Choose a delay of at least one minute.": "ଅତି କମରେ ଏକ ମିନିଟ୍‌ର ଅପେକ୍ଷା ବାଛନ୍ତୁ।",
    "Choose a different wait for tightening and loosening your rules.": "ନିୟମ କଡ଼ା ଓ ଢିଲା କରିବା ପାଇଁ ଅଲଗା ଅପେକ୍ଷା ବାଛନ୍ତୁ।",
    "Choose separate waits, one shared wait, or a wait only when loosening rules.": "ଅଲଗା ଅପେକ୍ଷା, ଗୋଟିଏ ଅପେକ୍ଷା, କିମ୍ବା କେବଳ ନିୟମ ଢିଲା କଲାବେଳେ ଅପେକ୍ଷା ବାଛନ୍ତୁ।",
    "Choose what each trusted contact can approve, instead of giving everyone the same permissions.": "ସମସ୍ତଙ୍କୁ ସମାନ ଅନୁମତି ନଦେଇ ପ୍ରତ୍ୟେକ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି କ’ଣ ଅନୁମୋଦନ କରିପାରିବେ ବାଛନ୍ତୁ।",
    "Choose your boundaries now. Give yourself time before changing them later.": "ଏବେ ଆପଣଙ୍କ ସୀମା ବାଛନ୍ତୁ। ପରେ ବଦଳାଇବା ପୂର୍ବରୁ ନିଜକୁ ସମୟ ଦିଅନ୍ତୁ।",
    "Daily allowance": "ଦୈନିକ ବରାଦ",
    "Daily allowance: %d min": "ଦୈନିକ ବରାଦ: %d ମି",
    "Daily boundaries in Limits. Recurring and planned time in Schedules.": "ଦୈନିକ ସୀମା ସୀମା ରେ। ପୁନରାବୃତ୍ତ ଓ ଯୋଜିତ ସମୟ ସମୟସୂଚୀ ରେ।",
    "Decide with a clear head": "ସଫା ମୁଣ୍ଡରେ ନିଷ୍ପତ୍ତି ନିଅନ୍ତୁ",
    "Delay for every change": "ପ୍ରତ୍ୟେକ ବଦଳ ପାଇଁ ଅପେକ୍ଷା",
    "Demora 2.0": "Demora 2.0",
    "Demora could not finish reading or backing up your saved setup. Nothing has been reset. Try again, or contact hello@getdemora.app before reinstalling.": "Demora ଆପଣଙ୍କ ସେଭ୍ ହୋଇଥିବା ସେଟଅପ୍ ପଢ଼ିବା କିମ୍ବା ବ୍ୟାକଅପ୍ ଶେଷ କରିପାରିଲା ନାହିଁ। କିଛି ରିସେଟ୍ ହୋଇ ନାହିଁ। ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ, କିମ୍ବା ପୁନଃ ଇନଷ୍ଟଲ୍ ପୂର୍ବରୁ hello@getdemora.app କୁ ଯୋଗାଯୋଗ କରନ୍ତୁ।",
    "Different days, different budgets": "ଅଲଗା ଦିନ, ଅଲଗା ବଜେଟ୍",
    "Edit your selection": "ଆପଣଙ୍କ ବାଛିବା ସମ୍ପାଦନ କରନ୍ତୁ",
    "Editing override permissions follows your delays. This welcome doesn't change them.": "ଓଭରରାଇଡ୍ ଅନୁମତି ସମ୍ପାଦନ ଆପଣଙ୍କ ଅପେକ୍ଷା ମାନେ। ଏହି ସ୍ୱାଗତ ସେମାନଙ୍କୁ ବଦଳାଏ ନାହିଁ।",
    "Every change": "ପ୍ରତ୍ୟେକ ବଦଳ",
    "Existing contacts keep their pending-change permissions. They don't automatically gain extra-time access.": "ବିଦ୍ୟମାନ ଯୋଗାଯୋଗ ଅପେକ୍ଷାରେ ଥିବା ବଦଳର ଅନୁମତି ରଖନ୍ତି। ସେମାନେ ଅତିରିକ୍ତ ସମୟ ଆକ୍ସେସ୍ ନିଜେ ନିଜେ ପାଆନ୍ତି ନାହିଁ।",
    "Extra time with intention": "ଭାବିଚିନ୍ତି ଅତିରିକ୍ତ ସମୟ",
    "Free. No account, ads, or analytics. Your app choices and usage stay on your device.": "ମାଗଣା। କୌଣସି ଖାତା, ବିଜ୍ଞାପନ କିମ୍ବା ଆନାଲିଟିକ୍ସ ନାହିଁ। ଆପଣଙ୍କ ଆପ୍ ବାଛିବା ଓ ବ୍ୟବହାର ଆପଣଙ୍କ ଡିଭାଇସ୍‌ରେ ହିଁ ରହେ।",
    "Give your day a little shape.": "ଆପଣଙ୍କ ଦିନକୁ ଟିକେ ଆକାର ଦିଅନ୍ତୁ।",
    "How changes wait": "ବଦଳ କିପରି ଅପେକ୍ଷା କରେ",
    "Immediately": "ତୁରନ୍ତ",
    "Keep a simple daily allowance, or make a limit fit the way your day unfolds.": "ଏକ ସରଳ ଦୈନିକ ବରାଦ ରଖନ୍ତୁ, କିମ୍ବା ସୀମାକୁ ଆପଣଙ୍କ ଦିନର ଗତି ସହ ମେଳାନ୍ତୁ।",
    "Keep separate waits, use one shared wait, or wait only when loosening rules. Your current delay mode and durations stay unchanged.": "ଅଲଗା ଅପେକ୍ଷା ରଖନ୍ତୁ, ଗୋଟିଏ ଅପେକ୍ଷା ବ୍ୟବହାର କରନ୍ତୁ, କିମ୍ବା କେବଳ ନିୟମ ଢିଲା କଲାବେଳେ ଅପେକ୍ଷା କରନ୍ତୁ। ଆପଣଙ୍କ ବର୍ତ୍ତମାନର ଅପେକ୍ଷା ଧରଣ ଓ ସମୟ ବଦଳେ ନାହିଁ।",
    "Language & appearance": "ଭାଷା ଓ ଦୃଶ୍ୟ",
    "Legacy usage-burst pacing and math overrides have been removed. Daily limits remain. Split budgets and extra-time steps are optional alternatives, not automatic replacements.": "ପୁରୁଣା ବ୍ୟବହାର-ବିସ୍ଫୋରଣ ଗତି ଓ ଗଣିତ ଓଭରରାଇଡ୍ ହଟାଯାଇଛି। ଦୈନିକ ସୀମା ରହିଛି। ଭାଗ ହୋଇଥିବା ବଜେଟ୍ ଓ ଅତିରିକ୍ତ-ସମୟ ଧାପ ବୈକଳ୍ପିକ ବିକଳ୍ପ, ସ୍ୱୟଂଚାଳିତ ବଦଳ ନୁହେଁ।",
    "Let the impulse pass": "ଆବେଗକୁ ଯିବାକୁ ଦିଅନ୍ତୁ",
    "Limit name": "ସୀମାର ନାମ",
    "Limits & schedules": "ସୀମା ଓ ସମୟସୂଚୀ",
    "Make room for what matters.": "ଯାହା ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ ତା’ ପାଇଁ ଜାଗା କରନ୍ତୁ।",
    "More-strict changes apply immediately.": "ଅଧିକ କଡ଼ା ବଦଳ ତୁରନ୍ତ ଲାଗୁ ହୁଏ।",
    "My first limit": "ମୋର ପ୍ରଥମ ସୀମା",
    "No limit yet. Add one whenever you're ready in Limits & blocks.": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ସୀମା ନାହିଁ। ପ୍ରସ୍ତୁତ ହେଲେ ସୀମା ଓ ବ୍ଲକ୍ ରେ ଗୋଟିଏ ଯୋଡ଼ନ୍ତୁ।",
    "No silent new permissions": "ଚୁପ୍‌ଚାପ୍ ନୂଆ ଅନୁମତି ନାହିଁ",
    "Nothing to configure here. Review a limit when you're ready; edits still follow your delays.": "ଏଠାରେ ଠିକ୍ କରିବାକୁ କିଛି ନାହିଁ। ପ୍ରସ୍ତୁତ ହେଲେ ଏକ ସୀମା ଦେଖନ୍ତୁ; ବଦଳ ଏବେ ବି ଆପଣଙ୍କ ଅପେକ୍ଷା ମାନେ।",
    "One app or a shared group": "ଗୋଟିଏ ଆପ୍ କିମ୍ବା ଏକ ସେୟାର୍ ଗ୍ରୁପ୍",
    "One budget, three portions": "ଗୋଟିଏ ବଜେଟ୍, ତିନୋଟି ଭାଗ",
    "One delay for all changes": "ସମସ୍ତ ବଦଳ ପାଇଁ ଗୋଟିଏ ଅପେକ୍ଷା",
    "One wait for all changes: %@": "ସମସ୍ତ ବଦଳ ପାଇଁ ଗୋଟିଏ ଅପେକ୍ଷା: %@",
    "Only less-strict changes wait": "କେବଳ କମ୍ କଡ଼ା ବଦଳ ଅପେକ୍ଷା କରେ",
    "Open my limits": "ମୋ ସୀମା ଖୋଲନ୍ତୁ",
    "Optional: choose an app or a group and a daily allowance. This will be a real limit, not a demo.": "ବୈକଳ୍ପିକ: ଏକ ଆପ୍ କିମ୍ବା ଗ୍ରୁପ୍ ଓ ଏକ ଦୈନିକ ବରାଦ ବାଛନ୍ତୁ। ଏହା ପ୍ରକୃତ ସୀମା ହେବ, ଡେମୋ ନୁହେଁ।",
    "Permission by person": "ବ୍ୟକ୍ତି ଅନୁସାରେ ଅନୁମତି",
    "Plan ordered extra-time steps, each with its own wait or approval method.": "କ୍ରମରେ ଅତିରିକ୍ତ-ସମୟ ଧାପ ଠିକ୍ କରନ୍ତୁ, ପ୍ରତ୍ୟେକର ନିଜସ୍ୱ ଅପେକ୍ଷା କିମ୍ବା ଅନୁମୋଦନ ପଦ୍ଧତି ସହ।",
    "Planned windows": "ଯୋଜିତ ସମୟ",
    "Red": "ଲାଲ",
    "Scope approvals to the pending changes you choose. Extra-time approval is a separate opt-in.": "ଅନୁମୋଦନ ଆପଣ ବାଛିଥିବା ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ମଧ୍ୟରେ ସୀମିତ ରଖନ୍ତୁ। ଅତିରିକ୍ତ ସମୟର ଅନୁମୋଦନ ଅଲଗା ପସନ୍ଦ।",
    "See what's active, what's next, and which changes are waiting.": "କ’ଣ ସକ୍ରିୟ, ପରେ କ’ଣ ଓ କେଉଁ ବଦଳ ଅପେକ୍ଷାରେ, ଦେଖନ୍ତୁ।",
    "Set a limit later": "ସୀମା ପରେ ଠିକ୍ କରନ୍ତୁ",
    "Set limits for an app or a group, and plan time away.": "ଏକ ଆପ୍ କିମ୍ବା ଗ୍ରୁପ୍ ପାଇଁ ସୀମା ଠିକ୍ କରନ୍ତୁ ଓ ଦୂରରେ ରହିବାର ଯୋଜନା କରନ୍ତୁ।",
    "Set weekday allowances and an optional wake-up wait.": "ସପ୍ତାହର ଦିନ ଅନୁସାରେ ବରାଦ ଓ ଏକ ବୈକଳ୍ପିକ ଉଠିବା ଅପେକ୍ଷା ଠିକ୍ କରନ୍ତୁ।",
    "Setup couldn't be saved": "ସେଟଅପ୍ ସେଭ୍ କରାଯାଇପାରିଲା ନାହିଁ",
    "Split an allowance across your day, with optional carryover.": "ଦିନସାରା ବରାଦ ଭାଗ କରନ୍ତୁ, ବୈକଳ୍ପିକ ଆଗକୁ ନେବା ସହ।",
    "Start with one boundary.": "ଗୋଟିଏ ସୀମାରୁ ଆରମ୍ଭ କରନ୍ତୁ।",
    "Step %d of %d": "ଧାପ %d / %d",
    "The same wait applies whether you tighten or loosen a rule.": "ଆପଣ ନିୟମ କଡ଼ା କରନ୍ତୁ କି ଢିଲା, ସମାନ ଅପେକ୍ଷା ଲାଗୁ ହୁଏ।",
    "The selected apps share this allowance. You can fine-tune it later in Limits & blocks.": "ବଛା ଆପ୍ ଏହି ବରାଦ ବାଣ୍ଟି ନିଏ। ପରେ ସୀମା ଓ ବ୍ଲକ୍ ରେ ଆପଣ ଏହାକୁ ସୂକ୍ଷ୍ମ ଭାବେ ମେଳାଇପାରିବେ।",
    "These are your starting settings. Later changes to rules and delay settings follow your delay policy.": "ଏହା ଆପଣଙ୍କ ଆରମ୍ଭ ସେଟିଂସ୍। ନିୟମ ଓ ଅପେକ୍ଷା ସେଟିଂସ୍‌ର ପରବର୍ତ୍ତୀ ବଦଳ ଆପଣଙ୍କ ଅପେକ୍ଷା ନିୟମ ମାନେ।",
    "This limit will be saved when you start. Your initial setup doesn't need to wait.": "ଆପଣ ଆରମ୍ଭ କଲେ ଏହି ସୀମା ସେଭ୍ ହେବ। ଆପଣଙ୍କ ପ୍ରାଥମିକ ସେଟଅପ୍‌କୁ ଅପେକ୍ଷା କରିବାକୁ ପଡ଼େ ନାହିଁ।",
    "Three ways to wait": "ଅପେକ୍ଷା କରିବାର ତିନି ଉପାୟ",
    "Tighten a rule immediately. Loosening it still waits.": "ଏକ ନିୟମ ତୁରନ୍ତ କଡ଼ା କରନ୍ତୁ। ତାହାକୁ ଢିଲା କରିବା ଏବେ ବି ଅପେକ୍ଷା କରେ।",
    "Tightening is immediate · Loosening: %@": "କଡ଼ା କରିବା ତୁରନ୍ତ · ଢିଲା କରିବା: %@",
    "Tightening: %@ · Loosening: %@": "କଡ଼ା କରିବା: %@ · ଢିଲା କରିବା: %@",
    "Trust, with clear boundaries.": "ସ୍ପଷ୍ଟ ସୀମା ସହ ଭରସା।",
    "Try again": "ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ",
    "Two delays": "ଦୁଇଟି ଅପେକ୍ଷା",
    "Want a practice run? The optional walkthrough and extra safeguards are in Settings → Help.": "ଅଭ୍ୟାସ କରିବାକୁ ଚାହୁଁଛନ୍ତି? ବୈକଳ୍ପିକ ୱାକ୍‌ଥ୍ରୁ ଓ ଅତିରିକ୍ତ ସୁରକ୍ଷା ସେଟିଂସ୍ → ସାହାଯ୍ୟ ରେ ଅଛି।",
    "Welcome back": "ପୁଣି ସ୍ୱାଗତ",
    "You can add a limit after enabling Screen Time access. For now, continue without one.": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆକ୍ସେସ୍ ଚାଲୁ କରିବା ପରେ ସୀମା ଯୋଡ଼ିପାରିବେ। ଏବେ ଏହା ବିନା ଜାରି ରଖନ୍ତୁ।",
    "You're ready. Your rules are still yours.": "ଆପଣ ପ୍ରସ୍ତୁତ। ଆପଣଙ୍କ ନିୟମ ଏବେ ବି ଆପଣଙ୍କର।",
    "Your choices are still here. Please try again.": "ଆପଣଙ୍କ ପସନ୍ଦ ଏବେ ବି ଏଠାରେ ଅଛି। ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Your delay policy": "ଆପଣଙ୍କ ଅପେକ୍ଷା ନିୟମ",
    "Your next chapter.": "ଆପଣଙ୍କ ପରବର୍ତ୍ତୀ ଅଧ୍ୟାୟ।",
    "Your saved rules and pending changes are retained. Your existing delay settings are unchanged.": "ଆପଣଙ୍କ ସେଭ୍ ହୋଇଥିବା ନିୟମ ଓ ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ରହେ। ଆପଣଙ୍କ ବିଦ୍ୟମାନ ଅପେକ୍ଷା ସେଟିଂସ୍ ବଦଳି ନାହିଁ।",
    "Your setup is safe": "ଆପଣଙ୍କ ସେଟଅପ୍ ସୁରକ୍ଷିତ",
    "Your waits and trusted contacts now have their own place.": "ଆପଣଙ୍କ ଅପେକ୍ଷା ଓ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତିଙ୍କ ଏବେ ନିଜସ୍ୱ ସ୍ଥାନ ଅଛି।",
    // End Demora 2.0 copy.
    // Per-contact approval permissions and schedule app editing.
    "All pending changes": "ସମସ୍ତ ଅପେକ୍ଷାରେ ଥିବା ବଦଳ",
    "None": "କିଛି ନୁହେଁ",
    "Edit": "ସମ୍ପାଦନ",
    "This contact must confirm before they can approve.": "ଅନୁମୋଦନ ପୂର୍ବରୁ ଏହି ଯୋଗାଯୋଗକୁ ନିଶ୍ଚିତ କରିବାକୁ ହେବ।",
    "Queued": "ଧାଡ଼ିରେ",
    "Changing apps, categories, or websites always uses the less-strict delay. The current schedule stays in effect until the change applies.": "ଆପ୍, ଶ୍ରେଣୀ କିମ୍ବା ୱେବସାଇଟ୍ ବଦଳାଇବା ସବୁବେଳେ କମ୍ କଡ଼ା ଅପେକ୍ଷା ବ୍ୟବହାର କରେ। ବଦଳ ଲାଗୁ ନହେବା ପର୍ଯ୍ୟନ୍ତ ବର୍ତ୍ତମାନର ସମୟସୂଚୀ ଚାଲୁ ରହେ।",
    "Limit changes": "ସୀମା ବଦଳ",
    "Schedule changes": "ସମୟସୂଚୀ ବଦଳ",
    "Session changes": "ସେସନ୍ ବଦଳ",
    "Delay changes": "ଅପେକ୍ଷା ବଦଳ",
    "Protection changes": "ସୁରକ୍ଷା ବଦଳ",
    "Contact changes": "ଯୋଗାଯୋଗ ବଦଳ",
    "Waiting for a trusted contact": "ଜଣେ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତିଙ୍କ ପାଇଁ ଅପେକ୍ଷା",
    "Trusted-contact approvals are turned off.": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତିଙ୍କ ଅନୁମୋଦନ ବନ୍ଦ ଅଛି।",
    "Next use: %d usage minutes after contact approval": "ପରବର୍ତ୍ତୀ ବ୍ୟବହାର: ଯୋଗାଯୋଗ ଅନୁମୋଦନ ପରେ %d ବ୍ୟବହାର ମିନିଟ୍",
    "Extra time for %@: %d usage minutes": "%@ ପାଇଁ ଅତିରିକ୍ତ ସମୟ: %d ବ୍ୟବହାର ମିନିଟ୍",
    "Cancel and start again": "ବାତିଲ୍ କରି ପୁଣି ଆରମ୍ଭ କରନ୍ତୁ",
    "Cancel this request, then reopen extra time to choose contacts again.": "ଏହି ଅନୁରୋଧ ବାତିଲ୍ କରନ୍ତୁ, ତା’ପରେ ଯୋଗାଯୋଗ ପୁଣି ବାଛିବାକୁ ଅତିରିକ୍ତ ସମୟ ଖୋଲନ୍ତୁ।",
    "This contact approval could not grant extra time. Cancel and try again.": "ଏହି ଯୋଗାଯୋଗ ଅନୁମୋଦନ ଅତିରିକ୍ତ ସମୟ ଦେଇପାରିଲା ନାହିଁ। ବାତିଲ୍ କରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Phrases": "ବାକ୍ୟ",
    "Phrase type": "ବାକ୍ୟର ପ୍ରକାର",
    "Random words": "ଅନିୟମିତ ଶବ୍ଦ",
    "Custom phrase": "କଷ୍ଟମ୍ ବାକ୍ୟ",
    "Words": "ଶବ୍ଦ",
    "%d words": "%d ଟି ଶବ୍ଦ",
    "Wrong words before reset": "ରିସେଟ୍ ପୂର୍ବରୁ ଭୁଲ ଶବ୍ଦ",
    "Unlimited": "ଅସୀମିତ",
    "Add phrase": "ବାକ୍ୟ ଯୋଡ଼ନ୍ତୁ",
    "Edit phrase": "ବାକ୍ୟ ସମ୍ପାଦନ କରନ୍ତୁ",
    "Remove phrase": "ବାକ୍ୟ ହଟାନ୍ତୁ",
    "Add or change phrase: %@": "ବାକ୍ୟ ଯୋଡ଼ନ୍ତୁ କିମ୍ବା ବଦଳାନ୍ତୁ: %@",
    "Remove phrase: %@": "ବାକ୍ୟ ହଟାନ୍ତୁ: %@",
    "phrase": "ବାକ୍ୟ",
    "The exact custom phrase is saved on this device. Choose something you would not type impulsively.": "ଠିକ୍ କଷ୍ଟମ୍ ବାକ୍ୟ ଏହି ଡିଭାଇସ୍‌ରେ ସେଭ୍ ହୁଏ। ଆବେଗରେ ଟାଇପ୍ କରିବେ ନାହିଁ ଏପରି କିଛି ବାଛନ୍ତୁ।",
    "Word %d of %d": "ଶବ୍ଦ %d / %d",
    "Mistakes: %d": "ଭୁଲ: %d",
    "Type the highlighted word": "ହାଇଲାଇଟ୍ ହୋଇଥିବା ଶବ୍ଦ ଟାଇପ୍ କରନ୍ତୁ",
    "Check word": "ଶବ୍ଦ ଯାଞ୍ଚ କରନ୍ତୁ",
    "That word was incorrect. Try again.": "ସେହି ଶବ୍ଦ ଭୁଲ ଥିଲା। ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Too many mistakes. Start again.": "ବହୁତ ଭୁଲ। ପୁଣି ଆରମ୍ଭ କରନ୍ତୁ।",
    "Phrase unavailable. Close this screen and try again.": "ବାକ୍ୟ ଉପଲବ୍ଧ ନୁହେଁ। ଏହି ସ୍କ୍ରିନ୍ ବନ୍ଦ କରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "This change is no longer available. Please try again.": "ଏହି ବଦଳ ଆଉ ଉପଲବ୍ଧ ନୁହେଁ। ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Type every word to receive this use of extra time.": "ଅତିରିକ୍ତ ସମୟର ଏହି ବ୍ୟବହାର ପାଇବାକୁ ପ୍ରତ୍ୟେକ ଶବ୍ଦ ଟାଇପ୍ କରନ୍ତୁ।",
    "This extra-time use is no longer available.": "ଅତିରିକ୍ତ ସମୟର ଏହି ବ୍ୟବହାର ଆଉ ଉପଲବ୍ଧ ନୁହେଁ।",
    "Unavailable phrase": "ଅନୁପଲବ୍ଧ ବାକ୍ୟ",
    "Next use: %d usage minutes after typing %@": "ପରବର୍ତ୍ତୀ ବ୍ୟବହାର: %2$@ ଟାଇପ୍ କରିବା ପରେ %1$d ବ୍ୟବହାର ମିନିଟ୍",
    "Approval permissions": "ଅନୁମୋଦନ ଅନୁମତି",
    "Change trusted-contact permissions: %@": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତିଙ୍କ ଅନୁମତି ବଦଳାନ୍ତୁ: %@",
    "This contact can no longer approve these changes. Send a new request.": "ଏହି ଯୋଗାଯୋଗ ଆଉ ଏହି ବଦଳ ଅନୁମୋଦନ କରିପାରିବେ ନାହିଁ। ନୂଆ ଅନୁରୋଧ ପଠାନ୍ତୁ।",
    "Today's limits": "ଆଜିର ସୀମା",
    "View usage": "ବ୍ୟବହାର ଦେଖନ୍ତୁ",
    "Active sessions": "ସକ୍ରିୟ ସେସନ୍",
    "Limits & blocks": "ସୀମା ଓ ବ୍ଲକ୍",
    "Your limits": "ଆପଣଙ୍କ ସୀମା",
    "More blocking tools": "ଅଧିକ ବ୍ଲକ୍ ଉପକରଣ",
    "App & website blocking": "ଆପ୍ ଓ ୱେବସାଇଟ୍ ବ୍ଲକ୍",
    "deletion, adult sites, custom domains": "ମାଡ଼ିବା, ପ୍ରାପ୍ତବୟସ୍କ ସାଇଟ୍, କଷ୍ଟମ୍ ଡୋମେନ୍",
    "Delays & overrides": "ଅପେକ୍ଷା ଓ ଓଭରରାଇଡ୍",
    "Your rules can change—just not in the moment.": "ଆପଣଙ୍କ ନିୟମ ବଦଳିପାରେ — କେବଳ ସେହି କ୍ଷଣରେ ନୁହେଁ।",
    "Only someone you trust can approve skipping a pending change's wait.": "ଅପେକ୍ଷାରେ ଥିବା ବଦଳର ଅପେକ୍ଷା ଏଡ଼ାଇବା କେବଳ ଆପଣ ଭରସା କରୁଥିବା କେହି ଅନୁମୋଦନ କରିପାରିବେ।",
    "Three time portions": "ତିନୋଟି ସମୟ ଭାଗ",
    "First cutoff": "ପ୍ରଥମ ସୀମା-ସମୟ",
    "Second cutoff": "ଦ୍ୱିତୀୟ ସୀମା-ସମୟ",
    "First portion: %d minutes": "ପ୍ରଥମ ଭାଗ: %d ମିନିଟ୍",
    "Middle portion: %d minutes": "ମଝି ଭାଗ: %d ମିନିଟ୍",
    "Final portion: %d minutes": "ଶେଷ ଭାଗ: %d ମିନିଟ୍",
    "Divide today's usage into time-of-day portions. Unused minutes can carry into later portions if you choose.": "ଆଜିର ବ୍ୟବହାରକୁ ଦିନର ସମୟ ଅନୁସାରେ ଭାଗରେ ବାଣ୍ଟନ୍ତୁ। ଚାହିଁଲେ ଅବ୍ୟବହୃତ ମିନିଟ୍ ପରବର୍ତ୍ତୀ ଭାଗକୁ ଯାଇପାରେ।",
    "Manual extra time": "ହାତରେ ଅତିରିକ୍ତ ସମୟ",
    "A limit is a daily usage budget for selected apps or categories. When it runs out, those apps are blocked until midnight.": "ସୀମା ହେଉଛି ବାଛିଥିବା ଆପ୍ କିମ୍ବା ଶ୍ରେଣୀ ପାଇଁ ଦୈନିକ ବ୍ୟବହାର ବଜେଟ୍। ତାହା ଶେଷ ହେଲେ ସେହି ଆପ୍ ମଧ୍ୟରାତ୍ରି ପର୍ଯ୍ୟନ୍ତ ବ୍ଲକ୍ ରହେ।",
    "Home shows today's Screen Time usage. Limits & Blocks lists your configured limits; tap one to see its apps and categories. Usage from before you created a limit still counts that day. Raising or removing a limit is less strict; adding one or lowering its minutes is stricter.": "ହୋମ୍ ଆଜିର ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଦେଖାଏ। ସୀମା ଓ ବ୍ଲକ୍ ଆପଣଙ୍କ ସୀମା ତାଲିକାଭୁକ୍ତ କରେ; ଗୋଟିଏ ଉପରେ ଟ୍ୟାପ୍ କରି ତାହାର ଆପ୍ ଓ ଶ୍ରେଣୀ ଦେଖନ୍ତୁ। ସୀମା ବନାଇବା ପୂର୍ବର ବ୍ୟବହାର ମଧ୍ୟ ସେହି ଦିନ ଗଣାଯାଏ। ସୀମା ବଢ଼ାଇବା କିମ୍ବା ହଟାଇବା କମ୍ କଡ଼ା; ଯୋଡ଼ିବା କିମ୍ବା ମିନିଟ୍ କମାଇବା ଅଧିକ କଡ଼ା।",
    "Use %d": "%d ବ୍ୟବହାର କରନ୍ତୁ",
    "Extra usage: %d minutes": "ଅତିରିକ୍ତ ବ୍ୟବହାର: %d ମିନିଟ୍",
    "Wait: %d minutes": "ଅପେକ୍ଷା: %d ମିନିଟ୍",
    "Add another use": "ଆଉ ଏକ ବ୍ୟବହାର ଯୋଡ଼ନ୍ତୁ",
    "Set the usage minutes and wait for each use. Extra time is available only after the full daily limit is spent, and resets at midnight.": "ପ୍ରତ୍ୟେକ ବ୍ୟବହାର ପାଇଁ ବ୍ୟବହାର ମିନିଟ୍ ଓ ଅପେକ୍ଷା ଠିକ୍ କରନ୍ତୁ। ଅତିରିକ୍ତ ସମୟ ସମ୍ପୂର୍ଣ୍ଣ ଦୈନିକ ସୀମା ଶେଷ ହେଲା ପରେ ହିଁ ମିଳେ, ଓ ମଧ୍ୟରାତ୍ରିରେ ରିସେଟ୍ ହୁଏ।",
    "Next use: %d usage minutes after a %d-minute wait": "ପରବର୍ତ୍ତୀ ବ୍ୟବହାର: %d ମିନିଟ୍ ଅପେକ୍ଷା ପରେ %d ବ୍ୟବହାର ମିନିଟ୍",
    "Extra usage per request: %d minutes": "ପ୍ରତ୍ୟେକ ଅନୁରୋଧ ପିଛା ଅତିରିକ୍ତ ବ୍ୟବହାର: %d ମିନିଟ୍",
    "Requests per day: %d": "ଦିନକୁ ଅନୁରୋଧ: %d",
    "Wait after request: %d minutes": "ଅନୁରୋଧ ପରେ ଅପେକ୍ଷା: %d ମିନିଟ୍",
    "After the full daily limit is spent, request more actual usage minutes. The apps remain blocked until the wait ends. The daily request count resets at midnight.": "ସମ୍ପୂର୍ଣ୍ଣ ଦୈନିକ ସୀମା ଶେଷ ହେଲା ପରେ ଅଧିକ ପ୍ରକୃତ ବ୍ୟବହାର ମିନିଟ୍ ମାଗନ୍ତୁ। ଅପେକ୍ଷା ଶେଷ ନହେବା ପର୍ଯ୍ୟନ୍ତ ଆପ୍ ବ୍ଲକ୍ ରହେ। ଦୈନିକ ଅନୁରୋଧ ସଂଖ୍ୟା ମଧ୍ୟରାତ୍ରିରେ ରିସେଟ୍ ହୁଏ।",
    "iOS Screen Time callbacks can arrive late. Wake-up, split, and extra-time boundaries may not switch at the exact minute.": "iOS ସ୍କ୍ରିନ୍ ଟାଇମ୍ କଲ୍‌ବ୍ୟାକ୍ ବିଳମ୍ବରେ ଆସିପାରେ। ଉଠିବା, ଭାଗ ଓ ଅତିରିକ୍ତ-ସମୟ ସୀମା ଠିକ୍ ସେହି ମିନିଟ୍‌ରେ ବଦଳିନପାରେ।",
    "Extra-time requests left today: %d": "ଆଜି ବାକି ଅତିରିକ୍ତ-ସମୟ ଅନୁରୋଧ: %d",
    "Request extra time (%d left)": "ଅତିରିକ୍ତ ସମୟ ମାଗନ୍ତୁ (%d ବାକି)",
    "Extra time available in": "ଅତିରିକ୍ତ ସମୟ ମିଳିବ",
    "(%d requests left)": "(%d ଟି ଅନୁରୋଧ ବାକି)",
    "Extra usage active · %d requests left": "ଅତିରିକ୍ତ ବ୍ୟବହାର ସକ୍ରିୟ · %d ଟି ଅନୁରୋଧ ବାକି",
    "No extra-time requests left today": "ଆଜି ଅତିରିକ୍ତ-ସମୟ ଅନୁରୋଧ ବାକି ନାହିଁ",
    "Extra time": "ଅତିରିକ୍ତ ସମୟ",
    "Extra time could not be started safely. Your limit is still in place; try again later.": "ଅତିରିକ୍ତ ସମୟ ସୁରକ୍ଷିତ ଭାବେ ଆରମ୍ଭ ହୋଇପାରିଲା ନାହିଁ। ଆପଣଙ୍କ ସୀମା ଏବେ ବି ଅଛି; ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Split-budget blocks cannot be manually rechecked. They remain until their scheduled boundary.": "ଭାଗ ହୋଇଥିବା ବଜେଟ୍ ବ୍ଲକ୍ ହାତେ ପୁଣି ଯାଞ୍ଚ କରାଯାଇପାରେ ନାହିଁ। ସେଗୁଡ଼ିକ ସେମାନଙ୍କ ନିର୍ଦ୍ଧାରିତ ସୀମା ପର୍ଯ୍ୟନ୍ତ ରହେ।",
    "Change limit: %@": "ସୀମା ବଦଳାନ୍ତୁ: %@",
    "Unlock immediately after tap": "ଟ୍ୟାପ୍ ପରେ ତୁରନ୍ତ ଅନଲକ୍ କରନ୍ତୁ",
    "Wake up": "ଉଠନ୍ତୁ",
    "Available after %@": "%@ ପରେ ଉପଲବ୍ଧ",
    "Awake for today": "ଆଜି ପାଇଁ ଉଠିଗଲେ",
    "Different limits by weekday": "ସପ୍ତାହର ଦିନ ଅନୁସାରେ ଅଲଗା ସୀମା",
    "Each weekday's budget replaces the daily limit for that day.": "ପ୍ରତ୍ୟେକ ଦିନର ବଜେଟ୍ ସେହି ଦିନ ପାଇଁ ଦୈନିକ ସୀମାର ସ୍ଥାନ ନିଏ।",
    "Require wake-up tap": "ଉଠନ୍ତୁ ଟ୍ୟାପ୍ ଆବଶ୍ୟକ କରନ୍ତୁ",
    "Wait %d minutes after tap": "ଟ୍ୟାପ୍ ପରେ %d ମିନିଟ୍ ଅପେକ୍ଷା କରନ୍ତୁ",
    "After your first tap each day, wait before this limit becomes available.": "ପ୍ରତିଦିନ ଆପଣଙ୍କ ପ୍ରଥମ ଟ୍ୟାପ୍ ପରେ, ଏହି ସୀମା ଉପଲବ୍ଧ ହେବା ପୂର୍ବରୁ ଅପେକ୍ଷା କରନ୍ତୁ।",
    "Split daily budget": "ଭାଗ ହୋଇଥିବା ଦୈନିକ ବଜେଟ୍",
    "Cutoff time": "ସୀମା-ସମୟ",
    "%d minutes before cutoff": "ସୀମା-ସମୟର %d ମିନିଟ୍ ପୂର୍ବରୁ",
    "Carry unused early minutes forward": "ଅବ୍ୟବହୃତ ପ୍ରାରମ୍ଭିକ ମିନିଟ୍ ଆଗକୁ ନିଅନ୍ତୁ",
    "Reserve part of today's budget before the cutoff. The rest is available afterward.": "ସୀମା-ସମୟ ପୂର୍ବରୁ ଆଜିର ବଜେଟ୍‌ର ଏକ ଅଂଶ ସଂରକ୍ଷିତ ରଖନ୍ତୁ। ବାକି ତା’ ପରେ ମିଳେ।",
    "Usage bursts and breaks": "ବ୍ୟବହାରର ଝଲକ ଓ ବିରତି",
    "Burst quota: %d minutes": "ଝଲକ କୋଟା: %d ମିନିଟ୍",
    "Fresh allowance interval: %d minutes": "ନୂଆ ବରାଦ ବ୍ୟବଧାନ: %d ମିନିଟ୍",
    "Cooldown / break: %d minutes": "କୁଲଡାଉନ୍ / ବିରତି: %d ମିନିଟ୍",
    "Practical approximation, not an exact rolling window: a usage burst, a minimum interval before a fresh allowance, then a break. iOS may deliver usage callbacks late.": "ବ୍ୟବହାରିକ ଅନୁମାନ, ସଠିକ୍ ଗଡ଼ୁଥିବା ଝରକା ନୁହେଁ: ଏକ ବ୍ୟବହାର ଝଲକ, ନୂଆ ବରାଦ ପୂର୍ବରୁ ନ୍ୟୂନତମ ବ୍ୟବଧାନ, ତା’ପରେ ବିରତି। iOS ବ୍ୟବହାର କଲ୍‌ବ୍ୟାକ୍ ବିଳମ୍ବରେ ଦେଇପାରେ।",
    "iOS Screen Time callbacks can arrive late. Wake-up, split, and pacing boundaries may not switch at the exact minute.": "iOS ସ୍କ୍ରିନ୍ ଟାଇମ୍ କଲ୍‌ବ୍ୟାକ୍ ବିଳମ୍ବରେ ଆସିପାରେ। ଉଠିବା, ଭାଗ ଓ ଗତି ସୀମା ଠିକ୍ ସେହି ମିନିଟ୍‌ରେ ବଦଳିନପାରେ।",
    "Edit apps": "ଆପ୍ ସମ୍ପାଦନ କରନ୍ତୁ",
    "Change apps in %@": "%@ ରେ ଆପ୍ ବଦଳାନ୍ତୁ",
    "Change apps and daily limit for %@ to %d min/day": "%@ ପାଇଁ ଆପ୍ ଓ ଦୈନିକ ସୀମା %d ମି/ଦିନ କରନ୍ତୁ",
    "Change limit": "ସୀମା ବଦଳାନ୍ତୁ",
    "Notifications": "ବିଜ୍ଞପ୍ତି",
    "5 minutes left for a limit": "ସୀମାର ୫ ମିନିଟ୍ ବାକି",
    "Only for limits longer than 5 minutes. No alert is sent during a free period.": "କେବଳ ୫ ମିନିଟ୍‌ରୁ ଲମ୍ବା ସୀମା ପାଇଁ। ମୁକ୍ତ ସମୟରେ କୌଣସି ସତର୍କ ପଠାଯାଏ ନାହିଁ।",
    "Free period starts or ends in 5 minutes": "ମୁକ୍ତ ସମୟ ୫ ମିନିଟ୍‌ରେ ଆରମ୍ଭ କିମ୍ବା ଶେଷ ହୁଏ",
    "Optional reminders for scheduled free periods and free-session endings.": "ନିର୍ଦ୍ଧାରିତ ମୁକ୍ତ ସମୟ ଓ ମୁକ୍ତ ସେସନ୍ ଶେଷ ପାଇଁ ବୈକଳ୍ପିକ ସ୍ମାରକ।",
    "5 minutes left": "୫ ମିନିଟ୍ ବାକି",
    "About 5 minutes remain for %@ today.": "ଆଜି %@ ପାଇଁ ପ୍ରାୟ ୫ ମିନିଟ୍ ବାକି।",
    "Free period starts in 5 minutes": "ମୁକ୍ତ ସମୟ ୫ ମିନିଟ୍‌ରେ ଆରମ୍ଭ ହୁଏ",
    "Free period ends in 5 minutes": "ମୁକ୍ତ ସମୟ ୫ ମିନିଟ୍‌ରେ ଶେଷ ହୁଏ",
    "Now": "ଏବେ",
    "Next": "ପରେ",
    "No timed rule active": "କୌଣସି ସମୟ ନିୟମ ସକ୍ରିୟ ନାହିଁ",
    "Nothing coming up": "କିଛି ଆସୁନାହିଁ",
    "Limit reached": "ସୀମା ପହଞ୍ଚିଲା",
    "Demora now speaks more languages": "Demora ଏବେ ଅଧିକ ଭାଷା କହେ",
    "We've added support for German, French, Portuguese, Polish, Turkish, and Hindi.": "ଆମେ ଜର୍ମାନ୍, ଫରାସୀ, ପର୍ତ୍ତୁଗୀଜ୍, ପୋଲିଶ୍, ତୁର୍କୀ ଓ ହିନ୍ଦୀ ପାଇଁ ସମର୍ଥନ ଯୋଡ଼ିଛୁ।",
    "Apply language": "ଭାଷା ଲାଗୁ କରନ୍ତୁ",
    "Translation in beta": "ଅନୁବାଦ ବିଟାରେ",
    "This language is in beta. Please report any mistranslations or unclear phrasing to hello@getdemora.app.": "ଏହି ଭାଷା ବିଟାରେ ଅଛି। ଭୁଲ ଅନୁବାଦ କିମ୍ବା ଅସ୍ପଷ୍ଟ ଶବ୍ଦରଚନା hello@getdemora.app କୁ ଜଣାନ୍ତୁ।",
    "Dismiss": "ବନ୍ଦ କରନ୍ତୁ",
    "Recheck blocked limits": "ବ୍ଲକ୍ ହୋଇଥିବା ସୀମା ପୁଣି ଯାଞ୍ଚ କରନ୍ତୁ",
    "Takes around 30 seconds": "ପ୍ରାୟ ୩୦ ସେକେଣ୍ଡ ଲାଗେ",
    "Recheck keeps current blocks in place while iOS verifies today's usage. Limits iOS confirms stay blocked.": "iOS ଆଜିର ବ୍ୟବହାର ଯାଞ୍ଚ କରୁଥିବା ବେଳେ ପୁଣି-ଯାଞ୍ଚ ବର୍ତ୍ତମାନର ବ୍ଲକ୍ ରଖେ। iOS ଯେଉଁ ସୀମା ନିଶ୍ଚିତ କରେ ସେଗୁଡ଼ିକ ବ୍ଲକ୍ ରହେ।",
    "Limit recheck": "ସୀମା ପୁଣି ଯାଞ୍ଚ",
    "Released %d stale limit blocks. %d limits were freshly confirmed by iOS.": "%d ଟି ପୁରୁଣା ସୀମା ବ୍ଲକ୍ ଛଡ଼ାଗଲା। iOS ନୂଆ କରି %d ଟି ସୀମା ନିଶ୍ଚିତ କଲା।",
    "iOS freshly confirmed all current limit blocks.": "iOS ସମସ୍ତ ବର୍ତ୍ତମାନର ସୀମା ବ୍ଲକ୍ ନୂଆ କରି ନିଶ୍ଚିତ କଲା।",
    "No blocked limits need to be rechecked.": "ପୁଣି ଯାଞ୍ଚ କରିବାକୁ କୌଣସି ବ୍ଲକ୍ ହୋଇଥିବା ସୀମା ନାହିଁ।",
    "Wait until the active free period ends, then recheck again.": "ଚାଲିଥିବା ମୁକ୍ତ ସମୟ ଶେଷ ନହେବା ପର୍ଯ୍ୟନ୍ତ ଅପେକ୍ଷା କରନ୍ତୁ, ତା’ପରେ ପୁଣି ଯାଞ୍ଚ କରନ୍ତୁ।",
    "You can recheck again in %@.": "ଆପଣ %@ ପରେ ପୁଣି ଯାଞ୍ଚ କରିପାରିବେ।",
    "The recheck was interrupted. No blocks were changed.": "ପୁଣି-ଯାଞ୍ଚ ବାଧା ପାଇଲା। କୌଣସି ବ୍ଲକ୍ ବଦଳି ନାହିଁ।",
    "iOS couldn't complete the verification safely. No blocks were changed. Try again later.": "iOS ସୁରକ୍ଷିତ ଭାବେ ଯାଞ୍ଚ ସମ୍ପୂର୍ଣ୍ଣ କରିପାରିଲା ନାହିଁ। କୌଣସି ବ୍ଲକ୍ ବଦଳି ନାହିଁ। ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Safe limit rechecking requires iOS 17.4 or later. No blocks were changed.": "ସୁରକ୍ଷିତ ପୁଣି-ଯାଞ୍ଚ ପାଇଁ iOS 17.4 କିମ୍ବା ପରବର୍ତ୍ତୀ ଦରକାର। କୌଣସି ବ୍ଲକ୍ ବଦଳି ନାହିଁ।",
    "This is a demo — nothing you do here is saved or actually blocked.": "ଏହା ଏକ ଡେମୋ — ଏଠାରେ ଆପଣ ଯାହା କରନ୍ତି ତାହା ସେଭ୍ ହୁଏ ନାହିଁ କି ପ୍ରକୃତରେ ବ୍ଲକ୍ ହୁଏ ନାହିଁ।",
    "Limitations": "ସୀମାବଦ୍ଧତା",
    "iOS reporting notes": "iOS ରିପୋର୍ଟିଂ ଟିପ୍ପଣୀ",
    "Today's usage reporting": "ଆଜିର ବ୍ୟବହାର ରିପୋର୍ଟିଂ",
    "Daily counting on older iOS": "ପୁରୁଣା iOS ରେ ଦୈନିକ ଗଣନା",
    "%@ #%d of every month": "ପ୍ରତି ମାସରେ %@ #%d",
    "%d / %d min": "%d / %d ମି",
    "blocked until midnight": "ମଧ୍ୟରାତ୍ରି ପର୍ଯ୍ୟନ୍ତ ବ୍ଲକ୍",
