    "Solve math problems to skip a countdown.": "କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବାକୁ ଗଣିତ ସମାଧାନ କରନ୍ତୁ।",
    "Enter a password to skip a countdown.": "କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବାକୁ ପାସୱାର୍ଡ ଦିଅନ୍ତୁ।",
    "How schedules work": "ସମୟସୂଚୀ କିପରି କାମ କରେ",
    "Help": "ସାହାଯ୍ୟ",
    "thank you": "ଧନ୍ୟବାଦ",
    "Guide": "ଗାଇଡ୍",
    "Contact": "ଯୋଗାଯୋଗ",
    "About": "ବିଷୟରେ",
    "how each part works": "ପ୍ରତ୍ୟେକ ଅଂଶ କିପରି କାମ କରେ",
    "links": "ଲିଙ୍କ୍",
    "Report a bug": "ବଗ୍ ଜଣାନ୍ତୁ",
    "Request a feature": "ସୁବିଧା ମାଗନ୍ତୁ",
    "General help": "ସାଧାରଣ ସାହାଯ୍ୟ",
    "Website": "ୱେବସାଇଟ୍",
    "Instagram": "Instagram",
    "What Demora is": "Demora କ’ଣ",
    "Demora protects your screen-time rules with a delay instead of a password. Every change you make waits out a countdown before it takes effect, so you can always change your mind — just not instantly, in a moment of weakness. Blocking itself is enforced by iOS through Screen Time.": "Demora ପାସୱାର୍ଡ ବଦଳରେ ଅପେକ୍ଷା ଦ୍ୱାରା ଆପଣଙ୍କ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ନିୟମ ସୁରକ୍ଷିତ ରଖେ। ଆପଣ କରିଥିବା ପ୍ରତ୍ୟେକ ବଦଳ ଲାଗୁ ହେବା ପୂର୍ବରୁ କାଉଣ୍ଟଡାଉନ୍ ପୂରଣ କରେ, ତେଣୁ ଆପଣ ସବୁବେଳେ ମନ ବଦଳାଇପାରିବେ — କେବଳ ତୁରନ୍ତ ନୁହେଁ, ଦୁର୍ବଳ କ୍ଷଣରେ ନୁହେଁ। ବ୍ଲକ୍ ନିଜେ iOS ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଦ୍ୱାରା ଲାଗୁ ହୁଏ।",
    "There are two delays. The more-strict delay gates changes that tighten your rules (adding a limit, lowering minutes, adding a schedule). The less-strict delay gates changes that loosen them (raising a limit, removing a block, adding a free period) — usually set longer. Pending changes show on the Home tab with a live countdown and can be cancelled before they apply.": "ଦୁଇଟି ଅପେକ୍ଷା ଅଛି। କଡ଼ା ଅପେକ୍ଷା ଆପଣଙ୍କ ନିୟମ କଡ଼ା କରୁଥିବା ବଦଳ ପାଇଁ (ସୀମା ଯୋଡ଼ିବା, ମିନିଟ୍ କମାଇବା, ସମୟସୂଚୀ ଯୋଡ଼ିବା)। କମ୍ କଡ଼ା ଅପେକ୍ଷା ସେଗୁଡ଼ିକୁ ଢିଲା କରୁଥିବା ବଦଳ ପାଇଁ (ସୀମା ବଢ଼ାଇବା, ବ୍ଲକ୍ ହଟାଇବା, ମୁକ୍ତ ସମୟ ଯୋଡ଼ିବା) — ସାଧାରଣତଃ ଅଧିକ ଲମ୍ବା। ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ହୋମ୍ ଟାବ୍‌ରେ ଜୀବନ୍ତ କାଉଣ୍ଟଡାଉନ୍ ସହ ଦେଖାଯାଏ ଓ ଲାଗୁ ହେବା ପୂର୍ବରୁ ବାତିଲ୍ କରାଯାଇପାରେ।",
    "A limit is a daily time budget for the apps or categories you choose. When the minutes run out, those apps are blocked until midnight. The Limits tab shows today's usage per limit, and tapping a limit shows exactly which apps it covers.": "ସୀମା ହେଉଛି ଆପଣ ବାଛିଥିବା ଆପ୍ କିମ୍ବା ଶ୍ରେଣୀ ପାଇଁ ଦୈନିକ ସମୟ ବଜେଟ୍। ମିନିଟ୍ ଶେଷ ହେଲେ ସେହି ଆପ୍ ମଧ୍ୟରାତ୍ରି ପର୍ଯ୍ୟନ୍ତ ବ୍ଲକ୍ ରହେ। ସୀମା ଟାବ୍ ପ୍ରତ୍ୟେକ ସୀମାର ଆଜିର ବ୍ୟବହାର ଦେଖାଏ, ଏବଂ ଗୋଟିଏ ସୀମା ଉପରେ ଟ୍ୟାପ୍ କଲେ କେଉଁ ଆପ୍ ତାହା ଭିତରେ ଅଛି ଠିକ୍ ଦେଖାଯାଏ।",
    "Schedules block apps on a repeating or one-off basis. Recurring schedules repeat daily, on chosen weekdays, or monthly. Planned windows are one-offs for specific dates. Sessions are immediate timed blocks or unblocks. Free periods are windows where limits don't block and usage doesn't count.": "ସମୟସୂଚୀ ପୁନରାବୃତ୍ତ କିମ୍ବା ଏକ-ଥର ଆଧାରରେ ଆପ୍ ବ୍ଲକ୍ କରେ। ପୁନରାବୃତ୍ତ ସମୟସୂଚୀ ପ୍ରତିଦିନ, ବାଛିଥିବା ସପ୍ତାହ ଦିନରେ କିମ୍ବା ମାସିକ ଚାଲେ। ଯୋଜିତ ସମୟ ନିର୍ଦ୍ଦିଷ୍ଟ ତାରିଖ ପାଇଁ ଏକ-ଥର। ସେସନ୍ ତୁରନ୍ତ ସମୟ-ବଦ୍ଧ ବ୍ଲକ୍ କିମ୍ବା ଅନବ୍ଲକ୍। ମୁକ୍ତ ସମୟ ଏପରି ଝରକା ଯେଉଁଠି ସୀମା ବ୍ଲକ୍ କରେ ନାହିଁ ଓ ବ୍ୟବହାର ଗଣାଯାଏ ନାହିଁ।",
    "A trusted contact can approve skipping a countdown — by email code or from their own Demora app. People you add must accept before they can approve, and you can revoke them at any time.": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବାକୁ ଅନୁମୋଦନ କରିପାରିବେ — ଇମେଲ୍ କୋଡ୍ ଦ୍ୱାରା କିମ୍ବା ନିଜ Demora ଆପ୍‌ରୁ। ଆପଣ ଯୋଡ଼ିଥିବା ବ୍ୟକ୍ତି ଅନୁମୋଦନ ପୂର୍ବରୁ ଅନୁରୋଧ ଗ୍ରହଣ କରିବାକୁ ପଡ଼େ, ଓ ଆପଣ ଯେକୌଣସି ସମୟରେ ସେମାନଙ୍କୁ ହଟାଇପାରିବେ।",
    "App deletion lock": "ଆପ୍ ମାଡ଼ିବା ଲକ୍",
    "the core idea": "ମୂଳ ଭାବନା",
    "the two countdowns": "ଦୁଇଟି କାଉଣ୍ଟଡାଉନ୍",
    "daily app budgets": "ଦୈନିକ ଆପ୍ ବଜେଟ୍",
    "recurring, planned, sessions": "ପୁନରାବୃତ୍ତ, ଯୋଜିତ, ସେସନ୍",
    "escape hatches": "ଖସିଯିବା ବାଟ",
    "approval by a person": "ବ୍ୟକ୍ତି ଦ୍ୱାରା ଅନୁମୋଦନ",
    "can't uninstall to bypass": "ଏଡ଼ାଇବାକୁ ଅନଇନଷ୍ଟଲ୍ କରାଯାଇପାରେ ନାହିଁ",
    "Most screen-time apps lock your rules behind a password. Because you know the password, you can undo your own rules the moment you feel the urge — so they rarely stick.\n\nDemora protects your rules with time instead. Every change waits out a countdown you set in advance before it takes effect. You stay in full control of your rules, but you can't change them in a single impulsive moment. The blocking itself is enforced by iOS through Screen Time — the same system parental controls use — so it can't be quietly bypassed.": "ଅଧିକାଂଶ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆପ୍ ଆପଣଙ୍କ ନିୟମ ପାସୱାର୍ଡ ପଛରେ ତାଲା ପକାଏ। ପାସୱାର୍ଡ ଆପଣ ଜାଣନ୍ତି ବୋଲି ଲାଳସା ଆସିଲେ ନିଜ ନିୟମ ଖୋଲିପାରନ୍ତି — ତେଣୁ ସେଗୁଡ଼ିକ କ୍ୱଚିତ୍ ଟିକେ।\n\nDemora ବଦଳରେ ସମୟ ଦ୍ୱାରା ଆପଣଙ୍କ ନିୟମ ସୁରକ୍ଷିତ ରଖେ। ପ୍ରତ୍ୟେକ ବଦଳ ଲାଗୁ ହେବା ପୂର୍ବରୁ ଆପଣ ଆଗରୁ ଠିକ୍ କରିଥିବା କାଉଣ୍ଟଡାଉନ୍ ପୂରଣ କରେ। ନିୟମ ଉପରେ ସମ୍ପୂର୍ଣ୍ଣ ନିୟନ୍ତ୍ରଣ ଆପଣଙ୍କର, କିନ୍ତୁ ଗୋଟିଏ ଆବେଗର କ୍ଷଣରେ ବଦଳାଇପାରିବେ ନାହିଁ। ବ୍ଲକ୍ ନିଜେ iOS ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଦ୍ୱାରା ଲାଗୁ ହୁଏ — ଅଭିଭାବକ ନିୟନ୍ତ୍ରଣ ବ୍ୟବହାର କରୁଥିବା ସମାନ ବ୍ୟବସ୍ଥା — ତେଣୁ ଏହାକୁ ଚୁପ୍‌ଚାପ୍ ଏଡ଼ାଇ ହେବ ନାହିଁ।",
    "Demora has two delays. The more-strict delay covers any change that tightens your rules: adding a limit, lowering its minutes, adding a schedule, or turning on the deletion lock. The less-strict delay covers changes that loosen them: raising a limit, removing a block, adding a free period, or disabling an override. The less-strict delay is usually set longer, since loosening is where temptation lives.\n\nA change doesn't apply right away — it becomes a pending change with a live countdown on the Home tab. You can cancel it any time before it lands, and when the countdown reaches zero it applies on its own, even if the app is closed.": "Demora ର ଦୁଇଟି ଅପେକ୍ଷା ଅଛି। କଡ଼ା ଅପେକ୍ଷା ଆପଣଙ୍କ ନିୟମ କଡ଼ା କରୁଥିବା ପ୍ରତ୍ୟେକ ବଦଳକୁ ଆବରେ: ସୀମା ଯୋଡ଼ିବା, ମିନିଟ୍ କମାଇବା, ସମୟସୂଚୀ ଯୋଡ଼ିବା କିମ୍ବା ମାଡ଼ିବା ଲକ୍ ଚାଲୁ କରିବା। କମ୍ କଡ଼ା ଅପେକ୍ଷା ସେଗୁଡ଼ିକୁ ଢିଲା କରୁଥିବା ବଦଳକୁ ଆବରେ: ସୀମା ବଢ଼ାଇବା, ବ୍ଲକ୍ ହଟାଇବା, ମୁକ୍ତ ସମୟ ଯୋଡ଼ିବା କିମ୍ବା ଓଭରରାଇଡ୍ ବନ୍ଦ କରିବା। କମ୍ କଡ଼ା ଅପେକ୍ଷା ସାଧାରଣତଃ ଅଧିକ ଲମ୍ବା, କାରଣ ପ୍ରଲୋଭନ ଢିଲା କରିବାରେ ହିଁ ଥାଏ।\n\nବଦଳ ତୁରନ୍ତ ଲାଗୁ ହୁଏ ନାହିଁ — ଏହା ହୋମ୍ ଟାବ୍‌ରେ ଜୀବନ୍ତ କାଉଣ୍ଟଡାଉନ୍ ସହ ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ହୁଏ। ଲାଗୁ ହେବା ପୂର୍ବରୁ ଯେକୌଣସି ସମୟରେ ବାତିଲ୍ କରିପାରିବେ, ଏବଂ କାଉଣ୍ଟଡାଉନ୍ ଶୂନ୍ୟ ହେଲେ ଆପ୍ ବନ୍ଦ ଥିଲେ ମଧ୍ୟ ଏହା ନିଜେ ଲାଗୁ ହୁଏ।",
    "A limit is a daily time budget for a set of apps or whole categories. When the minutes run out, those apps are blocked for the rest of the day and unlock again at midnight.\n\nThe Limits tab shows today's real usage for each limit, read straight from Screen Time, and tapping a limit reveals exactly which apps and categories it covers. Because usage is measured by iOS, time spent before you created the limit still counts toward it that day. Raising or removing a limit is a less-strict change; adding one or lowering its minutes is stricter.": "ସୀମା ହେଉଛି ଆପ୍ ଗୋଷ୍ଠୀ କିମ୍ବା ସମ୍ପୂର୍ଣ୍ଣ ଶ୍ରେଣୀ ପାଇଁ ଦୈନିକ ସମୟ ବଜେଟ୍। ମିନିଟ୍ ଶେଷ ହେଲେ ସେହି ଆପ୍ ଦିନର ବାକି ଅଂଶ ବ୍ଲକ୍ ରହେ ଓ ମଧ୍ୟରାତ୍ରିରେ ପୁଣି ଖୋଲେ।\n\nସୀମା ଟାବ୍ ପ୍ରତ୍ୟେକ ସୀମାର ଆଜିର ପ୍ରକୃତ ବ୍ୟବହାର ସିଧା ସ୍କ୍ରିନ୍ ଟାଇମ୍‌ରୁ ପଢ଼ି ଦେଖାଏ, ଏବଂ ସୀମା ଉପରେ ଟ୍ୟାପ୍ କଲେ କେଉଁ ଆପ୍ ଓ ଶ୍ରେଣୀ ଆସେ ଠିକ୍ ଦେଖାଯାଏ। ବ୍ୟବହାର iOS ମାପେ ବୋଲି ସୀମା ବନାଇବା ପୂର୍ବରୁ ବିତାଇଥିବା ସମୟ ମଧ୍ୟ ସେହି ଦିନ ଗଣାଯାଏ। ସୀମା ବଢ଼ାଇବା କିମ୍ବା ହଟାଇବା କମ୍ କଡ଼ା ବଦଳ; ଯୋଡ଼ିବା କିମ୍ବା ମିନିଟ୍ କମାଇବା କଡ଼ା।",
    "Schedules block apps by time rather than by budget, in a few shapes. Recurring schedules repeat — every day, on chosen weekdays, or on a monthly pattern. Planned windows are one-offs for a specific date, like a trip or an exam. Sessions are immediate, timed blocks or unblocks you start right now. Free periods are windows where limits don't block and usage doesn't count toward them.\n\nEach blocking schedule either blocks the apps you pick, or blocks everything except the apps you pick. When rules overlap, the most specific one wins: a session beats a planned window, which beats a recurring schedule, and within the same kind the one added most recently takes priority.": "ସମୟସୂଚୀ ବଜେଟ୍ ବଦଳରେ ସମୟ ଅନୁସାରେ ଆପ୍ ବ୍ଲକ୍ କରେ, କିଛି ରୂପରେ। ପୁନରାବୃତ୍ତ ସମୟସୂଚୀ ପୁନରାବୃତ୍ତ ହୁଏ — ପ୍ରତିଦିନ, ବାଛିଥିବା ସପ୍ତାହ ଦିନରେ କିମ୍ବା ମାସିକ ଢାଞ୍ଚାରେ। ଯୋଜିତ ସମୟ ଏକ ନିର୍ଦ୍ଦିଷ୍ଟ ତାରିଖ ପାଇଁ ଏକ-ଥର, ଯେପରି ଯାତ୍ରା କିମ୍ବା ପରୀକ୍ଷା। ସେସନ୍ ତୁରନ୍ତ, ସମୟ-ବଦ୍ଧ ବ୍ଲକ୍ କିମ୍ବା ଅନବ୍ଲକ୍ ଯାହା ଆପଣ ଏବେ ଆରମ୍ଭ କରନ୍ତି। ମୁକ୍ତ ସମୟ ଏପରି ଝରକା ଯେଉଁଠି ସୀମା ବ୍ଲକ୍ କରେ ନାହିଁ ଓ ବ୍ୟବହାର ସେମାନଙ୍କ ବିରୁଦ୍ଧରେ ଗଣାଯାଏ ନାହିଁ।\n\nପ୍ରତ୍ୟେକ ବ୍ଲକ୍ ସମୟସୂଚୀ ହୁଏ ଆପଣ ବାଛିଥିବା ଆପ୍ ବ୍ଲକ୍ କରେ, ନଚେତ୍ ଆପଣ ବାଛିଥିବା ଆପ୍ ବ୍ୟତୀତ ସବୁ। ନିୟମ ଓଭରଲାପ୍ ହେଲେ ସବୁଠାରୁ ନିର୍ଦ୍ଦିଷ୍ଟ ଜିତେ: ସେସନ୍ ଯୋଜିତ ସମୟକୁ ହରାଏ, ଯାହା ପୁନରାବୃତ୍ତ ସମୟସୂଚୀକୁ ହରାଏ, ଓ ଏକା ପ୍ରକାର ଭିତରେ ସର୍ବଶେଷରେ ଯୋଡ଼ାଯାଇଥିବା ଆଗରେ ଯାଏ।",
    "Overrides are optional escape hatches that let you skip a pending change's countdown. There are three: solve a set of math problems, enter a password, or ask a trusted contact to approve. They're all off by default, so out of the box your delays are absolute.\n\nTurning an override on, or making it easier, counts as a less-strict change and waits out that delay. Turning one off, or making it harder, is stricter — so you can't instantly weaken your own safety net.": "ଓଭରରାଇଡ୍ ବୈକଳ୍ପିକ ଖସିଯିବା ବାଟ ଯାହା ଅପେକ୍ଷାରେ ଥିବା ବଦଳର କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବାକୁ ଦିଏ। ତିନୋଟି ଅଛି: ଗଣିତ ସମାଧାନ କରିବା, ପାସୱାର୍ଡ ଦେବା, କିମ୍ବା ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତିଙ୍କୁ ଅନୁମୋଦନ କରିବାକୁ କହିବା। ସବୁ ଡିଫଲ୍ଟରେ ବନ୍ଦ, ତେଣୁ ଆରମ୍ଭରୁ ଆପଣଙ୍କ ଅପେକ୍ଷା ନିରଙ୍କୁଶ।\n\nଓଭରରାଇଡ୍ ଚାଲୁ କରିବା କିମ୍ବା ସହଜ କରିବା କମ୍ କଡ଼ା ବଦଳ ଭାବେ ଗଣାଯାଏ ଓ ସେହି ଅପେକ୍ଷା ପୂରଣ କରେ। ବନ୍ଦ କରିବା କିମ୍ବା କଷ୍ଟକର କରିବା କଡ଼ା — ତେଣୁ ଆପଣ ତୁରନ୍ତ ନିଜ ସୁରକ୍ଷା ଜାଲକୁ ଦୁର୍ବଳ କରିପାରିବେ ନାହିଁ।",
    "A trusted contact is a person who can approve skipping a countdown for you. They can approve by entering a short code sent to their email, or directly from their own copy of Demora.\n\nAnyone you add has to accept the request before they can approve anything, so no one is involved without their knowledge. You can revoke a contact at any time, and they can step down on their side too. Adding the override is a less-strict change; removing it is stricter.": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଆପଣଙ୍କ ପାଇଁ କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବା ଅନୁମୋଦନ କରିପାରିବେ। ସେ ନିଜ ଇମେଲ୍‌କୁ ପଠାଯାଇଥିବା ଛୋଟ କୋଡ୍ ଦେଇ, କିମ୍ବା ସିଧା ନିଜ Demora କପିରୁ ଅନୁମୋଦନ କରିପାରିବେ।\n\nଆପଣ ଯୋଡ଼ିଥିବା ପ୍ରତ୍ୟେକଙ୍କୁ କିଛି ଅନୁମୋଦନ କରିବା ପୂର୍ବରୁ ଅନୁରୋଧ ଗ୍ରହଣ କରିବାକୁ ପଡ଼େ, ତେଣୁ କେହି ନଜାଣି ଜଡ଼ିତ ନୁହେଁ। ଆପଣ ଯୋଗାଯୋଗ ଯେକୌଣସି ସମୟରେ ହଟାଇପାରିବେ, ଏବଂ ସେମାନେ ମଧ୍ୟ ନିଜ ପାଖରୁ ହଟିପାରନ୍ତି। ଓଭରରାଇଡ୍ ଯୋଡ଼ିବା କମ୍ କଡ଼ା ବଦଳ; ହଟାଇବା କଡ଼ା।",
    "When the deletion lock is on, deleting any app from this iPhone is blocked — including Demora itself. That closes the most obvious loophole: uninstalling the app to wipe your rules.\n\nBecause turning the lock off makes things easier to bypass, it counts as a less-strict change and waits out that delay before it takes effect.": "ମାଡ଼ିବା ଲକ୍ ଚାଲୁ ଥିଲେ ଏହି iPhone ରୁ ଯେକୌଣସି ଆପ୍ ମାଡ଼ିବା ବ୍ଲକ୍ ହୁଏ — Demora ନିଜେ ମଧ୍ୟ। ଏହା ସବୁଠାରୁ ସ୍ପଷ୍ଟ ଫାଙ୍କ ବନ୍ଦ କରେ: ନିୟମ ପୋଛିବାକୁ ଆପ୍ ଅନଇନଷ୍ଟଲ୍ କରିବା।\n\nଲକ୍ ବନ୍ଦ କଲେ ଏଡ଼ାଇବା ସହଜ ହୁଏ ବୋଲି ଏହା କମ୍ କଡ଼ା ବଦଳ ଗଣାଯାଏ ଓ ଲାଗୁ ହେବା ପୂର୍ବରୁ ସେହି ଅପେକ୍ଷା ପୂରଣ କରେ।",
    "When on, deleting any app from this iPhone is blocked — including Demora itself — so your rules can't be bypassed by uninstalling. Turning it off goes through the less-strict delay.": "ଚାଲୁ ଥିଲେ ଏହି iPhone ରୁ ଯେକୌଣସି ଆପ୍ ମାଡ଼ିବା ବ୍ଲକ୍ ହୁଏ — Demora ନିଜେ ମଧ୍ୟ — ତେଣୁ ଅନଇନଷ୍ଟଲ୍ କରି ଆପଣଙ୍କ ନିୟମ ଏଡ଼ାଯାଇପାରେ ନାହିଁ। ଏହାକୁ ବନ୍ଦ କରିବା କମ୍ କଡ଼ା ଅପେକ୍ଷା ଦେଇ ଯାଏ।",
    "Blocks": "ବ୍ଲକ୍",
    "New recurring": "ନୂଆ ପୁନରାବୃତ୍ତ",
    "Week": "ସପ୍ତାହ",
    "Month": "ମାସ",
    "Nothing on this day.": "ଏହି ଦିନ କିଛି ନାହିଁ।",
    "When things overlap": "ଯେତେବେଳେ ଜିନିଷ ଓଭରଲାପ୍ ହୁଏ",
    "One-off, right now: block or unblock chosen apps for a set number of minutes. Still delay-gated to start; ending early flips the rule.": "ଏକ-ଥର, ଏବେ: ବାଛିଥିବା ଆପ୍ କିଛି ମିନିଟ୍ ପାଇଁ ବ୍ଲକ୍ କିମ୍ବା ଅନବ୍ଲକ୍ କରନ୍ତୁ। ଆରମ୍ଭ କରିବା ଏବେ ବି ଅପେକ୍ଷାଧୀନ; ଆଗରୁ ଶେଷ କଲେ ନିୟମ ଓଲଟିଯାଏ।",
    "One-off windows for specific dates — a trip, an exam. Block, allow-all-except, or a free period. Doesn't repeat.": "ନିର୍ଦ୍ଦିଷ୍ଟ ତାରିଖ ପାଇଁ ଏକ-ଥର ଝରକା — ଯାତ୍ରା, ପରୀକ୍ଷା। ବ୍ଲକ୍, ଏଗୁଡ଼ିକ ବ୍ୟତୀତ ସବୁ ଅନୁମତି, କିମ୍ବା ମୁକ୍ତ ସମୟ। ପୁନରାବୃତ୍ତ ହୁଏ ନାହିଁ।",
    "Windows that repeat — daily, by weekday, or monthly. Each is either a block or a free period.": "ପୁନରାବୃତ୍ତ ହେଉଥିବା ଝରକା — ପ୍ରତିଦିନ, ସପ୍ତାହ ଦିନ ଅନୁସାରେ କିମ୍ବା ମାସିକ। ପ୍ରତ୍ୟେକ ହୁଏ ବ୍ଲକ୍, ନଚେତ୍ ମୁକ୍ତ ସମୟ।",
    "Limits don't block during the window, and time used inside it doesn't count against your daily budgets.": "ଝରକା ସମୟରେ ସୀମା ବ୍ଲକ୍ କରେ ନାହିଁ, ଓ ଏହା ଭିତରେ ବିତିଥିବା ସମୟ ଆପଣଙ୍କ ଦୈନିକ ବଜେଟ୍‌ରେ ଗଣାଯାଏ ନାହିଁ।",
    "Priority: a session beats a planned window, which beats a recurring schedule. Within the same kind, the one you added most recently wins.": "ପ୍ରାଥମିକତା: ସେସନ୍ ଯୋଜିତ ସମୟକୁ ହରାଏ, ଯାହା ପୁନରାବୃତ୍ତ ସମୟସୂଚୀକୁ ହରାଏ। ଏକା ପ୍ରକାର ଭିତରେ ଆପଣ ସର୍ବଶେଷରେ ଯୋଡ଼ିଥିବା ଜିତେ।",
    "today %@–%@": "ଆଜି %@–%@",
    "Change passcode": "ପାସ୍‌କୋଡ୍ ବଦଳାନ୍ତୁ",
    "Select": "ବାଛନ୍ତୁ",
    "Cancel %d": "%d ବାତିଲ୍ କରନ୍ତୁ",
    "Apply %d now": "%d ଏବେ ଲାଗୁ କରନ୍ତୁ",
    "%d changes": "%d ଟି ବଦଳ",
    "Denied": "ପ୍ରତ୍ୟାଖ୍ୟାତ",
