    "Shown to people you ask to approve, so they know it's you.": "ଆପଣ ଯେଉଁମାନଙ୍କୁ ଅନୁମୋଦନ ମାଗନ୍ତି ସେମାନଙ୍କୁ ଦେଖାଯାଏ, ଯେପରି ସେମାନେ ଜାଣିବେ ଏହା ଆପଣ।",
