    "These people have you as a trusted contact. Removing yourself tells them and stops their requests.": "ଏହି ବ୍ୟକ୍ତିମାନେ ଆପଣଙ୍କୁ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଭାବେ ରଖିଛନ୍ତି। ନିଜକୁ ହଟାଇଲେ ସେମାନଙ୍କୁ ଜଣାଯାଏ ଓ ସେମାନଙ୍କ ଅନୁରୋଧ ବନ୍ଦ ହୁଏ।",
