    "%@ removed their permission to be your trusted contact.": "%@ ଆପଣଙ୍କ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ରହିବାର ଅନୁମତି ଫେରାଇ ନେଇଛନ୍ତି।",
    "Trusted contact removed": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ହଟାଯାଇଛି",
