    "Accept": "ଗ୍ରହଣ କରନ୍ତୁ",
    "Decline": "ପ୍ରତ୍ୟାଖ୍ୟାନ କରନ୍ତୁ",
    "Pending": "ଅପେକ୍ଷାରେ",
    "Waiting for them to accept in their Demora app.": "ସେମାନେ ସେମାନଙ୍କ Demora ଆପ୍‌ରେ ଗ୍ରହଣ କରିବାକୁ ଅପେକ୍ଷା କରାଯାଉଛି।",
    "A trusted contact can let you skip a pending change's countdown — by emailing you a one-time code, or, if they use Demora, by approving from their own app.": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଆପଣଙ୍କୁ ଅପେକ୍ଷାରେ ଥିବା ବଦଳର କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବାକୁ ଦେଇପାରନ୍ତି — ଆପଣଙ୍କୁ ଏକ-ଥରର କୋଡ୍ ଇମେଲ୍ କରି, କିମ୍ବା Demora ବ୍ୟବହାର କଲେ ନିଜ ଆପ୍‌ରୁ ଅନୁମୋଦନ କରି।",
    "Share this code so another Demora user can add you. You get a request to accept before it's active.": "ଏହି କୋଡ୍ ସେୟାର୍ କରନ୍ତୁ ଯେପରି ଅନ୍ୟ Demora ବ୍ୟବହାରକାରୀ ଆପଣଙ୍କୁ ଯୋଡ଼ିପାରିବେ। ସକ୍ରିୟ ହେବା ପୂର୍ବରୁ ଗ୍ରହଣ କରିବାକୁ ଆପଣ ଏକ ଅନୁରୋଧ ପାଆନ୍ତି।",
    "A Demora user (code %@) wants to add you as their trusted contact.": "ଜଣେ Demora ବ୍ୟବହାରକାରୀ (କୋଡ୍ %@) ଆପଣଙ୍କୁ ତାଙ୍କ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଭାବେ ଯୋଡ଼ିବାକୁ ଚାହାନ୍ତି।",
    "%@ (code %@) wants to add you as their trusted contact.": "%@ (କୋଡ୍ %@) ଆପଣଙ୍କୁ ତାଙ୍କ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଭାବେ ଯୋଡ଼ିବାକୁ ଚାହାନ୍ତି।",
    "If you accept, they can ask you to approve skipping their delays.": "ଆପଣ ଗ୍ରହଣ କଲେ ସେମାନେ ସେମାନଙ୍କ ଅପେକ୍ଷା ଏଡ଼ାଇବା ଅନୁମୋଦନ କରିବାକୁ ଆପଣଙ୍କୁ କହିପାରନ୍ତି।",
    "Email contacts work as soon as you add them. Demora-user contacts must accept first. Adding a contact is a less-strict change; removing one is stricter — both go through delays.": "ଇମେଲ୍ ଯୋଗାଯୋଗ ଯୋଡ଼ିବା ମାତ୍ରେ କାମ କରେ। Demora-ବ୍ୟବହାରକାରୀ ଯୋଗାଯୋଗ ପ୍ରଥମେ ଗ୍ରହଣ କରିବା ଜରୁରୀ। ଯୋଗାଯୋଗ ଯୋଡ଼ିବା କମ୍ କଡ଼ା ବଦଳ; ହଟାଇବା କଡ଼ା — ଦୁହିଁ ଅପେକ୍ଷା ଦେଇ ଯାଏ।",
