    "Adding a contact is a less-strict change; removing one is stricter — both go through delays.": "ଯୋଗାଯୋଗ ଯୋଡ଼ିବା କମ୍ କଡ଼ା ବଦଳ; ହଟାଇବା କଡ଼ା — ଦୁହିଁ ଅପେକ୍ଷା ଦେଇ ଯାଏ।",
