    "Ask them for the code shown in their Demora settings.": "ସେମାନଙ୍କ Demora ସେଟିଂସ୍‌ରେ ଦେଖାଯାଉଥିବା କୋଡ୍ ସେମାନଙ୍କୁ ମାଗନ୍ତୁ।",
