    "approvers, blocked": "ଅନୁମୋଦନକାରୀ, ବ୍ଲକ୍ ହୋଇଥିବା",
    "Couldn't send the request — check your connection and try again.": "ଅନୁରୋଧ ପଠାଯାଇପାରିଲା ନାହିଁ — ସଂଯୋଗ ଯାଞ୍ଚ କରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Too many requests to this contact right now. Try again later.": "ଏବେ ଏହି ଯୋଗାଯୋଗକୁ ବହୁତ ଅନୁରୋଧ ଯାଇଛି। ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "You've used all of today's approval emails. Try again tomorrow.": "ଆପଣ ଆଜିର ସମସ୍ତ ଅନୁମୋଦନ ଇମେଲ୍ ବ୍ୟବହାର କରିସାରିଛନ୍ତି। କାଲି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "General blocking": "ସାଧାରଣ ବ୍ଲକ୍",
    "deletion, websites": "ମାଡ଼ିବା, ୱେବସାଇଟ୍",
    "Block adult websites": "ପ୍ରାପ୍ତବୟସ୍କ ୱେବସାଇଟ୍ ବ୍ଲକ୍ କରନ୍ତୁ",
    "Allow adult websites": "ପ୍ରାପ୍ତବୟସ୍କ ୱେବସାଇଟ୍ ଅନୁମତି ଦିଅନ୍ତୁ",
    "Uses Apple's built-in filter to limit adult websites in Safari and other apps.": "Safari ଓ ଅନ୍ୟ ଆପ୍‌ରେ ପ୍ରାପ୍ତବୟସ୍କ ୱେବସାଇଟ୍ ସୀମିତ କରିବାକୁ Apple ର ଅନ୍ତର୍ନିହିତ ଫିଲ୍ଟର ବ୍ୟବହାର କରେ।",
    "Website blocker": "ୱେବସାଇଟ୍ ବ୍ଲକର୍",
    "Block website: %@": "ୱେବସାଇଟ୍ ବ୍ଲକ୍ କରନ୍ତୁ: %@",
    "Unblock website: %@": "ୱେବସାଇଟ୍ ଅନବ୍ଲକ୍ କରନ୍ତୁ: %@",
    "e.g. reddit.com": "ଯଥା reddit.com",
    "Queue: remove": "ଧାଡ଼ି: ହଟାନ୍ତୁ",
    "Block specific websites by typing their domain — no need for Apple's site picker, which often comes up empty. Note: blocking sites also turns on Apple's adult-content filter. Adding a site is gated by your delays; removing one waits the longer delay.": "ଡୋମେନ୍ ଟାଇପ୍ କରି ନିର୍ଦ୍ଦିଷ୍ଟ ୱେବସାଇଟ୍ ବ୍ଲକ୍ କରନ୍ତୁ — Apple ର ସାଇଟ୍ ପିକର୍ ଦରକାର ନାହିଁ, ଯାହା ପ୍ରାୟତଃ ଖାଲି ଆସେ। ଟିପ୍ପଣୀ: ସାଇଟ୍ ବ୍ଲକ୍ କଲେ Apple ର ପ୍ରାପ୍ତବୟସ୍କ-ବିଷୟବସ୍ତୁ ଫିଲ୍ଟର ମଧ୍ୟ ଚାଲୁ ହୁଏ। ସାଇଟ୍ ଯୋଡ଼ିବା ଆପଣଙ୍କ ଅପେକ୍ଷାଧୀନ; ହଟାଇବା ଲମ୍ବା ଅପେକ୍ଷା କରେ।",
    "Blocked all day": "ଦିନସାରା ବ୍ଲକ୍",
    "Adult websites": "ପ୍ରାପ୍ତବୟସ୍କ ୱେବସାଇଟ୍",
    "%d sites": "%d ଟି ସାଇଟ୍",
    "Blocked sites": "ବ୍ଲକ୍ ହୋଇଥିବା ସାଇଟ୍",
    "Stop apps from being deleted, limit adult websites, or block specific sites by domain. Every change here goes through your delays.": "ଆପ୍ ମାଡ଼ିବା ରୋକନ୍ତୁ, ପ୍ରାପ୍ତବୟସ୍କ ୱେବସାଇଟ୍ ସୀମିତ କରନ୍ତୁ, କିମ୍ବା ଡୋମେନ୍ ଅନୁସାରେ ନିର୍ଦ୍ଦିଷ୍ଟ ସାଇଟ୍ ବ୍ଲକ୍ କରନ୍ତୁ। ଏଠାର ପ୍ରତ୍ୟେକ ବଦଳ ଆପଣଙ୍କ ଅପେକ୍ଷା ଦେଇ ଯାଏ।",
    "0 minutes — this app stays blocked all day, every day.": "୦ ମିନିଟ୍ — ଏହି ଆପ୍ ପ୍ରତିଦିନ ଦିନସାରା ବ୍ଲକ୍ ରହେ।",
    "Approval emails are at capacity right now. Try again later, or use a Demora contact.": "ଅନୁମୋଦନ ଇମେଲ୍ ଏବେ କ୍ଷମତା ସୀମାରେ ଅଛି। ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ, କିମ୍ବା ଏକ Demora ଯୋଗାଯୋଗ ବ୍ୟବହାର କରନ୍ତୁ।",
    "You've sent today": "ଆପଣ ଆଜି ପଠାଇଛନ୍ତି",
    "All users · today": "ସମସ୍ତ ବ୍ୟବହାରକାରୀ · ଆଜି",
