    "Email address": "ଇମେଲ୍ ଠିକଣା",
    "Email contacts aren't available yet in this build.": "ଇମେଲ୍ ଯୋଗାଯୋଗ ଏହି ସଂସ୍କରଣରେ ଏପର୍ଯ୍ୟନ୍ତ ଉପଲବ୍ଧ ନୁହେଁ।",
    "Enable trusted-contact override": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଓଭରରାଇଡ୍ ଚାଲୁ କରନ୍ତୁ",
    "Friends who use Demora can add you as their trusted contact with this code.": "Demora ବ୍ୟବହାର କରୁଥିବା ବନ୍ଧୁମାନେ ଏହି କୋଡ୍ ଦ୍ୱାରା ଆପଣଙ୍କୁ ସେମାନଙ୍କ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଭାବେ ଯୋଡ଼ିପାରିବେ।",
    "Demora user": "Demora ବ୍ୟବହାରକାରୀ",
    "My code": "ମୋ କୋଡ୍",
    "No Demora user found with that code.": "ସେହି କୋଡ୍ ସହ କୌଣସି Demora ବ୍ୟବହାରକାରୀ ମିଳିଲେ ନାହିଁ।",
    "Remove trusted contact: %@": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ହଟାନ୍ତୁ: %@",
    "Send request": "ଅନୁରୋଧ ପଠାନ୍ତୁ",
    "Sending…": "ପଠାଯାଉଛି…",
    "Someone set you as their trusted contact and wants to skip a waiting period.": "କେହି ଆପଣଙ୍କୁ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଭାବେ ଠିକ୍ କରିଛନ୍ତି ଓ ଅପେକ୍ଷା ଏଡ଼ାଇବାକୁ ଚାହାନ୍ତି।",
    "Their Demora code": "ସେମାନଙ୍କ Demora କୋଡ୍",
    "Trusted contacts": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି",
    "Verify code": "କୋଡ୍ ଯାଞ୍ଚ କରନ୍ତୁ",
    "When enabled, a trusted contact can let you skip a pending change's countdown — by emailing you a code, or by approving from their own Demora app.": "ଚାଲୁ ଥିଲେ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଆପଣଙ୍କୁ ଅପେକ୍ଷାରେ ଥିବା ବଦଳର କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବାକୁ ଦେଇପାରନ୍ତି — ଆପଣଙ୍କୁ କୋଡ୍ ଇମେଲ୍ କରି, କିମ୍ବା ନିଜ Demora ଆପ୍‌ରୁ ଅନୁମୋଦନ କରି।",
    "Wrong or expired code.": "ଭୁଲ କିମ୍ବା ମିଆଦ ଶେଷ ହୋଇଥିବା କୋଡ୍।",
    "Your contact received a code by email. Enter it here. It expires in 15 minutes.": "ଆପଣଙ୍କ ଯୋଗାଯୋଗ ଇମେଲ୍‌ରେ ଏକ କୋଡ୍ ପାଇଲେ। ଏଠାରେ ଦିଅନ୍ତୁ। ଏହା ୧୫ ମିନିଟ୍‌ରେ ମିଆଦ ଶେଷ ହୁଏ।",
    "contact": "ଯୋଗାଯୋଗ",
    "e.g. Mom, Alex": "ଯଥା ମା, ଆଲେକ୍ସ",
    "%@ (%d problems)": "%@ (%d ଟି ପ୍ରଶ୍ନ)",
    "%@ session: %@ (%d min)": "%@ ସେସନ୍: %@ (%d ମି)",
    "%@ — session starts in %@, then runs %d min": "%@ — ସେସନ୍ %@ ରେ ଆରମ୍ଭ ହୁଏ, ତା’ପରେ %d ମି ଚାଲେ",
    "%@ — takes effect in %@": "%@ — %@ ରେ ଲାଗୁ ହେବ",
    "%d apps, %d categories": "%d ଟି ଆପ୍, %d ଟି ଶ୍ରେଣୀ",
    "%d hr": "%d ଘ",
    "%d min": "%d ମି",
    "%d min/day": "%d ମି/ଦିନ",
    "%d minutes": "%d ମିନିଟ୍",
    "%d minutes/day": "%d ମିନିଟ୍/ଦିନ",
    "%d selected": "%d ବଛା",
    "ACTIVE": "ସକ୍ରିୟ",
    "Add a daily time limit. It activates after your 'more strict' delay (%@).": "ଏକ ଦୈନିକ ସମୟସୀମା ଯୋଡ଼ନ୍ତୁ। ଏହା ଆପଣଙ୍କ 'କଡ଼ା' ଅପେକ୍ଷା (%@) ପରେ ସକ୍ରିୟ ହୁଏ।",
    "Add free period: %@ (%@)": "ମୁକ୍ତ ସମୟ ଯୋଡ଼ନ୍ତୁ: %@ (%@)",
    "Add free period…": "ମୁକ୍ତ ସମୟ ଯୋଡ଼ନ୍ତୁ…",
    "Add limit: %@ — %d min/day": "ସୀମା ଯୋଡ଼ନ୍ତୁ: %@ — %d ମି/ଦିନ",
    "Add me": "ମୋତେ ଯୋଡ଼ନ୍ତୁ",
    "Add my name…": "ମୋ ନାମ ଯୋଡ଼ନ୍ତୁ…",
    "Add schedule: %@ (%@ %@)": "ସମୟସୂଚୀ ଯୋଡ଼ନ୍ତୁ: %@ (%@ %@)",
    "Add schedule…": "ସମୟସୂଚୀ ଯୋଡ଼ନ୍ତୁ…",
    "Adding…": "ଯୋଡ଼ା ହେଉଛି…",
    "Allow app deletion": "ଆପ୍ ମାଡ଼ିବାକୁ ଅନୁମତି ଦିଅନ୍ତୁ",
    "App deletion": "ଆପ୍ ମାଡ଼ିବା",
    "Apply now…": "ଏବେ ଲାଗୁ କରନ୍ତୁ…",
    "Permissions": "ଅନୁମତି",
    "Demora needs Screen Time access to set limits and block apps, and notifications to tell you when a pending change is ready. iOS will ask for each.": "ସୀମା ଠିକ୍ କରିବାକୁ ଓ ଆପ୍ ବ୍ଲକ୍ କରିବାକୁ Demora କୁ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆକ୍ସେସ୍ ଦରକାର, ଏବଂ ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ପ୍ରସ୍ତୁତ ହେଲେ ଜଣାଇବାକୁ ବିଜ୍ଞପ୍ତି। iOS ପ୍ରତ୍ୟେକ ପାଇଁ ପଚାରିବ।",
    "Grant access": "ଆକ୍ସେସ୍ ଦିଅନ୍ତୁ",
    "Welcome to Demora": "Demora କୁ ସ୍ୱାଗତ",
    "Demora can be a lot at first, so let's set up your first limit together — a quick, hands-on walkthrough of how delays and overrides actually feel. It takes about a minute.": "Demora ପ୍ରଥମେ ବହୁତ ଲାଗିପାରେ, ତେଣୁ ଚାଲନ୍ତୁ ଏକାଠି ଆପଣଙ୍କ ପ୍ରଥମ ସୀମା ଠିକ୍ କରିବା — ଅପେକ୍ଷା ଓ ଓଭରରାଇଡ୍ ପ୍ରକୃତରେ କେମିତି ଲାଗେ ତାହାର ଏକ ଶୀଘ୍ର, ହାତ-ଅଭିଜ୍ଞତା ଭ୍ରମଣ। ପ୍ରାୟ ଏକ ମିନିଟ୍ ଲାଗେ।",
    "Add my first limit": "ମୋ ପ୍ରଥମ ସୀମା ଯୋଡ଼ନ୍ତୁ",
    "Add your first limit": "ଆପଣଙ୍କ ପ୍ରଥମ ସୀମା ଯୋଡ଼ନ୍ତୁ",
    "Add a recurring schedule": "ପୁନରାବୃତ୍ତ ସମୟସୂଚୀ ଯୋଡ଼ନ୍ତୁ",
    "Add a sample contact": "ଏକ ନମୁନା ଯୋଗାଯୋଗ ଯୋଡ଼ନ୍ତୁ",
    "Adding a trusted contact normally waits out a delay. In this tutorial it's instant.": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଯୋଡ଼ିବା ସାଧାରଣତଃ ଅପେକ୍ଷା ପୂରଣ କରେ। ଏହି ଟ୍ୟୁଟୋରିଆଲ୍‌ରେ ତାହା ତୁରନ୍ତ।",
    "Alex (sample)": "ଆଲେକ୍ସ (ନମୁନା)",
    "Now a schedule. Tap ‘Add a recurring schedule’, pick a time window and some apps, then queue it.": "ଏବେ ଏକ ସମୟସୂଚୀ। ‘ପୁନରାବୃତ୍ତ ସମୟସୂଚୀ ଯୋଡ଼ନ୍ତୁ’ ଟ୍ୟାପ୍ କରନ୍ତୁ, ଏକ ସମୟ ଝରକା ଓ କିଛି ଆପ୍ ବାଛନ୍ତୁ, ତା’ପରେ ଧାଡ଼ିରେ ରଖନ୍ତୁ।",
    "Two changes are waiting, and you can't wait them out. Tap Select, choose both, Apply — then use the password override. The password is: test": "ଦୁଇଟି ବଦଳ ଅପେକ୍ଷାରେ, ଓ ଆପଣ ସେଗୁଡ଼ିକ ପୂରଣ କରିପାରିବେ ନାହିଁ। ବାଛନ୍ତୁ ଟ୍ୟାପ୍ କରନ୍ତୁ, ଦୁଇଟିଯାକ ବାଛନ୍ତୁ, ଲାଗୁ କରନ୍ତୁ — ତା’ପରେ ପାସୱାର୍ଡ ଓଭରରାଇଡ୍ ବ୍ୟବହାର କରନ୍ତୁ। ପାସୱାର୍ଡ: test",
    "Open Calendar to see everything laid out by day.": "ଦିନ ଅନୁସାରେ ସବୁ ସଜାଯାଇଥିବା ଦେଖିବାକୁ କ୍ୟାଲେଣ୍ଡର ଖୋଲନ୍ତୁ।",
    "Now tidy up: remove the recurring schedule here, and the limit over in Limits.": "ଏବେ ସଫା କରନ୍ତୁ: ପୁନରାବୃତ୍ତ ସମୟସୂଚୀ ଏଠାରେ ହଟାନ୍ତୁ, ଓ ସୀମା ସୀମା ରେ।",
    "Now tidy up: open Recurring and remove the schedule you made.": "ଏବେ ସଫା କରନ୍ତୁ: ପୁନରାବୃତ୍ତ ଖୋଲି ଆପଣ ବନାଇଥିବା ସମୟସୂଚୀ ହଟାନ୍ତୁ।",
    "And the limit: tap it, then Remove this limit.": "ଏବଂ ସୀମା: ତା’ ଉପରେ ଟ୍ୟାପ୍ କରନ୍ତୁ, ତା’ପରେ ଏହି ସୀମା ହଟାନ୍ତୁ।",
    "Let's add a backup approver. Open Rules → Overrides → Trusted contacts and add a sample contact.": "ଚାଲନ୍ତୁ ଏକ ବ୍ୟାକଅପ୍ ଅନୁମୋଦନକାରୀ ଯୋଡ଼ିବା। ନିୟମ → ଓଭରରାଇଡ୍ → ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଖୋଲି ଏକ ନମୁନା ଯୋଗାଯୋଗ ଯୋଡ଼ନ୍ତୁ।",
    "Home delays": "ହୋମ୍ ଅପେକ୍ଷା",
    "Home overrides": "ହୋମ୍ ଓଭରରାଇଡ୍",
    "shown": "ଦେଖାଯାଇଛି",
    "hidden": "ଲୁଚିଛି",
    "Rules": "ନିୟମ",
    "Current overrides": "ବର୍ତ୍ତମାନର ଓଭରରାଇଡ୍",
    "No overrides on": "କୌଣସି ଓଭରରାଇଡ୍ ଚାଲୁ ନାହିଁ",
    "Code": "କୋଡ୍",
    "Name (optional)": "ନାମ (ବୈକଳ୍ପିକ)",
    "Unnamed": "ନାମହୀନ",
    "Waiting for them to enter their code.": "ସେମାନେ ସେମାନଙ୍କ କୋଡ୍ ଦେବାକୁ ଅପେକ୍ଷା କରାଯାଉଛି।",
    "Added as a trusted contact": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଭାବେ ଯୋଡ଼ାଗଲା",
    "Add as trusted contact": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଭାବେ ଯୋଡ଼ନ୍ତୁ",
    "They get a request to accept right away. They can approve for you once the wait ends.": "ସେମାନେ ତୁରନ୍ତ ଗ୍ରହଣ କରିବାକୁ ଏକ ଅନୁରୋଧ ପାଆନ୍ତି। ଅପେକ୍ଷା ଶେଷ ହେଲେ ସେମାନେ ଆପଣଙ୍କ ପାଇଁ ଅନୁମୋଦନ କରିପାରିବେ।",
    "Removing yourself tells them and stops their requests.": "ନିଜକୁ ହଟାଇଲେ ସେମାନଙ୍କୁ ଜଣାଯାଏ ଓ ସେମାନଙ୍କ ଅନୁରୋଧ ବନ୍ଦ ହୁଏ।",
    "That's your own code.": "ଏହା ଆପଣଙ୍କର ନିଜ କୋଡ୍।",
    "These people have you as a trusted contact. Tap one to see their details or add them back. Removing yourself tells them and stops their requests.": "ଏହି ବ୍ୟକ୍ତିମାନେ ଆପଣଙ୍କୁ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି ଭାବେ ରଖିଛନ୍ତି। ବିବରଣୀ ଦେଖିବାକୁ କିମ୍ବା ପୁଣି ଯୋଡ଼ିବାକୁ ଜଣେ ଉପରେ ଟ୍ୟାପ୍ କରନ୍ତୁ। ନିଜକୁ ହଟାଇଲେ ସେମାନଙ୍କୁ ଜଣାଯାଏ ଓ ସେମାନଙ୍କ ଅନୁରୋଧ ବନ୍ଦ ହୁଏ।",
    "Confirmed": "ନିଶ୍ଚିତ",
    "Send confirmation code": "ନିଶ୍ଚିତକରଣ କୋଡ୍ ପଠାନ୍ତୁ",
    "Resend code": "କୋଡ୍ ପୁଣି ପଠାନ୍ତୁ",
    "Confirm contact": "ଯୋଗାଯୋଗ ନିଶ୍ଚିତ କରନ୍ତୁ",
    "We email a code to this address. Your contact gives you the code, you enter it here, and then they can approve for you. Until then they can't.": "ଆମେ ଏହି ଠିକଣାକୁ ଏକ କୋଡ୍ ଇମେଲ୍ କରୁ। ଆପଣଙ୍କ ଯୋଗାଯୋଗ ଆପଣଙ୍କୁ କୋଡ୍ ଦିଅନ୍ତି, ଆପଣ ଏଠାରେ ଦିଅନ୍ତି, ତା’ପରେ ସେ ଆପଣଙ୍କ ପାଇଁ ଅନୁମୋଦନ କରିପାରିବେ। ସେତେବେଳ ପର୍ଯ୍ୟନ୍ତ ନୁହେଁ।",
    "Code sent. Ask your contact for it.": "କୋଡ୍ ପଠାଗଲା। ଆପଣଙ୍କ ଯୋଗାଯୋଗଙ୍କୁ ମାଗନ୍ତୁ।",
    "Daily email limit reached. Try again later.": "ଦୈନିକ ଇମେଲ୍ ସୀମା ପହଞ୍ଚିଲା। ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "You've sent too many codes today. Try again tomorrow.": "ଆପଣ ଆଜି ବହୁତ କୋଡ୍ ପଠାଇଛନ୍ତି। କାଲି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Couldn't send the code. Check your connection and try again.": "କୋଡ୍ ପଠାଇପାରିଲା ନାହିଁ। ସଂଯୋଗ ଯାଞ୍ଚ କରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "That code didn't match. Double-check and try again.": "ସେହି କୋଡ୍ ମେଳ ଖାଇଲା ନାହିଁ। ଦୁଇଥର ଦେଖି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Elementary": "ପ୍ରାଥମିକ",
    "Middle school": "ମାଧ୍ୟମିକ",
    "High school": "ଉଚ୍ଚ ମାଧ୍ୟମିକ",
    "Very easy": "ବହୁତ ସହଜ",
    "Your change is ready": "ଆପଣଙ୍କ ବଦଳ ପ୍ରସ୍ତୁତ",
    "Your limits have reset": "ଆପଣଙ୍କ ସୀମା ରିସେଟ୍ ହୋଇଛି",
    "If any apps still look blocked, open Demora to refresh them.": "କୌଣସି ଆପ୍ ଏବେ ବି ବ୍ଲକ୍ ଲାଗିଲେ ସେଗୁଡ଼ିକୁ ରିଫ୍ରେସ୍ କରିବାକୁ Demora ଖୋଲନ୍ତୁ।",
    "If you denied access, turn on Screen Time for Demora in Settings, then come back.": "ଆପଣ ଆକ୍ସେସ୍ ମନା କରିଥିଲେ, ସେଟିଂସ୍‌ରେ Demora ପାଇଁ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଚାଲୁ କରି ଫେରି ଆସନ୍ତୁ।",
    "Open Settings": "ସେଟିଂସ୍ ଖୋଲନ୍ତୁ",
    "Couldn't check the code — check your connection and try again.": "କୋଡ୍ ଯାଞ୍ଚ କରାଯାଇପାରିଲା ନାହିଁ — ସଂଯୋଗ ଯାଞ୍ଚ କରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Couldn't send your response — check your connection and try again.": "ଆପଣଙ୍କ ଉତ୍ତର ପଠାଯାଇପାରିଲା ନାହିଁ — ସଂଯୋଗ ଯାଞ୍ଚ କରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Those changes are still counting down. Wait them out, or turn on an override in Settings → Rules → Overrides to skip the wait.": "ସେହି ବଦଳ ଏବେ ବି କାଉଣ୍ଟଡାଉନ୍‌ରେ ଅଛି। ଅପେକ୍ଷା କରନ୍ତୁ, କିମ୍ବା ଅପେକ୍ଷା ଏଡ଼ାଇବାକୁ ସେଟିଂସ୍ → ନିୟମ → ଓଭରରାଇଡ୍ ରେ ଏକ ଓଭରରାଇଡ୍ ଚାଲୁ କରନ୍ତୁ।",
    "Heads up": "ସାବଧାନ",
    "Feature roadmap": "ବୈଶିଷ୍ଟ୍ୟ ରୋଡ୍‌ମ୍ୟାପ୍",
    "links to Trello": "Trello କୁ ଲିଙ୍କ୍",
    "Safety code": "ସୁରକ୍ଷା କୋଡ୍",
    "Mark as verified": "ଯାଞ୍ଚିତ ଭାବେ ଚିହ୍ନଟ କରନ୍ତୁ",
    "Verified": "ଯାଞ୍ଚିତ",
    "Security": "ସୁରକ୍ଷା",
    "Available once you've both added each other.": "ଆପଣମାନେ ଦୁହେଁ ପରସ୍ପରକୁ ଯୋଡ଼ିବା ପରେ ଉପଲବ୍ଧ।",
    "Compare this code with your contact in person or on a call. If it matches on both phones, no one has tampered with the connection.": "ଏହି କୋଡ୍ ଆପଣଙ୍କ ଯୋଗାଯୋଗ ସହ ମୁହାଁମୁହିଁ କିମ୍ବା କଲ୍‌ରେ ମିଳାନ୍ତୁ। ଦୁଇ ଫୋନ୍‌ରେ ମିଳିଲେ କେହି ସଂଯୋଗରେ ଛେଡ଼ଛାଡ଼ କରିନାହାଁନ୍ତି।",
    "Background blocking may be incomplete": "ବ୍ୟାକ୍‌ଗ୍ରାଉଣ୍ଡ୍ ବ୍ଲକ୍ ଅସମ୍ପୂର୍ଣ୍ଣ ହୋଇପାରେ",
    "iOS limits how many limits and schedules can run in the background at once. Removing a few restores full enforcement.": "iOS ଏକସାଙ୍ଗରେ ବ୍ୟାକ୍‌ଗ୍ରାଉଣ୍ଡ୍‌ରେ କେତେ ସୀମା ଓ ସମୟସୂଚୀ ଚାଲିପାରିବ ତାହା ସୀମିତ କରେ। କିଛି ହଟାଇଲେ ପୂର୍ଣ୍ଣ ପ୍ରୟୋଗ ଫେରେ।",
    "College": "କଲେଜ୍",
    "Nothing — just a new problem": "କିଛି ନୁହେଁ — କେବଳ ଏକ ନୂଆ ପ୍ରଶ୍ନ",
    "Lose one correct answer": "ଗୋଟିଏ ସଠିକ୍ ଉତ୍ତର ହରାନ୍ତୁ",
    "Restart from zero": "ଶୂନରୁ ପୁଣି ଆରମ୍ଭ କରନ୍ତୁ",
    "Enable math override (%@, %d problems)": "ଗଣିତ ଓଭରରାଇଡ୍ ଚାଲୁ କରନ୍ତୁ (%@, %d ଟି ପ୍ରଶ୍ନ)",
    "Solve for x:  (x − %d) × %d = %d": "x ବାହାର କରନ୍ତୁ:  (x − %d) × %d = %d",
    "Avatar": "ଅବତାର",
    "Icon": "ଆଇକନ୍",
    "Photo": "ଫଟୋ",
    "Type one emoji": "ଗୋଟିଏ ଇମୋଜି ଟାଇପ୍ କରନ୍ତୁ",
    "Choose a photo": "ଏକ ଫଟୋ ବାଛନ୍ତୁ",
    "Change photo": "ଫଟୋ ବଦଳାନ୍ତୁ",
    "Remove photo": "ଫଟୋ ହଟାନ୍ତୁ",
    "Demora %@": "Demora %@",
    "Blocked user": "ବ୍ଲକ୍ ହୋଇଥିବା ବ୍ୟବହାରକାରୀ",
    "Two removals are pending. Tap Select, choose both, Apply — then approve with your trusted contact instead of the password.": "ଦୁଇଟି ହଟାଇବା ଅପେକ୍ଷାରେ। ବାଛନ୍ତୁ ଟ୍ୟାପ୍ କରନ୍ତୁ, ଦୁଇଟିଯାକ ବାଛନ୍ତୁ, ଲାଗୁ କରନ୍ତୁ — ତା’ପରେ ପାସୱାର୍ଡ ବଦଳରେ ଆପଣଙ୍କ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତିଙ୍କ ଦ୍ୱାରା ଅନୁମୋଦନ କରାନ୍ତୁ।",
    "Waiting for approval…": "ଅନୁମୋଦନର ଅପେକ୍ଷାରେ…",
    "%d changes: %@": "%d ଟି ବଦଳ: %@",
    "Awaiting approval": "ଅନୁମୋଦନର ଅପେକ୍ଷାରେ",
    "Tap to enter the email code": "ଇମେଲ୍ କୋଡ୍ ଦେବାକୁ ଟ୍ୟାପ୍ କରନ୍ତୁ",
    "Encrypted request — re-add this contact to read it.": "ଏନକ୍ରିପ୍ଟ ହୋଇଥିବା ଅନୁରୋଧ — ପଢ଼ିବାକୁ ଏହି ଯୋଗାଯୋଗ ପୁଣି ଯୋଡ଼ନ୍ତୁ।",
    "Privacy Policy": "ଗୋପନୀୟତା ନୀତି",
    "Terms of Use": "ବ୍ୟବହାର ସର୍ତ୍ତାବଳୀ",
    "Almost done": "ପ୍ରାୟ ଶେଷ",
    "Nice work — that's the whole loop. Now set the delays and overrides that will actually protect you.": "ବଢ଼ିଆ କାମ — ଏହା ପୂରା ଚକ୍ର ଥିଲା। ଏବେ ଆପଣଙ୍କୁ ପ୍ରକୃତରେ ସୁରକ୍ଷା ଦେବା ଅପେକ୍ଷା ଓ ଓଭରରାଇଡ୍ ଠିକ୍ କରନ୍ତୁ।",
    "Finish setup": "ସେଟଅପ୍ ଶେଷ କରନ୍ତୁ",
    "Tap ‘Add your first limit’, choose an app or two and a daily budget, then queue the change.": "‘ଆପଣଙ୍କ ପ୍ରଥମ ସୀମା ଯୋଡ଼ନ୍ତୁ’ ଟ୍ୟାପ୍ କରନ୍ତୁ, ଗୋଟିଏ-ଦୁଇଟି ଆପ୍ ଓ ଦୈନିକ ବଜେଟ୍ ବାଛନ୍ତୁ, ତା’ପରେ ବଦଳ ଧାଡ଼ିରେ ରଖନ୍ତୁ।",
    "Your change is waiting out its delay — and you can't wait this one out. Tap ‘Apply now…’ and use the password override. The password is: test": "ଆପଣଙ୍କ ବଦଳ ତାହାର ଅପେକ୍ଷା ପୂରଣ କରୁଛି — ଓ ଏହା ଆପଣ ପୂରଣ କରିପାରିବେ ନାହିଁ। ‘ଏବେ ଲାଗୁ କରନ୍ତୁ…’ ଟ୍ୟାପ୍ କରି ପାସୱାର୍ଡ ଓଭରରାଇଡ୍ ବ୍ୟବହାର କରନ୍ତୁ। ପାସୱାର୍ଡ: test",
    "Now remove it: tap the limit, then ‘Remove this limit’.": "ଏବେ ହଟାନ୍ତୁ: ସୀମା ଉପରେ ଟ୍ୟାପ୍ କରନ୍ତୁ, ତା’ପରେ ‘ଏହି ସୀମା ହଟାନ୍ତୁ’।",
    "Same again — tap ‘Apply now…’ and enter the password (test).": "ପୁଣି ସେମିତି — ‘ଏବେ ଲାଗୁ କରନ୍ତୁ…’ ଟ୍ୟାପ୍ କରି ପାସୱାର୍ଡ (test) ଦିଅନ୍ତୁ।",
    "For this tutorial, only the password works. The password is: test": "ଏହି ଟ୍ୟୁଟୋରିଆଲ୍‌ରେ କେବଳ ପାସୱାର୍ଡ କାମ କରେ। ପାସୱାର୍ଡ: test",
    "Everything here is just a sample — nothing is saved and nothing is actually blocked. It's only to show how the app works.": "ଏଠାର ସବୁକିଛି କେବଳ ନମୁନା — କିଛି ସେଭ୍ ହୁଏ ନାହିଁ ଓ କିଛି ପ୍ରକୃତରେ ବ୍ଲକ୍ ହୁଏ ନାହିଁ। ଆପ୍ କିପରି କାମ କରେ ଦେଖାଇବାକୁ ହିଁ ଏହା।",
    "Applying…": "ଲାଗୁ ହେଉଛି…",
    "Confirm": "ନିଶ୍ଚିତ କରନ୍ତୁ",
    "Apps": "ଆପ୍",
    "Apps that stay usable": "ବ୍ୟବହାରଯୋଗ୍ୟ ରହୁଥିବା ଆପ୍",
    "Apps to block": "ବ୍ଲକ୍ କରିବାକୁ ଆପ୍",
    "Nothing selected": "କିଛି ବଛା ହୋଇ ନାହିଁ",
    "Apps blocked": "ଆପ୍ ବ୍ଲକ୍ ହୋଇଛି",
    "Apps unblocked": "ଆପ୍ ଅନବ୍ଲକ୍ ହୋଇଛି",
    "Blocking the selected apps": "ବଛା ଆପ୍ ବ୍ଲକ୍ ହେଉଛି",
    "Unblocking the selected apps": "ବଛା ଆପ୍ ଅନବ୍ଲକ୍ ହେଉଛି",
    "Apps to unblock": "ଅନବ୍ଲକ୍ କରିବାକୁ ଆପ୍",
    "Authorize": "ଅଧିକୃତ କରନ୍ତୁ",
    "Authorized ✓": "ଅଧିକୃତ ✓",
    "Back": "ପଛକୁ",
    "Beta testers": "ବିଟା ପରୀକ୍ଷକ",
    "Block": "ବ୍ଲକ୍ କରନ୍ତୁ",
    "Block all except…": "ଏଗୁଡ଼ିକ ବ୍ୟତୀତ ସବୁ ବ୍ଲକ୍ କରନ୍ତୁ…",
    "Block app deletion": "ଆପ୍ ମାଡ଼ିବା ବ୍ଲକ୍ କରନ୍ତୁ",
    "Block apps": "ଆପ୍ ବ୍ଲକ୍ କରନ୍ତୁ",
    "Block only…": "କେବଳ ଏଗୁଡ଼ିକ ବ୍ଲକ୍ କରନ୍ତୁ…",
    "Blocked by Demora": "Demora ଦ୍ୱାରା ବ୍ଲକ୍",
    "Blocking is enforced by iOS itself through Screen Time, the same system parental controls use.": "ବ୍ଲକ୍ ନିଜେ iOS ଦ୍ୱାରା ସ୍କ୍ରିନ୍ ଟାଇମ୍ ମାଧ୍ୟମରେ ଲାଗୁ ହୁଏ, ଅଭିଭାବକ ନିୟନ୍ତ୍ରଣ ବ୍ୟବହାର କରୁଥିବା ସମାନ ବ୍ୟବସ୍ଥା।",
    "Cancel": "ବାତିଲ୍",
    "Change %@ to %d min/day": "%@ କୁ %d ମି/ଦିନ କରନ୍ତୁ",
    "Changes that make things LESS STRICT (raise a limit, remove a block, add a free period) wait out your second delay — usually set longer.": "ଯେଉଁ ବଦଳ ଜିନିଷକୁ କମ୍ କଡ଼ା କରେ (ସୀମା ବଢ଼ାଇବା, ବ୍ଲକ୍ ହଟାଇବା, ମୁକ୍ତ ସମୟ ଯୋଡ଼ିବା) ତାହା ଆପଣଙ୍କ ଦ୍ୱିତୀୟ ଅପେକ୍ଷା ପୂରଣ କରେ — ସାଧାରଣତଃ ଅଧିକ ଲମ୍ବା।",
    "Changes that make things STRICTER (add a limit, lower minutes, add a schedule) wait out your first delay.": "ଯେଉଁ ବଦଳ ଜିନିଷକୁ ଅଧିକ କଡ଼ା କରେ (ସୀମା ଯୋଡ଼ିବା, ମିନିଟ୍ କମାଇବା, ସମୟସୂଚୀ ଯୋଡ଼ିବା) ତାହା ଆପଣଙ୍କ ପ୍ରଥମ ଅପେକ୍ଷା ପୂରଣ କରେ।",
    "Changes you make will appear here with a countdown.": "ଆପଣ କରିଥିବା ବଦଳ କାଉଣ୍ଟଡାଉନ୍ ସହ ଏଠାରେ ଦେଖାଯିବ।",
    "Choose apps": "ଆପ୍ ବାଛନ୍ତୁ",
    "Close": "ବନ୍ଦ କରନ୍ତୁ",
    "Confirm password": "ପାସୱାର୍ଡ ନିଶ୍ଚିତ କରନ୍ତୁ",
    "Continue": "ଜାରି ରଖନ୍ତୁ",
    "Couldn't load names (check iCloud/network).": "ନାମ ଲୋଡ୍ ହୋଇପାରିଲା ନାହିଁ (iCloud/ନେଟୱର୍କ ଯାଞ୍ଚ କରନ୍ତୁ)।",
    "Couldn't submit — make sure you're signed into iCloud and try again.": "ଦାଖଲ ହୋଇପାରିଲା ନାହିଁ — iCloud ରେ ସାଇନ୍ ଇନ୍ ଅଛି କି ନାହିଁ ଦେଖି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Current delays": "ବର୍ତ୍ତମାନର ଅପେକ୍ଷା",
    "Daily limit": "ଦୈନିକ ସୀମା",
    "Day %d of every month": "ପ୍ରତି ମାସର %d ତାରିଖ",
