    "During a free period, limits don't block and usage inside the window doesn't count toward them — time used before the window still does.": "ମୁକ୍ତ ସମୟରେ ସୀମା ବ୍ଲକ୍ କରେ ନାହିଁ, ଓ ଝରକା ଭିତରର ବ୍ୟବହାର ସେଥିରେ ଗଣାଯାଏ ନାହିଁ — ଝରକା ପୂର୍ବର ସମୟ ଏବେ ବି ଗଣାଯାଏ।",
