    "Ends": "ଶେଷ ହୁଏ",
    "Enter password": "ପାସୱାର୍ଡ ଦିଅନ୍ତୁ",
    "Every change you make waits out a delay you chose, counting down in the background. You can always change your rules — just not in a moment of weakness.": "ଆପଣ କରିଥିବା ପ୍ରତ୍ୟେକ ବଦଳ ଆପଣ ବାଛିଥିବା ଅପେକ୍ଷା ପୂରଣ କରେ, ବ୍ୟାକ୍‌ଗ୍ରାଉଣ୍ଡ୍‌ରେ କାଉଣ୍ଟଡାଉନ୍ ଚାଲେ। ଆପଣ ନିୟମ ସବୁବେଳେ ବଦଳାଇପାରିବେ — କେବଳ ଦୁର୍ବଳ କ୍ଷଣରେ ନୁହେଁ।",
    "Every day": "ପ୍ରତିଦିନ",
    "Everything on the iPhone is blocked during the window except the apps picked here.": "ଝରକା ସମୟରେ iPhone ର ସବୁକିଛି ବ୍ଲକ୍ ରହେ, କେବଳ ଏଠାରେ ବଛା ଆପ୍ ବ୍ୟତୀତ।",
    "Free period": "ମୁକ୍ତ ସମୟ",
    "Today's usage is reported by iOS Screen Time, which can be slow to load or briefly show nothing. If it looks empty, tap the refresh arrow a couple of times.": "ଆଜିର ବ୍ୟବହାର iOS ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଜଣାଏ, ଯାହା ଲୋଡ୍ ହେବାକୁ ବିଳମ୍ବ କରିପାରେ କିମ୍ବା କିଛି ସମୟ କିଛି ଦେଖାଇପାରେ ନାହିଁ। ଖାଲି ଲାଗିଲେ ରିଫ୍ରେସ୍ ତୀର ଉପରେ କେତେଥର ଟ୍ୟାପ୍ କରନ୍ତୁ।",
    "Free": "ମୁକ୍ତ",
    "Free period: %@ (%d min)": "ମୁକ୍ତ ସମୟ: %@ (%d ମି)",
    "Free period — nothing is blocked": "ମୁକ୍ତ ସମୟ — କିଛି ବ୍ଲକ୍ ନାହିଁ",
    "Temporarily lifts everything — no app blocks apply, and usage during the free period doesn't count toward your limits.": "ଅସ୍ଥାୟୀ ଭାବେ ସବୁକିଛି ଉଠାଇ ନିଏ — କୌଣସି ଆପ୍ ବ୍ଲକ୍ ଲାଗୁ ନାହିଁ, ଓ ମୁକ୍ତ ସମୟର ବ୍ୟବହାର ଆପଣଙ୍କ ସୀମାରେ ଗଣାଯାଏ ନାହିଁ।",
    "Free periods": "ମୁକ୍ତ ସମୟ",
