    "How does it work?": "ଏହା କିପରି କାମ କରେ?",
    "Keep it appropriate — names are reviewed, and inappropriate ones won't be added.": "ଶାଳୀନ ରଖନ୍ତୁ — ନାମ ଦେଖାଯାଏ, ଅନୁପଯୁକ୍ତ ନାମ ଯୋଡ଼ାଯିବ ନାହିଁ।",
    "Language": "ଭାଷା",
    "Demora needs Screen Time authorization to set app limits and block apps. iOS will ask for your confirmation.": "ଆପ୍ ସୀମା ଠିକ୍ କରିବାକୁ ଓ ଆପ୍ ବ୍ଲକ୍ କରିବାକୁ Demora କୁ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଅଧିକାର ଦରକାର। iOS ଆପଣଙ୍କ ନିଶ୍ଚିତକରଣ ମାଗିବ।",
    "Demora wouldn't exist without the people who tested it, broke it, and told me about it. Thank you. ❤️": "ଯେଉଁମାନେ Demora ପରୀକ୍ଷା କଲେ, ଭାଙ୍ଗିଲେ ଓ ମୋତେ ଜଣାଇଲେ ସେମାନଙ୍କ ବିନା Demora ନଥାନ୍ତା। ଧନ୍ୟବାଦ। ❤️",
    "Less strict": "କମ୍ କଡ଼ା",
    "Less-strict delay": "କମ୍ କଡ଼ା ଅପେକ୍ଷା",
    "Limit": "ସୀମା",
    "Limits": "ସୀମା",
    "Limits won't block and usage won't count during this window.": "ଏହି ଝରକାରେ ସୀମା ବ୍ଲକ୍ କରିବ ନାହିଁ ଓ ବ୍ୟବହାର ଗଣାଯିବ ନାହିଁ।",
    "Limits: daily time budgets per app. When the minutes run out, the app is blocked until midnight.": "ସୀମା: ଆପ୍ ଅନୁସାରେ ଦୈନିକ ସମୟ ବଜେଟ୍। ମିନିଟ୍ ଶେଷ ହେଲେ ଆପ୍ ମଧ୍ୟରାତ୍ରି ପର୍ଯ୍ୟନ୍ତ ବ୍ଲକ୍ ରହେ।",
    "Looser changes": "ଢିଲା ବଦଳ",
    "Looser changes wait %@": "ଢିଲା ବଦଳ %@ ଅପେକ୍ଷା କରେ",
    "Math problems": "ଗଣିତ ପ୍ରଶ୍ନ",
