    "Mode": "ଧରଣ",
    "Monthly schedules can't cross midnight — set the end time after the start time.": "ମାସିକ ସମୟସୂଚୀ ମଧ୍ୟରାତ୍ରି ଅତିକ୍ରମ କରିପାରିବ ନାହିଁ — ଶେଷ ସମୟ ଆରମ୍ଭ ପରେ ରଖନ୍ତୁ।",
    "More strict": "ଅଧିକ କଡ଼ା",
    "More-strict delay": "କଡ଼ା ଅପେକ୍ଷା",
    "Most screen-time apps protect your rules with a password — which you know, so you cave. Demora protects them with time instead.": "ଅଧିକାଂଶ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆପ୍ ଆପଣଙ୍କ ନିୟମ ପାସୱାର୍ଡ ଦ୍ୱାରା ସୁରକ୍ଷିତ ରଖେ — ଯାହା ଆପଣ ଜାଣନ୍ତି, ତେଣୁ ହାର ମାନନ୍ତି। Demora ବଦଳରେ ସମୟ ଦ୍ୱାରା ସୁରକ୍ଷିତ ରଖେ।",
    "Name": "ନାମ",
