    "Off": "ବନ୍ଦ",
    "On": "ଚାଲୁ",
    "One-off and unplanned, but still delay-gated. A block session waits %@; an unblock session waits %@. Ending early flips the rule (or use an override).": "ଏକ-ଥର ଓ ଅଯୋଜିତ, ତଥାପି ଅପେକ୍ଷାଧୀନ। ବ୍ଲକ୍ ସେସନ୍ %@ ଅପେକ୍ଷା କରେ; ଅନବ୍ଲକ୍ ସେସନ୍ %@ ଅପେକ୍ଷା କରେ। ଆଗରୁ ଶେଷ କଲେ ନିୟମ ଓଲଟିଯାଏ (କିମ୍ବା ଓଭରରାଇଡ୍ ବ୍ୟବହାର କରନ୍ତୁ)।",
    "Only the apps picked here are blocked during the window.": "ଝରକା ସମୟରେ କେବଳ ଏଠାରେ ବଛା ଆପ୍ ବ୍ଲକ୍ ରହେ।",
    "Overrides": "ଓଭରରାଇଡ୍",
    "Overrides enabled": "ଓଭରରାଇଡ୍ ଚାଲୁ",
    "Overrides let you skip a pending change's countdown. They're off by default. Adding one later counts as a less-strict change; removing one counts as stricter — both go through delays.": "ଓଭରରାଇଡ୍ ଅପେକ୍ଷାରେ ଥିବା ବଦଳର କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବାକୁ ଦିଏ। ଏଗୁଡ଼ିକ ଡିଫଲ୍ଟରେ ବନ୍ଦ। ପରେ ଗୋଟିଏ ଯୋଡ଼ିବା କମ୍ କଡ଼ା ବଦଳ ଗଣାଯାଏ; ହଟାଇବା କଡ଼ା — ଦୁହିଁ ଅପେକ୍ଷା ଦେଇ ଯାଏ।",
    "Overrides skip a pending change's countdown. Enabling or weakening one is a less-strict change; disabling or strengthening one is stricter. All edits here go through the matching delay.": "ଓଭରରାଇଡ୍ ଅପେକ୍ଷାରେ ଥିବା ବଦଳର କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଏ। ଗୋଟିଏ ଚାଲୁ କରିବା କିମ୍ବା ଦୁର୍ବଳ କରିବା କମ୍ କଡ଼ା ବଦଳ; ବନ୍ଦ କରିବା କିମ୍ବା ମଜବୁତ କରିବା କଡ଼ା। ଏଠାର ସମସ୍ତ ବଦଳ ମେଳ ଖାଉଥିବା ଅପେକ୍ଷା ଦେଇ ଯାଏ।",
    "A change for this setting is already pending. Cancel it on the Home tab first if you want something different.": "ଏହି ସେଟିଂର ଏକ ବଦଳ ଆଗରୁ ଅପେକ୍ଷାରେ ଅଛି। ଅନ୍ୟ କିଛି ଚାହିଁଲେ ପ୍ରଥମେ ହୋମ୍ ଟାବ୍‌ରେ ତାହା ବାତିଲ୍ କରନ୍ତୁ।",
    "Already pending": "ଆଗରୁ ଅପେକ୍ଷାରେ",
    "Add": "ଯୋଡ଼ନ୍ତୁ",
