    "Cancels this request and lets you pick contacts again.": "ଏହି ଅନୁରୋଧ ବାତିଲ୍ କରେ ଓ ଆପଣଙ୍କୁ ପୁଣି ଯୋଗାଯୋଗ ବାଛିବାକୁ ଦିଏ।",
