    "/ de·mo·ra /  noun, Spanish": "/ de·mo·ra /  ବିଶେଷ୍ୟ, ସ୍ପାନିଶ୍",
    "a delay; the time that passes before something takes effect.": "ଏକ ଅପେକ୍ଷା; କିଛି ଲାଗୁ ହେବା ପୂର୍ବରୁ ଯେଉଁ ସମୟ ଅତିବାହିତ ହୁଏ।",
    "an iPhone app that protects your screen-time rules with definition 1 instead of a password.": "ଏକ iPhone ଆପ୍ ଯାହା ପାସୱାର୍ଡ ବଦଳରେ ସଂଜ୍ଞା ୧ ଦ୍ୱାରା ଆପଣଙ୍କ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ନିୟମ ସୁରକ୍ଷିତ ରଖେ।",
    "Coming soon — payments aren't available yet.": "ଶୀଘ୍ର ଆସୁଛି — ପେମେଣ୍ଟ ଏପର୍ଯ୍ୟନ୍ତ ଉପଲବ୍ଧ ନୁହେଁ।",
