    "Pending change": "ଅପେକ୍ଷାରେ ଥିବା ବଦଳ",
    "Pending changes": "ଅପେକ୍ଷାରେ ଥିବା ବଦଳ",
    "Pending changes show on the Home tab with a live countdown. You can cancel them anytime before they apply.": "ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ହୋମ୍ ଟାବ୍‌ରେ ଜୀବନ୍ତ କାଉଣ୍ଟଡାଉନ୍ ସହ ଦେଖାଯାଏ। ଲାଗୁ ହେବା ପୂର୍ବରୁ ଯେକୌଣସି ସମୟରେ ବାତିଲ୍ କରିପାରିବେ।",
