    "Plan a window": "ଏକ ଝରକା ଯୋଜନା କରନ୍ତୁ",
    "Plan a window…": "ଏକ ଝରକା ଯୋଜନା କରନ୍ତୁ…",
    "Plan ahead for specific dates — a trip, a weekend, an exam. Doesn't repeat. Planning a block is stricter; planning a free period is less strict.": "ନିର୍ଦ୍ଦିଷ୍ଟ ତାରିଖ ପାଇଁ ଆଗରୁ ଯୋଜନା କରନ୍ତୁ — ଯାତ୍ରା, ସପ୍ତାହାନ୍ତ, ପରୀକ୍ଷା। ପୁନରାବୃତ୍ତ ହୁଏ ନାହିଁ। ବ୍ଲକ୍ ଯୋଜନା କଡ଼ା; ମୁକ୍ତ ସମୟ ଯୋଜନା କମ୍ କଡ଼ା।",
    "Planned (one-off)": "ଯୋଜିତ (ଏକ-ଥର)",
    "Planned window": "ଯୋଜିତ ଝରକା",
    "Purchasing…": "କିଣା ହେଉଛି…",
    "Queue change": "ବଦଳ ଧାଡ଼ିରେ ରଖନ୍ତୁ",
    "Recurring schedules": "ପୁନରାବୃତ୍ତ ସମୟସୂଚୀ",
    "Remove free period: %@": "ମୁକ୍ତ ସମୟ ହଟାନ୍ତୁ: %@",
    "Remove limit: %@": "ସୀମା ହଟାନ୍ତୁ: %@",
    "Remove planned window: %@": "ଯୋଜିତ ଝରକା ହଟାନ୍ତୁ: %@",
    "Remove schedule: %@": "ସମୟସୂଚୀ ହଟାନ୍ତୁ: %@",
    "Remove this limit": "ଏହି ସୀମା ହଟାନ୍ତୁ",
    "Remove…": "ହଟାନ୍ତୁ…",
    "Repeating windows: every day, chosen weekdays, or monthly patterns. Adding waits %@; removing waits %@.": "ପୁନରାବୃତ୍ତ ଝରକା: ପ୍ରତିଦିନ, ବଛା ସପ୍ତାହ ଦିନ, କିମ୍ବା ମାସିକ ଢାଞ୍ଚା। ଯୋଡ଼ିବାକୁ %@ ଅପେକ୍ଷା; ହଟାଇବାକୁ %@ ଅପେକ୍ଷା।",
    "Repeats": "ପୁନରାବୃତ୍ତ ହୁଏ",
    "Schedule": "ସମୟସୂଚୀ",
    "Schedules": "ସମୟସୂଚୀ",
    "Schedules: recurring or one-off windows that block chosen apps — or everything except a chosen few. Plus free periods where time doesn't count.": "ସମୟସୂଚୀ: ପୁନରାବୃତ୍ତ କିମ୍ବା ଏକ-ଥର ଝରକା ଯାହା ବଛା ଆପ୍ ବ୍ଲକ୍ କରେ — କିମ୍ବା କିଛି ବ୍ୟତୀତ ସବୁ। ସହିତ ମୁକ୍ତ ସମୟ, ଯେଉଁଠି ସମୟ ଗଣାଯାଏ ନାହିଁ।",
    "Screen Time access": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆକ୍ସେସ୍",
    "Sessions": "ସେସନ୍",
    "Set 'less strict' delay to %@": "'କମ୍ କଡ଼ା' ଅପେକ୍ଷା %@ କରନ୍ତୁ",
    "Set 'more strict' delay to %@": "'କଡ଼ା' ଅପେକ୍ଷା %@ କରନ୍ତୁ",
    "Settings": "ସେଟିଂସ୍",
    "Setup": "ସେଟଅପ୍",
    "Simulate payment (beta)": "ପେମେଣ୍ଟ ସିମୁଲେଟ୍ କରନ୍ତୁ (ବିଟା)",
    "Skip the wait": "ଅପେକ୍ଷା ଏଡ଼ାନ୍ତୁ",
    "Solve %d math problems (%@)": "%d ଟି ଗଣିତ ପ୍ରଶ୍ନ ସମାଧାନ କରନ୍ତୁ (%@)",
    "Solve math problems": "ଗଣିତ ପ୍ରଶ୍ନ ସମାଧାନ କରନ୍ତୁ",
    "Start": "ଆରମ୍ଭ",
    "Start using Demora": "Demora ବ୍ୟବହାର ଆରମ୍ଭ କରନ୍ତୁ",
    "Starts": "ଆରମ୍ଭ ହୁଏ",
    "Stricter changes": "ଅଧିକ କଡ଼ା ବଦଳ",
    "Stricter changes wait %@": "ଅଧିକ କଡ଼ା ବଦଳ %@ ଅପେକ୍ଷା କରେ",
    "Temporarily lifts limits, schedules, and block sessions for the chosen apps.": "ବଛା ଆପ୍ ପାଇଁ ସୀମା, ସମୟସୂଚୀ ଓ ବ୍ଲକ୍ ସେସନ୍ ଅସ୍ଥାୟୀ ଭାବେ ଉଠାଇ ନିଏ।",
    "Thanks for testing Demora!": "Demora ପରୀକ୍ଷା କରିଥିବାରୁ ଧନ୍ୟବାଦ!",
    "This app is blocked right now — by a limit, a schedule, or a session. Changing your rules takes a delay; open Demora to queue a change.": "ଏହି ଆପ୍ ଏବେ ବ୍ଲକ୍ — ଏକ ସୀମା, ସମୟସୂଚୀ କିମ୍ବା ସେସନ୍ କାରଣରୁ। ନିୟମ ବଦଳାଇବାକୁ ଅପେକ୍ଷା ଲାଗେ; ବଦଳ ଧାଡ଼ିରେ ରଖିବାକୁ Demora ଖୋଲନ୍ତୁ।",
    "If it should already be unblocked, iOS is sometimes slow to apply a background change — open Demora for an immediate unblock.": "ଏତିକିବେଳକୁ ଅନବ୍ଲକ୍ ହେବା କଥା ହେଲେ, iOS କେବେ କେବେ ବ୍ୟାକ୍‌ଗ୍ରାଉଣ୍ଡ୍ ବଦଳ ଲାଗୁ କରିବାରେ ଧୀର — ତୁରନ୍ତ ଅନବ୍ଲକ୍ ପାଇଁ Demora ଖୋଲନ୍ତୁ।",
    "Two delays rule everything": "ଦୁଇଟି ଅପେକ୍ଷା ସବୁକିଛି ଚଳାଏ",
    "Type": "ପ୍ରକାର",
    "Unblock": "ଅନବ୍ଲକ୍ କରନ୍ତୁ",
    "Unblock apps": "ଆପ୍ ଅନବ୍ଲକ୍ କରନ୍ତୁ",
    "Wait this long before any change that loosens your rules takes effect. Usually set longer than the first.": "ଆପଣଙ୍କ ନିୟମ ଢିଲା କରୁଥିବା ଯେକୌଣସି ବଦଳ ଲାଗୁ ହେବା ପୂର୍ବରୁ ଏତେ ସମୟ ଅପେକ୍ଷା କରନ୍ତୁ। ସାଧାରଣତଃ ପ୍ରଥମଠାରୁ ଲମ୍ବା।",
    "Wait this long before any change that tightens your rules takes effect.": "ଆପଣଙ୍କ ନିୟମ କଡ଼ା କରୁଥିବା ଯେକୌଣସି ବଦଳ ଲାଗୁ ହେବା ପୂର୍ବରୁ ଏତେ ସମୟ ଅପେକ୍ଷା କରନ୍ତୁ।",
    "Want your name in the app's beta-tester thanks page? Pick whatever you'd like to be called.": "ଆପ୍ ର ବିଟା-ପରୀକ୍ଷକ ଧନ୍ୟବାଦ ପୃଷ୍ଠାରେ ଆପଣଙ୍କ ନାମ ଚାହୁଁଛନ୍ତି? ଆପଣ ଯେଉଁ ନାମରେ ଡକାଯିବାକୁ ଚାହାନ୍ତି ଲେଖନ୍ତୁ।",
    "Weekday": "ସପ୍ତାହର ଦିନ",
    "Weekdays": "ସପ୍ତାହର ଦିନ",
    "What can it do?": "ଏହା କ’ଣ କରିପାରେ?",
    "What's in the box": "ବାକ୍ସରେ କ’ଣ ଅଛି",
    "When": "କେବେ",
    "When on, deleting ANY app from this iPhone is blocked — including Demora itself, so blocks can't be bypassed by uninstalling.": "ଚାଲୁ ଥିଲେ ଏହି iPhone ରୁ ଯେକୌଣସି ଆପ୍ ମାଡ଼ିବା ବ୍ଲକ୍ ହୁଏ — Demora ନିଜେ ମଧ୍ୟ, ତେଣୁ ଅନଇନଷ୍ଟଲ୍ କରି ବ୍ଲକ୍ ଏଡ଼ାଯାଇପାରେ ନାହିଁ।",
    "Which one": "କେଉଁଟି",
    "Window": "ଝରକା",
    "Wrong — new problem": "ଭୁଲ — ନୂଆ ପ୍ରଶ୍ନ",
    "You're in! Your name will appear in the beta testers page once it's approved.": "ଆପଣ ଯୋଡ଼ିହୋଇଗଲେ! ଅନୁମୋଦିତ ହେଲେ ଆପଣଙ୍କ ନାମ ବିଟା ପରୀକ୍ଷକ ପୃଷ୍ଠାରେ ଦେଖାଯିବ।",
    "You're set": "ଆପଣ ପ୍ରସ୍ତୁତ",
    "Your name is in — it'll show up once approved.": "ଆପଣଙ୍କ ନାମ ଦାଖଲ ହୋଇଛି — ଅନୁମୋଦିତ ହେଲେ ଦେଖାଯିବ।",
    "Your name or nickname": "ଆପଣଙ୍କ ନାମ କିମ୍ବା ଡାକନାମ",
    "e.g. Airport, weekend trip": "ଯଥା ବିମାନ ବନ୍ଦର, ସପ୍ତାହାନ୍ତ ଯାତ୍ରା",
    "e.g. Bedtime": "ଯଥା ଶୋଇବା ସମୟ",
    "e.g. Deep work": "ଯଥା ଗଭୀର କାମ",
    "e.g. Instagram": "ଯଥା Instagram",
    "e.g. Lunch break": "ଯଥା ମଧ୍ୟାହ୍ନ ବିରତି",
    "free period": "ମୁକ୍ତ ସମୟ",
    "limit": "ସୀମା",
    "now": "ଏବେ",
    "planned window": "ଯୋଜିତ ଝରକା",
    "schedule": "ସମୟସୂଚୀ",
    "session": "ସେସନ୍",
    // Prevent disabling, walkthrough replay — added after the
    // 2026-07 update (App Attest, ContactCrypto, LatchReport extension).
    "A passcode is saved. Open the guide below to view it.": "ଏକ ପାସ୍‌କୋଡ୍ ସେଭ୍ ହୋଇଛି। ଦେଖିବାକୁ ତଳର ଗାଇଡ୍ ଖୋଲନ୍ତୁ।",
    "Can't reach this contact right now — they may have removed Demora or signed out. They won't be able to approve until they're back.": "ଏବେ ଏହି ଯୋଗାଯୋଗଙ୍କୁ ପାଇହେଉନାହିଁ — ସେ Demora ହଟାଇଥାଇପାରନ୍ତି କିମ୍ବା ସାଇନ୍ ଆଉଟ୍ କରିଥାଇପାରନ୍ତି। ସେ ଫେରିବା ପର୍ଯ୍ୟନ୍ତ ଅନୁମୋଦନ କରିପାରିବେ ନାହିଁ।",
    "Couldn't start the walkthrough": "ୱାକ୍‌ଥ୍ରୁ ଆରମ୍ଭ କରାଯାଇପାରିଲା ନାହିଁ",
    "Bug tracker": "ବଗ୍ ଟ୍ରାକର୍",
    "Demora can't stop you from turning off its Screen Time access in iOS Settings — but a friend can. If Screen Time itself is locked with someone else's passcode, iOS blocks any change to Demora's access, while Demora keeps doing all the blocking.": "iOS ସେଟିଂସ୍‌ରେ Demora ର ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆକ୍ସେସ୍ ବନ୍ଦ କରିବାରୁ Demora ଆପଣଙ୍କୁ ରୋକିପାରେ ନାହିଁ — କିନ୍ତୁ ବନ୍ଧୁ ରୋକିପାରିବେ। ସ୍କ୍ରିନ୍ ଟାଇମ୍ ନିଜେ ଅନ୍ୟ କାହାର ପାସ୍‌କୋଡ୍‌ରେ ଲକ୍ ଥିଲେ, iOS Demora ର ଆକ୍ସେସ୍‌ର ଯେକୌଣସି ବଦଳ ରୋକେ, ଓ Demora ସବୁ ବ୍ଲକ୍ କରିବା ଜାରି ରଖେ।",
    "Demora couldn't safely back up your current setup, so the replay was cancelled to protect your limits. Nothing was changed. Please try again in a moment.": "Demora ଆପଣଙ୍କ ବର୍ତ୍ତମାନର ସେଟଅପ୍ ସୁରକ୍ଷିତ ଭାବେ ବ୍ୟାକଅପ୍ କରିପାରିଲା ନାହିଁ, ତେଣୁ ଆପଣଙ୍କ ସୀମା ସୁରକ୍ଷିତ ରଖିବାକୁ ରିପ୍ଲେ ବାତିଲ୍ ହେଲା। କିଛି ବଦଳି ନାହିଁ। କିଛି ସମୟ ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Done. Now you can't disable Demora's access — or change the passcode — without your friend. To undo it later, your friend enters the passcode and turns it off.": "ହୋଇଗଲା। ଏବେ ଆପଣଙ୍କ ବନ୍ଧୁ ବିନା ଆପଣ Demora ର ଆକ୍ସେସ୍ ବନ୍ଦ କରିପାରିବେ ନାହିଁ — କିମ୍ବା ପାସ୍‌କୋଡ୍ ବଦଳାଇପାରିବେ ନାହିଁ। ପରେ ଫେରାଇବାକୁ ଆପଣଙ୍କ ବନ୍ଧୁ ପାସ୍‌କୋଡ୍ ଦେଇ ତାହା ବନ୍ଦ କରନ୍ତି।",
    "Email limit": "ଇମେଲ୍ ସୀମା",
    "Emoji": "ଇମୋଜି",
    "Friend: save the passcode here so it isn't lost. It's only shown from this page, which is behind your delay.": "ବନ୍ଧୁ: ପାସ୍‌କୋଡ୍ ଏଠାରେ ସେଭ୍ କରନ୍ତୁ ଯେପରି ହଜିବ ନାହିଁ। ଏହା କେବଳ ଏହି ପୃଷ୍ଠାରୁ ଦେଖାଯାଏ, ଯାହା ଆପଣଙ୍କ ଅପେକ୍ଷା ପଛରେ।",
    "Hand your phone to your friend. Have THEM enter a 4-digit passcode you don't see — don't watch.": "ଆପଣଙ୍କ ଫୋନ୍ ବନ୍ଧୁଙ୍କୁ ଦିଅନ୍ତୁ। ତାଙ୍କୁ ୪ ଅଙ୍କର ଏକ ପାସ୍‌କୋଡ୍ ଦେବାକୁ କହନ୍ତୁ ଯାହା ଆପଣ ଦେଖିବେ ନାହିଁ — ଦେଖନ୍ତୁ ନାହିଁ।",
    "Heads up: on your iOS version, a limit only counts screen time from the moment you add it — time you already spent earlier today isn't included. Update to iOS 17.4 or later for exact daily counting.": "ସାବଧାନ: ଆପଣଙ୍କ iOS ସଂସ୍କରଣରେ ସୀମା ଯୋଡ଼ିବା କ୍ଷଣରୁ ହିଁ ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଗଣାଯାଏ — ଆଜି ଆଗରୁ ବିତିଥିବା ସମୟ ଅନ୍ତର୍ଭୁକ୍ତ ନୁହେଁ। ସଠିକ୍ ଦୈନିକ ଗଣନା ପାଇଁ iOS 17.4 କିମ୍ବା ପରବର୍ତ୍ତୀକୁ ଅପଡେଟ୍ କରନ୍ତୁ।",
    "Onboarding demo — you can skip below. It's always available again in Settings → Help.": "ଅନବୋର୍ଡିଂ ଡେମୋ — ଆପଣ ତଳେ ଛାଡ଼ିପାରିବେ। ଏହା ସବୁବେଳେ ସେଟିଂସ୍ → ସାହାଯ୍ୟ ରେ ପୁଣି ଉପଲବ୍ଧ।",
    "One more safeguard": "ଆଉ ଏକ ସୁରକ୍ଷା",
    "Open Settings → Screen Time on this iPhone. If it's off, turn it on.": "ଏହି iPhone ରେ ସେଟିଂସ୍ → ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଖୋଲନ୍ତୁ। ବନ୍ଦ ଥିଲେ ଚାଲୁ କରନ୍ତୁ।",
    "Open the guide": "ଗାଇଡ୍ ଖୋଲନ୍ତୁ",
    "Passcode": "ପାସ୍‌କୋଡ୍",
    "Pick someone you trust and can reach. If the passcode and its recovery Apple ID are both lost, removing it may require erasing the device.": "ଆପଣ ଭରସା କରୁଥିବା ଓ ପହଞ୍ଚିହେବା ଭଳି କାହାକୁ ବାଛନ୍ତୁ। ପାସ୍‌କୋଡ୍ ଓ ତାହାର ରିକଭରି Apple ID ଦୁଇଟିଯାକ ହଜିଗଲେ ହଟାଇବାକୁ ଡିଭାଇସ୍ ମାଡ଼ିବାକୁ ପଡ଼ିପାରେ।",
    "Prevent disabling": "ବନ୍ଦ କରିବା ରୋକନ୍ତୁ",
    "Protection": "ସୁରକ୍ଷା",
    "Replay walkthrough": "ୱାକ୍‌ଥ୍ରୁ ପୁଣି ଚଳାନ୍ତୁ",
    "Request access": "ଆକ୍ସେସ୍ ମାଗନ୍ତୁ",
    "Save": "ସେଭ୍ କରନ୍ତୁ",
    "Saved passcode: %@": "ସେଭ୍ ହୋଇଥିବା ପାସ୍‌କୋଡ୍: %@",
    "Unlock viewing the stored passcode": "ସେଭ୍ ହୋଇଥିବା ପାସ୍‌କୋଡ୍ ଦେଖିବା ଅନଲକ୍ କରନ୍ତୁ",
    "Screen Time passcode": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ପାସ୍‌କୋଡ୍",
    "Enter passcode": "ପାସ୍‌କୋଡ୍ ଦିଅନ୍ତୁ",
    "View passcode": "ପାସ୍‌କୋଡ୍ ଦେଖନ୍ତୁ",
    "Change the passcode?": "ପାସ୍‌କୋଡ୍ ବଦଳାଇବେ?",
    "Are you sure? There is no way to undo this — the saved passcode is replaced only when you save a new one.": "ଆପଣ ନିଶ୍ଚିତ କି? ଏହା ଫେରାଇହେବ ନାହିଁ — ନୂଆ ପାସ୍‌କୋଡ୍ ସେଭ୍ କଲେ ହିଁ ସେଭ୍ ହୋଇଥିବା ପାସ୍‌କୋଡ୍ ବଦଳେ।",
    "The friend who set the Screen Time passcode can store it here so it isn't lost. Going back without saving keeps the current one.": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ପାସ୍‌କୋଡ୍ ଦେଇଥିବା ବନ୍ଧୁ ଏଠାରେ ସେଭ୍ କରିପାରିବେ ଯେପରି ହଜିବ ନାହିଁ। ସେଭ୍ ନକରି ପଛକୁ ଗଲେ ବର୍ତ୍ତମାନରଟି ରହେ।",
    "Viewing the stored passcode is behind your less-strict delay: request it, wait out the delay, and you get one look. After that it locks again.": "ସେଭ୍ ହୋଇଥିବା ପାସ୍‌କୋଡ୍ ଦେଖିବା ଆପଣଙ୍କ କମ୍ କଡ଼ା ଅପେକ୍ଷା ପଛରେ: ମାଗନ୍ତୁ, ଅପେକ୍ଷା ପୂରଣ କରନ୍ତୁ, ଓ ଏକ ଥର ଦେଖିବାକୁ ମିଳିବ। ତା’ପରେ ଏହା ପୁଣି ଲକ୍ ହୁଏ।",
    "Access is spent — viewing it again needs a new request.": "ଆକ୍ସେସ୍ ଖର୍ଚ୍ଚ ହୋଇଗଲା — ପୁଣି ଦେଖିବାକୁ ନୂଆ ଅନୁରୋଧ ଦରକାର।",
    "Screen Time usually only allows a 4-digit passcode — are you sure this is correct?": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ସାଧାରଣତଃ କେବଳ ୪ ଅଙ୍କର ପାସ୍‌କୋଡ୍ ନିଏ — ଆପଣ ନିଶ୍ଚିତ ଏହା ଠିକ୍?",
    "Saved ✓": "ସେଭ୍ ହେଲା ✓",
    "Show me how": "କିପରି ଦେଖାନ୍ତୁ",
    "Skip and set up manually": "ଛାଡ଼ି ହାତରେ ସେଟ୍ କରନ୍ତୁ",
    "Skip walkthrough": "ୱାକ୍‌ଥ୍ରୁ ଛାଡ଼ନ୍ତୁ",
    "Skip — set up manually": "ଛାଡ଼ନ୍ତୁ — ହାତରେ ସେଟ୍ କରନ୍ତୁ",
    "Store the Screen Time passcode": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ପାସ୍‌କୋଡ୍ ସେଭ୍ କରନ୍ତୁ",
    "Take photo": "ଫଟୋ ଉଠାନ୍ତୁ",
    "Takes about 2 minutes, and you need a second person physically with you.": "ପ୍ରାୟ ୨ ମିନିଟ୍ ଲାଗେ, ଓ ଆପଣଙ୍କ ସହ ଶାରୀରିକ ଭାବେ ଦ୍ୱିତୀୟ ଜଣେ ଦରକାର।",
    "Tap “Lock Screen Time Settings” (or “Use Screen Time Passcode”).": "“Lock Screen Time Settings” (କିମ୍ବା “Use Screen Time Passcode”) ଉପରେ ଟ୍ୟାପ୍ କରନ୍ତୁ।",
    "Thank you. ❤️": "ଧନ୍ୟବାଦ। ❤️",
    "That's okay. Without Screen Time access Demora can't block apps, but you can continue and turn it on later.": "ଠିକ୍ ଅଛି। ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆକ୍ସେସ୍ ବିନା Demora ଆପ୍ ବ୍ଲକ୍ କରିପାରେ ନାହିଁ, କିନ୍ତୁ ଆପଣ ଜାରି ରଖି ପରେ ଚାଲୁ କରିପାରିବେ।",
    "That's the whole loop. Your real limits, schedules, and settings are still here — nothing changed.": "ଏହା ପୂରା ଚକ୍ର ଥିଲା। ଆପଣଙ୍କ ପ୍ରକୃତ ସୀମା, ସମୟସୂଚୀ ଓ ସେଟିଂସ୍ ଏବେ ବି ଏଠାରେ ଅଛି — କିଛି ବଦଳି ନାହିଁ।",
    "There's a way to make Demora impossible to turn off — with a friend's help. It takes about 2 minutes and needs a second person physically with you.": "ବନ୍ଧୁଙ୍କ ସାହାଯ୍ୟରେ Demora କୁ ବନ୍ଦ କରିହେବ ନାହିଁ ଏପରି କରିବାର ଏକ ଉପାୟ ଅଛି। ପ୍ରାୟ ୨ ମିନିଟ୍ ଲାଗେ ଓ ଆପଣଙ୍କ ସହ ଶାରୀରିକ ଭାବେ ଦ୍ୱିତୀୟ ଜଣେ ଦରକାର।",
    "They call themselves “%@”.": "ସେମାନେ ନିଜକୁ “%@” ବୋଲି ଡାକନ୍ତି।",
    "This guide is behind your less-strict delay: request it, wait out the delay, and you get one open. After you view it, it locks again.": "ଏହି ଗାଇଡ୍ ଆପଣଙ୍କ କମ୍ କଡ଼ା ଅପେକ୍ଷା ପଛରେ: ମାଗନ୍ତୁ, ଅପେକ୍ଷା ପୂରଣ କରନ୍ତୁ, ଓ ଏକ ଥର ଖୋଲିବାକୁ ମିଳିବ। ଦେଖିବା ପରେ ଏହା ପୁଣି ଲକ୍ ହୁଏ।",
    "Unavailable": "ଅନୁପଲବ୍ଧ",
    "Unlock the “Prevent disabling” guide": "“ବନ୍ଦ କରିବା ରୋକନ୍ତୁ” ଗାଇଡ୍ ଅନଲକ୍ କରନ୍ତୁ",
    "Use photo": "ଫଟୋ ବ୍ୟବହାର କରନ୍ତୁ",
    "When asked for Screen Time Passcode Recovery, your friend signs in with THEIR OWN Apple ID — not yours. That's what stops you from resetting the passcode on your own.": "ସ୍କ୍ରିନ୍ ଟାଇମ୍ ପାସ୍‌କୋଡ୍ ରିକଭରି ମାଗିଲେ ଆପଣଙ୍କ ବନ୍ଧୁ ନିଜ Apple ID ରେ ସାଇନ୍ ଇନ୍ କରନ୍ତି — ଆପଣଙ୍କର ନୁହେଁ। ଏହା ହିଁ ଆପଣଙ୍କୁ ନିଜେ ପାସ୍‌କୋଡ୍ ରିସେଟ୍ କରିବାରୁ ରୋକେ।",
    "You can always find this later under Help — but there it's behind a delay.": "ଏହା ପରେ ଆପଣ ସବୁବେଳେ ସାହାଯ୍ୟ ରେ ପାଇପାରିବେ — କିନ୍ତୁ ସେଠାରେ ଏହା ଅପେକ୍ଷା ପଛରେ।",
    "You can change these any time under General blocking. Each change then goes through your delays.": "ଏଗୁଡ଼ିକ ଆପଣ ଯେକୌଣସି ସମୟରେ ସାଧାରଣ ବ୍ଲକ୍ ରେ ବଦଳାଇପାରିବେ। ପ୍ରତ୍ୟେକ ବଦଳ ତା’ପରେ ଆପଣଙ୍କ ଅପେକ୍ଷା ଦେଇ ଯାଏ।",
    "Your one-time access is ready.": "ଆପଣଙ୍କ ଏକ-ଥରର ଆକ୍ସେସ୍ ପ୍ରସ୍ତୁତ।",
    "your setup stays safe": "ଆପଣଙ୍କ ସେଟଅପ୍ ସୁରକ୍ଷିତ ରହେ",
    "—": "—",
    "A backup, if you want one.": "ଏକ ବ୍ୟାକଅପ୍, ଯଦି ଚାହିଁବେ।",
    "Optional: add a trusted contact, a phrase, or a password. Choose exactly what each can approve or unlock.": "ବୈକଳ୍ପିକ: ଏକ ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି, ବାକ୍ୟ କିମ୍ବା ପାସୱାର୍ଡ ଯୋଡ଼ନ୍ତୁ। ପ୍ରତ୍ୟେକ ଠିକ୍ କ’ଣ ଅନୁମୋଦନ କିମ୍ବା ଅନଲକ୍ କରିପାରିବ ବାଛନ୍ତୁ।",
    "These choices apply when you finish setup. Later additions and permission changes follow your delays.": "ଆପଣ ସେଟଅପ୍ ଶେଷ କଲେ ଏହି ପସନ୍ଦ ଲାଗୁ ହୁଏ। ପରବର୍ତ୍ତୀ ଯୋଗ ଓ ଅନୁମତି ବଦଳ ଆପଣଙ୍କ ଅପେକ୍ଷା ମାନେ।",
    "Background monitoring limit": "ବ୍ୟାକ୍‌ଗ୍ରାଉଣ୍ଡ୍ ମନିଟରିଂ ସୀମା",
    "This change needs %d background monitors, but iOS allows %d. Remove a schedule, split budget or pending change, then try again.": "ଏହି ବଦଳକୁ %d ଟି ବ୍ୟାକ୍‌ଗ୍ରାଉଣ୍ଡ୍ ମନିଟର୍ ଦରକାର, କିନ୍ତୁ iOS %d ଟି ଅନୁମତି ଦିଏ। ଏକ ସମୟସୂଚୀ, ଭାଗ ହୋଇଥିବା ବଜେଟ୍ କିମ୍ବା ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ହଟାଇ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    // Change receipt (Today redesign)
    "Looser change": "ଢିଲା ବଦଳ",
    "Stricter change": "କଡ଼ା ବଦଳ",
    "Takes effect": "ଲାଗୁ ହୁଏ",
    "Right away": "ତୁରନ୍ତ",
    "Until then nothing changes. You can cancel it from Today.": "ସେତେବେଳ ପର୍ଯ୍ୟନ୍ତ କିଛି ବଦଳେ ନାହିଁ। ଆପଣ ଏହାକୁ ‘ଆଜି’ ଟ୍ୟାବ୍‌ରୁ ବାତିଲ୍ କରିପାରିବେ।",
    "Hold to confirm": "ନିଶ୍ଚିତ କରିବାକୁ ଚାପି ଧରନ୍ତୁ",
    "Keep editing": "ସମ୍ପାଦନ ଜାରି ରଖନ୍ତୁ",
    "Confirm looser change?": "ଢିଲା ବଦଳ ନିଶ୍ଚିତ କରିବେ?",
    // Changes ledger (Today redesign)
    "Stricter": "ଅଧିକ କଡ଼ା",
    "Looser": "ଢିଲା",
    "Waiting for %@": "%@ ପାଇଁ ଅପେକ୍ଷା",
    "Changes": "ବଦଳ",
    "Within the hour": "ଏକ ଘଣ୍ଟା ଭିତରେ",
    "Later today": "ଆଜି ପରେ",
    "Tomorrow": "କାଲି",
    "Later": "ପରେ",
    "No changes waiting": "କୌଣସି ବଦଳ ଅପେକ୍ଷାରେ ନାହିଁ",
    "Changes you make wait here until they apply.": "ଆପଣ କରିଥିବା ବଦଳ ଲାଗୁ ହେବା ପର୍ଯ୍ୟନ୍ତ ଏଠାରେ ଅପେକ୍ଷା କରେ।",
    "Cancel these changes?": "ଏହି ବଦଳ ବାତିଲ୍ କରିବେ?",
    // Bulk apply notice (was untranslated)
    "Those changes are still counting down. Wait them out or use an available override.": "ସେହି ବଦଳ ଏବେ ବି କାଉଣ୍ଟଡାଉନ୍‌ରେ ଅଛି। ଅପେକ୍ଷା କରନ୍ତୁ କିମ୍ବା ଉପଲବ୍ଧ ଏକ ଓଭରରାଇଡ୍ ବ୍ୟବହାର କରନ୍ତୁ।",
    // Today (Today redesign)
    "Nothing is blocked right now.": "ଏବେ କିଛି ବ୍ଲକ୍ ନାହିଁ।",
    "Next: %@ at %@": "ପରେ: %@, %@ ରେ",
    "%@ is on until %@.": "%@ %@ ପର୍ଯ୍ୟନ୍ତ ଚାଲୁ ଅଛି।",
    "%d blocks are on. The first ends at %@.": "%d ଟି ବ୍ଲକ୍ ଚାଲୁ ଅଛି। ପ୍ରଥମଟି %@ ରେ ଶେଷ ହୁଏ।",
    "%@ is used up for today.": "%@ ଆଜି ପାଇଁ ଶେଷ ହୋଇଗଲା।",
    "%d limits are used up for today.": "%d ଟି ସୀମା ଆଜି ପାଇଁ ଶେଷ ହୋଇଗଲା।",
    "Resets at midnight": "ମଧ୍ୟରାତ୍ରିରେ ରିସେଟ୍ ହୁଏ",
    "You're in a free period until %@.": "ଆପଣ %@ ପର୍ଯ୍ୟନ୍ତ ମୁକ୍ତ ସମୟରେ ଅଛନ୍ତି।",
    "Good morning. Your apps wait until you wake up.": "ଶୁଭ ସକାଳ। ଆପଣ ଉଠିବା ପର୍ଯ୍ୟନ୍ତ ଆପଣଙ୍କ ଆପ୍ ଅପେକ୍ଷା କରେ।",
    "Your apps open at %@.": "ଆପଣଙ୍କ ଆପ୍ %@ ରେ ଖୋଲେ।",
    "Get extra time (%d left)": "ଅତିରିକ୍ତ ସମୟ ପାଆନ୍ତୁ (%d ବାକି)",
    "Extra time in": "ଅତିରିକ୍ତ ସମୟ ଆସିବ",
    "Extra time running": "ଅତିରିକ୍ତ ସମୟ ଚାଲୁଛି",
    "Changing soon": "ଶୀଘ୍ର ବଦଳିବ",
    "All %d": "ସମସ୍ତ %d",
