    "What it can skip": "ଏହା ଯାହା ଏଡ଼ାଇପାରେ",
    // You build: Guide, help and pointers to You (docs/you-redesign.md §8, Y10)
    "Demora protects deliberate decisions with time. In Rules → Your waits, choose separate waits for stricter and less-strict changes, one shared wait, or immediate tightening with a wait only for loosening. Lowering a budget tightens it; raising or removing it loosens it. Changing the policy follows your current policy, not the new one.": "Demora ସମୟ ଦ୍ୱାରା ଭାବିଚିନ୍ତି ନେଇଥିବା ନିଷ୍ପତ୍ତି ସୁରକ୍ଷିତ ରଖେ। ନିୟମ → ଆପଣଙ୍କ ଅପେକ୍ଷା ରେ କଡ଼ା ଓ ଢିଲା ବଦଳ ପାଇଁ ଅଲଗା ଅପେକ୍ଷା, ଗୋଟିଏ ଅପେକ୍ଷା, କିମ୍ବା ତୁରନ୍ତ କଡ଼ା କରିବା ଓ କେବଳ ଢିଲା କଲାବେଳେ ଅପେକ୍ଷା ବାଛନ୍ତୁ। ବଜେଟ୍ କମାଇଲେ ତାହା କଡ଼ା ହୁଏ; ବଢ଼ାଇଲେ କିମ୍ବା ହଟାଇଲେ ଢିଲା। ନୀତି ବଦଳାଇବା ଆପଣଙ୍କ ବର୍ତ୍ତମାନର ନୀତି ମାନେ, ନୂଆଟି ନୁହେଁ।",
    "Changes on Today shows queued changes and their countdowns. Cancel one there before it applies, or skip its wait with an eligible way to skip a wait. Current rules stay active until the change applies. Existing countdowns keep their deadlines when you edit delay settings or reopen Demora. Background application depends on iOS callbacks; open Demora if a due change has not appeared.": "ଆଜି ର ବଦଳ ଧାଡ଼ିରେ ଥିବା ବଦଳ ଓ ସେମାନଙ୍କ କାଉଣ୍ଟଡାଉନ୍ ଦେଖାଏ। ଲାଗୁ ହେବା ପୂର୍ବରୁ ସେଠାରେ ବାତିଲ୍ କରନ୍ତୁ, କିମ୍ବା ଯୋଗ୍ୟ ଅପେକ୍ଷା ଏଡ଼ାଇବା ଉପାୟରେ ଅପେକ୍ଷା ଏଡ଼ାନ୍ତୁ। ବଦଳ ଲାଗୁ ନହେବା ପର୍ଯ୍ୟନ୍ତ ବର୍ତ୍ତମାନର ନିୟମ ଚାଲୁ ରହେ। ଅପେକ୍ଷା ସେଟିଂସ୍ ବଦଳାଇଲେ କିମ୍ବା Demora ପୁଣି ଖୋଲିଲେ ଚାଲୁଥିବା କାଉଣ୍ଟଡାଉନ୍ ସେମାନଙ୍କ ଶେଷ ତାରିଖ ରଖେ। ବ୍ୟାକ୍‌ଗ୍ରାଉଣ୍ଡ୍‌ରେ ଲାଗୁ ହେବା iOS କଲ୍‌ବ୍ୟାକ୍ ଉପରେ ନିର୍ଭର କରେ; ଏକ ଦେୟ ବଦଳ ଦେଖାଯାଇ ନଥିଲେ Demora ଖୋଲନ୍ତୁ।",
    "In Rules, tap New rule → Daily limit, name a limit, choose apps, categories or websites, and set usage minutes. A group shares one allowance across its selection. Zero minutes blocks it all day. Open an existing limit to edit it. Different limits by weekday replaces the default budget on each chosen day. Daily allowances reset at midnight; on iOS 17.4 or later, earlier usage that day also counts.": "ନିୟମ ରେ ନୂଆ ନିୟମ → ଦୈନିକ ସୀମା ଟ୍ୟାପ୍ କରନ୍ତୁ, ସୀମାକୁ ନାମ ଦିଅନ୍ତୁ, ଆପ୍, ଶ୍ରେଣୀ କିମ୍ବା ୱେବସାଇଟ୍ ବାଛନ୍ତୁ ଓ ବ୍ୟବହାର ମିନିଟ୍ ଠିକ୍ କରନ୍ତୁ। ଗୋଟିଏ ଗ୍ରୁପ୍ ତାହାର ବାଛିବା ଉପରେ ଗୋଟିଏ ବରାଦ ବାଣ୍ଟେ। ଶୂନ୍ୟ ମିନିଟ୍ ଦିନସାରା ସବୁ ବ୍ଲକ୍ କରେ। ସମ୍ପାଦନ ପାଇଁ ବିଦ୍ୟମାନ ସୀମା ଖୋଲନ୍ତୁ। ସପ୍ତାହର ଦିନ ଅନୁସାରେ ଅଲଗା ସୀମା ପ୍ରତ୍ୟେକ ବଛା ଦିନରେ ଡିଫଲ୍ଟ ବଜେଟ୍‌ର ସ୍ଥାନ ନିଏ। ଦୈନିକ ବରାଦ ମଧ୍ୟରାତ୍ରିରେ ରିସେଟ୍ ହୁଏ; iOS 17.4 କିମ୍ବା ପରବର୍ତ୍ତୀରେ ସେହି ଦିନର ଆଗରୁ ବ୍ୟବହାର ମଧ୍ୟ ଗଣାଯାଏ।",
    "In a limit's editor, Manual extra time sets up to five ordered uses, each with its own usage minutes and a wait, named password, phrase or contact approval. Request a use on Today only after the full daily budget is spent. These are app-usage minutes, not a timed unblock session. Requests survive reopening Demora and reset at midnight. Extra time does not skip an early split portion, wake wait or unrelated block.": "ସୀମାର ସମ୍ପାଦକରେ ହାତରେ ଅତିରିକ୍ତ ସମୟ କ୍ରମରେ ପାଞ୍ଚ ପର୍ଯ୍ୟନ୍ତ ବ୍ୟବହାର ଠିକ୍ କରେ, ପ୍ରତ୍ୟେକର ନିଜସ୍ୱ ବ୍ୟବହାର ମିନିଟ୍ ଓ ଏକ ଅପେକ୍ଷା, ନାମିତ ପାସୱାର୍ଡ, ବାକ୍ୟ କିମ୍ବା ଯୋଗାଯୋଗ ଅନୁମୋଦନ ସହ। ଆଜି ରେ ବ୍ୟବହାର ମାଗନ୍ତୁ କେବଳ ସମ୍ପୂର୍ଣ୍ଣ ଦୈନିକ ବଜେଟ୍ ଶେଷ ହେଲା ପରେ। ଏଗୁଡ଼ିକ ଆପ୍-ବ୍ୟବହାର ମିନିଟ୍, ସମୟ-ବଦ୍ଧ ଅନବ୍ଲକ୍ ସେସନ୍ ନୁହେଁ। ଅନୁରୋଧ Demora ପୁଣି ଖୋଲିଲେ ମଧ୍ୟ ରହେ ଓ ମଧ୍ୟରାତ୍ରିରେ ରିସେଟ୍ ହୁଏ। ଅତିରିକ୍ତ ସମୟ ଏକ ପ୍ରାରମ୍ଭିକ ଭାଗ, ଉଠିବା ଅପେକ୍ଷା କିମ୍ବା ଅସମ୍ବନ୍ଧିତ ବ୍ଲକ୍ ଏଡ଼ାଏ ନାହିଁ।",
    "In Rules, tap New rule → Day & night to create up to five named groups. Check existing limits and choose extra apps, then set wake-up and sleep times and weekdays. One optional all-other-apps group automatically excludes explicitly timed groups; whole-category exceptions are not supported. Existing general wake/sleep settings and Group wake-up gates still apply alongside these groups.": "ନିୟମ ରେ ନୂଆ ନିୟମ → ଦିନ ଓ ରାତି ଟ୍ୟାପ୍ କରି ପାଞ୍ଚ ପର୍ଯ୍ୟନ୍ତ ନାମିତ ଗ୍ରୁପ୍ ବନାନ୍ତୁ। ବିଦ୍ୟମାନ ସୀମା ଦେଖନ୍ତୁ ଓ ଅତିରିକ୍ତ ଆପ୍ ବାଛନ୍ତୁ, ତା’ପରେ ଉଠିବା ଓ ନିଦ୍ରା ସମୟ ଓ ସପ୍ତାହର ଦିନ ଠିକ୍ କରନ୍ତୁ। ଗୋଟିଏ ବୈକଳ୍ପିକ ଅନ୍ୟ-ସମସ୍ତ-ଆପ୍ ଗ୍ରୁପ୍ ସ୍ପଷ୍ଟ ସମୟର ଗ୍ରୁପ୍ ନିଜେ ନିଜେ ବାଦ୍ ଦିଏ; ସମ୍ପୂର୍ଣ୍ଣ ଶ୍ରେଣୀ ବ୍ୟତିକ୍ରମ ସମର୍ଥିତ ନୁହେଁ। ବିଦ୍ୟମାନ ସାଧାରଣ ଉଠିବା/ନିଦ୍ରା ସେଟିଂସ୍ ଓ ଗ୍ରୁପ୍ ଉଠିବା ଗେଟ୍ ଏହି ଗ୍ରୁପ୍ ପାଖରେ ଏବେ ବି ଲାଗୁ।",
    "Set a wake-up start and wait, with optional per-weekday start and wait overrides. Tap Wake up on Today to start every eligible group's wait together; tapping again does not restart it. An optional latest wake-up time, also configurable by weekday, ends only that wake gate even without a tap or during a wait. It does not end sleep blocking or restore a spent daily budget.": "ଏକ ଉଠିବା ଆରମ୍ଭ ଓ ଅପେକ୍ଷା ଠିକ୍ କରନ୍ତୁ, ସପ୍ତାହର ଦିନ ଅନୁସାରେ ବୈକଳ୍ପିକ ଆରମ୍ଭ ଓ ଅପେକ୍ଷା ସହ। ଆଜି ରେ ଉଠନ୍ତୁ ଟ୍ୟାପ୍ କଲେ ସମସ୍ତ ଯୋଗ୍ୟ ଗ୍ରୁପ୍‌ର ଅପେକ୍ଷା ଏକାଠି ଆରମ୍ଭ ହୁଏ; ପୁଣି ଟ୍ୟାପ୍ କଲେ ତାହା ପୁଣି ଆରମ୍ଭ ହୁଏ ନାହିଁ। ଏକ ବୈକଳ୍ପିକ ଉଠିବାର ଶେଷ ସମୟ, ସପ୍ତାହର ଦିନ ଅନୁସାରେ ମଧ୍ୟ ଠିକ୍ କରାଯାଇପାରେ, କେବଳ ସେହି ଉଠିବା ଗେଟ୍ ଶେଷ କରେ, ଟ୍ୟାପ୍ ବିନା କିମ୍ବା ଅପେକ୍ଷା ସମୟରେ ମଧ୍ୟ। ଏହା ନିଦ୍ରା ବ୍ଲକ୍ ଶେଷ କରେ ନାହିଁ କି ଖର୍ଚ୍ଚ ହୋଇଥିବା ଦୈନିକ ବଜେଟ୍ ଫେରାଏ ନାହିଁ।",
    "In Rules, tap New rule and choose New session, Plan a block or Repeating block; New session also sits at the bottom of Today. Create a block, unblock or free period. New session starts after any required delay; its duration starts when it takes effect. Planned uses a specific date. Repeating runs daily, on weekdays or on a monthly pattern, and can cross midnight. Blocking rules can target selected apps or everything except a selection. Rules → Calendar shows occurrences.": "ନିୟମ ରେ ନୂଆ ନିୟମ ଟ୍ୟାପ୍ କରି ନୂଆ ସେସନ୍, ବ୍ଲକ୍ ଯୋଜନା କିମ୍ବା ପୁନରାବୃତ୍ତ ବ୍ଲକ୍ ବାଛନ୍ତୁ; ନୂଆ ସେସନ୍ ଆଜି ର ତଳେ ମଧ୍ୟ ଅଛି। ବ୍ଲକ୍, ଅନବ୍ଲକ୍ କିମ୍ବା ମୁକ୍ତ ସମୟ ବନାନ୍ତୁ। ନୂଆ ସେସନ୍ ଆବଶ୍ୟକ ଅପେକ୍ଷା ପରେ ଆରମ୍ଭ ହୁଏ; ତାହାର ଅବଧି ଲାଗୁ ହେଲେ ଆରମ୍ଭ ହୁଏ। ଯୋଜିତ ଏକ ନିର୍ଦ୍ଦିଷ୍ଟ ତାରିଖ ବ୍ୟବହାର କରେ। ପୁନରାବୃତ୍ତ ପ୍ରତିଦିନ, ସପ୍ତାହ ଦିନରେ କିମ୍ବା ମାସିକ ଢାଞ୍ଚାରେ ଚାଲେ ଓ ମଧ୍ୟରାତ୍ରି ଅତିକ୍ରମ କରିପାରେ। ବ୍ଲକ୍ ନିୟମ ବଛା ଆପ୍ କିମ୍ବା ବାଛିବା ବ୍ୟତୀତ ସବୁକୁ ଲକ୍ଷ୍ୟ କରିପାରେ। ନିୟମ → କ୍ୟାଲେଣ୍ଡର ଘଟଣା ଦେଖାଏ।",
    "In Rules, tap Conflicts to review the next week's potential overlaps. Default application order is wake/sleep → recurring → planned → sessions. Later effects apply only within their scope: an allowlist is not a global unblock, does not reset daily usage, and does not clear unrelated specific blocks. Category membership is hidden by Apple, and untapped wake windows are estimates, so some overlaps are uncertain.": "ନିୟମ ରେ ସଂଘର୍ଷ ଟ୍ୟାପ୍ କରି ଆସନ୍ତା ସପ୍ତାହର ସମ୍ଭାବ୍ୟ ଓଭରଲାପ୍ ଦେଖନ୍ତୁ। ଡିଫଲ୍ଟ ପ୍ରୟୋଗ କ୍ରମ ଉଠିବା/ନିଦ୍ରା → ପୁନରାବୃତ୍ତ → ଯୋଜିତ → ସେସନ୍। ପରବର୍ତ୍ତୀ ପ୍ରଭାବ କେବଳ ନିଜ ପରିସର ଭିତରେ ଲାଗୁ ହୁଏ: ଏକ ଅନୁମୋଦିତ ତାଲିକା ବିଶ୍ୱବ୍ୟାପୀ ଅନବ୍ଲକ୍ ନୁହେଁ, ଦୈନିକ ବ୍ୟବହାର ରିସେଟ୍ କରେ ନାହିଁ, ଓ ଅସମ୍ବନ୍ଧିତ ନିର୍ଦ୍ଦିଷ୍ଟ ବ୍ଲକ୍ ସଫା କରେ ନାହିଁ। Apple ଶ୍ରେଣୀ ସଦସ୍ୟତା ଲୁଚାଏ, ଓ ଟ୍ୟାପ୍ ହୋଇନଥିବା ଉଠିବା ଝରକା ଅନୁମାନ, ତେଣୁ କେତେକ ଓଭରଲାପ୍ ଅନିଶ୍ଚିତ।",
    "Open You → Ways to skip a wait to add, change or remove named passwords and phrases. Each has its own allowed uses; it cannot approve an unrelated change. Phrases can be custom or random on-device words, typed word by word with your chosen mistake allowance. Adding one or expanding what it may skip waits through the less-strict delay. Knowing the current password permits an immediate secret-only change, not an immediate permissions change.": "ନାମିତ ପାସୱାର୍ଡ ଓ ବାକ୍ୟ ଯୋଡ଼ିବା, ବଦଳାଇବା କିମ୍ବା ହଟାଇବା ପାଇଁ ଆପଣ → ଅପେକ୍ଷା ଏଡ଼ାଇବାର ଉପାୟ ଖୋଲନ୍ତୁ। ପ୍ରତ୍ୟେକର ନିଜସ୍ୱ ଅନୁମତି ପ୍ରାପ୍ତ ବ୍ୟବହାର ଅଛି; ଏହା ଅସମ୍ବନ୍ଧିତ ବଦଳ ଅନୁମୋଦନ କରିପାରେ ନାହିଁ। ବାକ୍ୟ କଷ୍ଟମ୍ କିମ୍ବା ଡିଭାଇସ୍‌ରେ ତିଆରି ଅନିୟମିତ ଶବ୍ଦ ହୋଇପାରେ, ଆପଣ ବାଛିଥିବା ଭୁଲ ଛାଡ଼ ସହ ଶବ୍ଦ ଶବ୍ଦ କରି ଟାଇପ୍ କରାଯାଏ। ଗୋଟିଏ ଯୋଡ଼ିବା କିମ୍ବା ତାହା ଯାହା ଏଡ଼ାଇପାରେ ତାହା ବିସ୍ତାର କରିବା କମ୍ କଡ଼ା ଅପେକ୍ଷା ଦେଇ ଯାଏ। ବର୍ତ୍ତମାନର ପାସୱାର୍ଡ ଜାଣିବା ଗୁପ୍ତ ବସ୍ତୁର ତୁରନ୍ତ ବଦଳ ଦିଏ, ଅନୁମତିର ତୁରନ୍ତ ବଦଳ ନୁହେଁ।",
    "In Rules, Recheck blocked limits takes around 30 seconds and keeps current blocks in place while iOS verifies usage. Confirmed spent limits stay blocked; a failed or interrupted check changes nothing. This is not a bypass for a real spent budget, split boundary, wake wait or schedule. Safe rechecking needs iOS 17.4 or later; wait until an active free period ends before trying.": "ନିୟମ ରେ ବ୍ଲକ୍ ହୋଇଥିବା ସୀମା ପୁଣି ଯାଞ୍ଚ କରନ୍ତୁ ପ୍ରାୟ ୩୦ ସେକେଣ୍ଡ ନିଏ ଓ iOS ବ୍ୟବହାର ଯାଞ୍ଚ କରୁଥିବା ବେଳେ ବର୍ତ୍ତମାନର ବ୍ଲକ୍ ରଖେ। ନିଶ୍ଚିତ ଶେଷ ହୋଇଥିବା ସୀମା ବ୍ଲକ୍ ରହେ; ବିଫଳ କିମ୍ବା ବାଧାପ୍ରାପ୍ତ ଯାଞ୍ଚ କିଛି ବଦଳାଏ ନାହିଁ। ଏହା ପ୍ରକୃତ ଶେଷ ହୋଇଥିବା ବଜେଟ୍, ଭାଗ ସୀମା, ଉଠିବା ଅପେକ୍ଷା କିମ୍ବା ସମୟସୂଚୀକୁ ଏଡ଼ାଇବାର ବାଟ ନୁହେଁ। ସୁରକ୍ଷିତ ପୁଣି-ଯାଞ୍ଚ ପାଇଁ iOS 17.4 କିମ୍ବା ପରବର୍ତ୍ତୀ ଦରକାର; ଚେଷ୍ଟା ପୂର୍ବରୁ ସକ୍ରିୟ ମୁକ୍ତ ସମୟ ଶେଷ ହେବା ପର୍ଯ୍ୟନ୍ତ ଅପେକ୍ଷା କରନ୍ତୁ।",
    "In You → Notifications, choose five-minute limit warnings and optional free-period boundary reminders. Limit warnings are only for budgets longer than five minutes and are suppressed during free periods. iOS notification permission is separate from Screen Time access, and alerts can arrive late or not at all. Now & Next and Pending Change widgets are read-only summaries; they do not apply overrides or show raw usage.": "ଆପଣ → ବିଜ୍ଞପ୍ତି ରେ ସୀମାର ପାଞ୍ଚ-ମିନିଟ୍ ଚେତାବନୀ ଓ ବୈକଳ୍ପିକ ମୁକ୍ତ-ସମୟ ସୀମା ସ୍ମାରକ ବାଛନ୍ତୁ। ସୀମା ଚେତାବନୀ କେବଳ ପାଞ୍ଚ ମିନିଟ୍‌ରୁ ଲମ୍ବା ବଜେଟ୍ ପାଇଁ ଓ ମୁକ୍ତ ସମୟରେ ଦମିତ ହୁଏ। iOS ବିଜ୍ଞପ୍ତି ଅନୁମତି ସ୍କ୍ରିନ୍ ଟାଇମ୍ ଆକ୍ସେସ୍‌ଠାରୁ ଅଲଗା, ଓ ସତର୍କ ବିଳମ୍ବରେ ଆସିପାରେ କିମ୍ବା ଆଦୌ ଆସିନପାରେ। ଏବେ ଓ ପରେ ଏବଂ ଅପେକ୍ଷାରେ ଥିବା ବଦଳ ୱିଜେଟ୍ କେବଳ ପଢ଼ିବା ସାରାଂଶ; ସେଗୁଡ଼ିକ ଓଭରରାଇଡ୍ ଲାଗୁ କରେ ନାହିଁ କି କଞ୍ଚା ବ୍ୟବହାର ଦେଖାଏ ନାହିଁ।",
    "contacts, passwords and phrases": "ଯୋଗାଯୋଗ, ପାସୱାର୍ଡ ଓ ବାକ୍ୟ",
    "How Demora works": "Demora କିପରି କାମ କରେ",
    "four short pages": "ଚାରିଟି ଛୋଟ ପୃଷ୍ଠା",
    "Your past decision wins": "ଆପଣଙ୍କ ପୂର୍ବ ନିଷ୍ପତ୍ତି ଜିତେ",
    "You set your rules when you're calm. Later, when an impulse says \"just this once\", the rule you chose still holds.": "ଆପଣ ଶାନ୍ତ ଥିବା ବେଳେ ନିୟମ ଠିକ୍ କରନ୍ତି। ପରେ, ଯେତେବେଳେ ଆବେଗ କହେ “କେବଳ ଏହି ଥର”, ଆପଣ ବାଛିଥିବା ନିୟମ ଏବେ ବି ଟିକେ।",
    "Stricter is quick, looser waits": "କଡ଼ା ଶୀଘ୍ର, ଢିଲା ଅପେକ୍ଷା କରେ",
    "Making a rule stricter can apply right away. Making it looser waits through the wait you chose in Rules → Your waits.": "ନିୟମ କଡ଼ା କରିବା ତୁରନ୍ତ ଲାଗୁ ହୋଇପାରେ। ତାହାକୁ ଢିଲା କରିବା ନିୟମ → ଆପଣଙ୍କ ଅପେକ୍ଷା ରେ ବାଛିଥିବା ଅପେକ୍ଷା ପୂରଣ କରେ।",
    "Changes wait in Changes": "ବଦଳ, ବଦଳ ରେ ଅପେକ୍ଷା କରେ",
    "A looser change waits in Changes on Today with its countdown. Until it lands nothing changes, and you can cancel it any time.": "ଏକ ଢିଲା ବଦଳ ଆଜି ର ବଦଳ ରେ କାଉଣ୍ଟଡାଉନ୍ ସହ ଅପେକ୍ଷା କରେ। ଲାଗୁ ନହେବା ପର୍ଯ୍ୟନ୍ତ କିଛି ବଦଳେ ନାହିଁ, ଓ ଆପଣ ଯେକୌଣସି ସମୟରେ ବାତିଲ୍ କରିପାରିବେ।",
    "A trusted contact, a password or a phrase can let a change apply early, but only for the kinds of change you allowed. Changes to them wait too. Set them up in You → Ways to skip a wait.": "ଭରସାଯୋଗ୍ୟ ବ୍ୟକ୍ତି, ପାସୱାର୍ଡ କିମ୍ବା ବାକ୍ୟ ବଦଳକୁ ଆଗରୁ ଲାଗୁ ହେବାକୁ ଦେଇପାରେ, କିନ୍ତୁ କେବଳ ଆପଣ ଅନୁମତି ଦେଇଥିବା ପ୍ରକାରର ବଦଳ ପାଇଁ। ସେଗୁଡ଼ିକର ବଦଳ ମଧ୍ୟ ଅପେକ୍ଷା କରେ। ଆପଣ → ଅପେକ୍ଷା ଏଡ଼ାଇବାର ଉପାୟ ରେ ସେଗୁଡ଼ିକ ଠିକ୍ କରନ୍ତୁ।",
    "How Demora works is always in You → Help & guide.": "Demora କିପରି କାମ କରେ ତାହା ସବୁବେଳେ ଆପଣ → ସାହାଯ୍ୟ ଓ ଗାଇଡ୍ ରେ ଅଛି।",
    "Find practical instructions and troubleshooting in You → Help & guide → Guide.": "ବ୍ୟବହାରିକ ନିର୍ଦ୍ଦେଶ ଓ ସମସ୍ୟା ସମାଧାନ ଆପଣ → ସାହାଯ୍ୟ ଓ ଗାଇଡ୍ → ଗାଇଡ୍ ରେ ମିଳିବ।",
    "Contact invitations are sent after setup. Contacts must confirm before they can approve; manage them in You → Ways to skip a wait.": "ସେଟଅପ୍ ପରେ ଯୋଗାଯୋଗ ନିମନ୍ତ୍ରଣ ପଠାଯାଏ। ଅନୁମୋଦନ ପୂର୍ବରୁ ଯୋଗାଯୋଗକୁ ନିଶ୍ଚିତ କରିବାକୁ ହୁଏ; ସେମାନଙ୍କୁ ଆପଣ → ଅପେକ୍ଷା ଏଡ଼ାଇବାର ଉପାୟ ରେ ସମ୍ଭାଳନ୍ତୁ।",
    "A person you choose approves skipping a countdown — by email code or from their own Demora app. You can also add more later in You → Ways to skip a wait.": "ଆପଣ ବାଛିଥିବା ଜଣେ ବ୍ୟକ୍ତି କାଉଣ୍ଟଡାଉନ୍ ଏଡ଼ାଇବା ଅନୁମୋଦନ କରନ୍ତି — ଇମେଲ୍ କୋଡ୍ ଦ୍ୱାରା କିମ୍ବା ନିଜ Demora ଆପ୍‌ରୁ। ଆପଣ ପରେ ଆପଣ → ଅପେକ୍ଷା ଏଡ଼ାଇବାର ଉପାୟ ରେ ଅଧିକ ଯୋଡ଼ିପାରିବେ।",
    "Choose your language here. You can change it anytime under You → Appearance → Language.": "ଏଠାରେ ଆପଣଙ୍କ ଭାଷା ବାଛନ୍ତୁ। ଆପଣ ଏହାକୁ ଯେକୌଣସି ସମୟରେ ଆପଣ → ଦୃଶ୍ୟ → ଭାଷା ରେ ବଦଳାଇପାରିବେ।",
    "Ask them for the code under You → Your code in their Demora. They'll get a request to accept before they can approve for you.": "ସେମାନଙ୍କ Demora ର ଆପଣ → ଆପଣଙ୍କ କୋଡ୍ ରେ ଥିବା କୋଡ୍ ସେମାନଙ୍କୁ ମାଗନ୍ତୁ। ଆପଣଙ୍କ ପାଇଁ ଅନୁମୋଦନ କରିବା ପୂର୍ବରୁ ସେମାନେ ଗ୍ରହଣ କରିବାକୁ ଏକ ଅନୁରୋଧ ପାଇବେ।",
    // You review fix: what can never be skipped early
    "Changes to passwords, phrases and what anyone may skip can never be skipped early.": "ପାସୱାର୍ଡ, ବାକ୍ୟ ଓ କିଏ କ’ଣ ଏଡ଼ାଇପାରିବ ସେଥିରେ ବଦଳ କେବେ ଆଗରୁ ଏଡ଼ାଯାଇପାରେ ନାହିଁ।",
    // When & where rules (step 1): change summaries for the receipt and ledger.
    "at %@": "%@ ରେ",
    "in %@": "%@ ପରେ",
    "every day": "ପ୍ରତିଦିନ",
    "on weekdays": "ସପ୍ତାହ ଦିନରେ",
    "on weekends": "ସପ୍ତାହାନ୍ତରେ",
    "on %@": "%@ ରେ",
    "%@ to %@": "%@ ରୁ %@",
    "%@ and %@": "%@ ଓ %@",
    "%@ or %@": "%@ କିମ୍ବା %@",
