    "A block starts when you check in at a place or in a country, and runs until the end you choose. Leaving doesn't end it. It blocks only the apps you choose.": "ଆପଣ କୌଣସି ସ୍ଥାନ କିମ୍ବା ଦେଶରେ ଚେକ୍ ଇନ୍ କଲେ ଏକ ବ୍ଲକ୍ ଆରମ୍ଭ ହୁଏ, ଓ ଆପଣ ବାଛିଥିବା ଶେଷ ପର୍ଯ୍ୟନ୍ତ ଚାଲେ। ସ୍ଥାନ ଛାଡ଼ିଲେ ଏହା ଶେଷ ହୁଏ ନାହିଁ। ଏହା କେବଳ ଆପଣ ବାଛିଥିବା ଆପ୍ ବ୍ଲକ୍ କରେ।",
    "Add at least one condition.": "ଅତି କମରେ ଗୋଟିଏ ସର୍ତ୍ତ ଯୋଡ଼ନ୍ତୁ।",
