    "Use a shorter name.": "ଏକ ଛୋଟ ନାମ ବ୍ୟବହାର କରନ୍ତୁ।",
    "Use at most four conditions.": "ସର୍ବାଧିକ ଚାରିଟି ସର୍ତ୍ତ ବ୍ୟବହାର କରନ୍ତୁ।",
    "With “any of”, a block can use times, places and countries, not days or dates.": "“ଯେକୌଣସି” ସହ ଏକ ବ୍ଲକ୍ ସମୟ, ସ୍ଥାନ ଓ ଦେଶ ବ୍ୟବହାର କରିପାରେ, ଦିନ କିମ୍ବା ତାରିଖ ନୁହେଁ।",
    "With “any of”, a time on its own blocks every day, like a repeating block.": "“ଯେକୌଣସି” ସହ ଏକୁଟିଆ ସମୟ ପ୍ରତିଦିନ ବ୍ଲକ୍ କରେ, ପୁନରାବୃତ୍ତ ବ୍ଲକ୍ ଭଳି।",
    "You can add up to four conditions.": "ଆପଣ ସର୍ବାଧିକ ଚାରିଟି ସର୍ତ୍ତ ଯୋଡ଼ିପାରିବେ।",
    "You can have up to five When & where rules.": "ଆପଣ ସର୍ବାଧିକ ପାଞ୍ଚଟି କେବେ ଓ କେଉଁଠି ନିୟମ ରଖିପାରିବେ।",
    // When & where step 3: check-in sheet and Today rows.
    "Free time needs all of these.": "ମୁକ୍ତ ସମୟ ପାଇଁ ଏସବୁ ସମସ୍ତ ଦରକାର।",
    "Free time needs any of these.": "ମୁକ୍ତ ସମୟ ପାଇଁ ଏଗୁଡ଼ିକ ମଧ୍ୟରୁ ଯେକୌଣସି ଦରକାର।",
    "The block needs all of these.": "ବ୍ଲକ୍ ପାଇଁ ଏସବୁ ସମସ୍ତ ଦରକାର।",
    "The block needs any of these.": "ବ୍ଲକ୍ ପାଇଁ ଏଗୁଡ଼ିକ ମଧ୍ୟରୁ ଯେକୌଣସି ଦରକାର।",
    "This rule changed. Check in again.": "ଏହି ନିୟମ ବଦଳିଛି। ପୁଣି ଚେକ୍ ଇନ୍ କରନ୍ତୁ।",
    "Free time is on until %@.": "ମୁକ୍ତ ସମୟ %@ ପର୍ଯ୍ୟନ୍ତ ଚାଲୁ ଅଛି।",
    "This rule needs your location.": "ଏହି ନିୟମକୁ ଆପଣଙ୍କ ଲୋକେସନ୍ ଦରକାର।",
    "You can have free time now.": "ଆପଣ ଏବେ ମୁକ୍ତ ସମୟ ପାଇପାରିବେ।",
    "You've used today's free time.": "ଆପଣ ଆଜିର ମୁକ୍ତ ସମୟ ବ୍ୟବହାର କରିସାରିଛନ୍ତି।",
    "Free time didn't start.": "ମୁକ୍ତ ସମୟ ଆରମ୍ଭ ହେଲା ନାହିଁ।",
    "Not right now.": "ଏବେ ନୁହେଁ।",
    "Your clock was changed recently. Free time can start once it's set right again.": "ଆପଣଙ୍କ ଘଣ୍ଟା ସମ୍ପ୍ରତି ବଦଳାଯାଇଥିଲା। ପୁଣି ଠିକ୍ ହେଲେ ମୁକ୍ତ ସମୟ ଆରମ୍ଭ ହୋଇପାରିବ।",
    "Couldn't count today's uses. Try again.": "ଆଜିର ବ୍ୟବହାର ଗଣାଯାଇପାରିଲା ନାହିଁ। ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Less than a minute is left in this window.": "ଏହି ଝରକାରେ ଏକ ମିନିଟ୍‌ରୁ କମ୍ ବାକି ଅଛି।",
    "It's waiting in Changes instead.": "ଏହା ବଦଳରେ ବଦଳ ରେ ଅପେକ୍ଷାରେ ଅଛି।",
    "This check is more than two minutes old. Check in again.": "ଏହି ଯାଞ୍ଚ ଦୁଇ ମିନିଟ୍‌ରୁ ଅଧିକ ପୁରୁଣା। ପୁଣି ଚେକ୍ ଇନ୍ କରନ୍ତୁ।",
    "A new day started. Check in again.": "ଏକ ନୂଆ ଦିନ ଆରମ୍ଭ ହେଲା। ପୁଣି ଚେକ୍ ଇନ୍ କରନ୍ତୁ।",
    "Your time zone changed. Check in again.": "ଆପଣଙ୍କ ଟାଇମ୍ ଜୋନ୍ ବଦଳିଛି। ପୁଣି ଚେକ୍ ଇନ୍ କରନ୍ତୁ।",
    "The conditions aren't met any more.": "ସର୍ତ୍ତ ଆଉ ପୂରଣ ହେଉନାହିଁ।",
    "Choose a length this rule allows.": "ଏହି ନିୟମ ଅନୁମତି ଦେଉଥିବା ଏକ ଲମ୍ବ ବାଛନ୍ତୁ।",
    "Free time from this rule is already on.": "ଏହି ନିୟମର ମୁକ୍ତ ସମୟ ଆଗରୁ ଚାଲୁ ଅଛି।",
    "This check-in was already used. Check in again.": "ଏହି ଚେକ୍-ଇନ୍ ଆଗରୁ ବ୍ୟବହୃତ ହୋଇସାରିଛି। ପୁଣି ଚେକ୍ ଇନ୍ କରନ୍ତୁ।",
    "A change is still being applied. Try again in a moment.": "ଏକ ବଦଳ ଏବେ ବି ଲାଗୁ ହେଉଛି। କିଛି ସମୟ ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Free time couldn't start safely. iOS may not be able to track another session right now. Nothing changed.": "ମୁକ୍ତ ସମୟ ସୁରକ୍ଷିତ ଭାବେ ଆରମ୍ଭ ହୋଇପାରିଲା ନାହିଁ। iOS ଏବେ ଆଉ ଏକ ସେସନ୍ ଟ୍ରାକ୍ କରିପାରୁନଥାଇପାରେ। କିଛି ବଦଳି ନାହିଁ।",
    "You're at %@": "ଆପଣ %@ ରେ ଅଛନ୍ତି",
    "You're not at %@": "ଆପଣ %@ ରେ ନାହାଁନ୍ତି",
    "You're in %@": "ଆପଣ %@ ରେ ଅଛନ୍ତି",
    "You're not in %@": "ଆପଣ %@ ରେ ନାହାଁନ୍ତି",
