    "Today is one of these dates": "ଆଜି ଏହି ତାରିଖ ମଧ୍ୟରୁ ଗୋଟିଏ",
    "Today isn't one of these dates": "ଆଜି ଏହି ତାରିଖ ମଧ୍ୟରୁ ଗୋଟିଏ ନୁହେଁ",
    "Not needed": "ଦରକାର ନାହିଁ",
    "Your clock was changed recently": "ଆପଣଙ୍କ ଘଣ୍ଟା ସମ୍ପ୍ରତି ବଦଳାଯାଇଥିଲା",
    "Your time zone changed recently": "ଆପଣଙ୍କ ଟାଇମ୍ ଜୋନ୍ ସମ୍ପ୍ରତି ବଦଳିଛି",
    "Couldn't read your time zone": "ଆପଣଙ୍କ ଟାଇମ୍ ଜୋନ୍ ପଢ଼ାଯାଇପାରିଲା ନାହିଁ",
    "Location is off for Demora. You can turn it on in Settings.": "Demora ପାଇଁ ଲୋକେସନ୍ ବନ୍ଦ ଅଛି। ଆପଣ ଏହାକୁ ସେଟିଂସ୍‌ରେ ଚାଲୁ କରିପାରିବେ।",
    "Couldn't get your location. Try again outside or near a window.": "ଆପଣଙ୍କ ଲୋକେସନ୍ ମିଳିଲା ନାହିଁ। ବାହାରେ କିମ୍ବା ଝରକା ପାଖରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
    "Location isn't precise enough here": "ଏଠାରେ ଲୋକେସନ୍ ଯଥେଷ୍ଟ ସଠିକ୍ ନୁହେଁ",
    "Needs precise location": "ସଠିକ୍ ଲୋକେସନ୍ ଦରକାର",
    "This location looks simulated": "ଏହି ଲୋକେସନ୍ ନକଲି ଲାଗୁଛି",
    "Location from an accessory can't start free time": "ଆକ୍ସେସରିର ଲୋକେସନ୍ ମୁକ୍ତ ସମୟ ଆରମ୍ଭ କରିପାରେ ନାହିଁ",
    "Too close to a border to tell": "ନିର୍ଣ୍ଣୟ କରିବାକୁ ସୀମାନ୍ତର ବହୁତ ପାଖରେ",
    "Couldn't tell which country you're in": "ଆପଣ କେଉଁ ଦେଶରେ ଅଛନ୍ତି ତାହା ନିର୍ଣ୍ଣୟ କରାଯାଇପାରିଲା ନାହିଁ",
    "Use a repeating block for rules without a place.": "ସ୍ଥାନ ବିନା ନିୟମ ପାଇଁ ପୁନରାବୃତ୍ତ ବ୍ଲକ୍ ବ୍ୟବହାର କରନ୍ତୁ।",
    "Check in again to check where you are.": "ଆପଣ କେଉଁଠି ଅଛନ୍ତି ଦେଖିବାକୁ ପୁଣି ଚେକ୍ ଇନ୍ କରନ୍ତୁ।",
    "Demora checks where you are once, when you tap Check in. It doesn't save or send your location.": "ଆପଣ ଚେକ୍ ଇନ୍ ଟ୍ୟାପ୍ କଲେ Demora ଥରେ ଦେଖେ ଆପଣ କେଉଁଠି। ଏହା ଆପଣଙ୍କ ଲୋକେସନ୍ ସେଭ୍ କରେ ନାହିଁ କି ପଠାଏ ନାହିଁ।",
