    "Demora reads where you are once to set this place's centre. It doesn't send your location.": "ଏହି ସ୍ଥାନର କେନ୍ଦ୍ର ଠିକ୍ କରିବାକୁ Demora ଥରେ ଦେଖେ ଆପଣ କେଉଁଠି। ଏହା ଆପଣଙ୍କ ଲୋକେସନ୍ ପଠାଏ ନାହିଁ।",
