    "You start it with Check in on the rule or on Today.": "ଆପଣ ଏହାକୁ ନିୟମରେ କିମ୍ବା ଆଜି ରେ ଚେକ୍ ଇନ୍ ଦ୍ୱାରା ଆରମ୍ଭ କରନ୍ତି।",
