    "or": "କିମ୍ବା",
    "within %@": "%@ ଭିତରେ",
    "This rule changed while you were editing. Close it and open it again.": "ଆପଣ ସମ୍ପାଦନ କରୁଥିବା ବେଳେ ଏହି ନିୟମ ବଦଳିଗଲା। ଏହାକୁ ବନ୍ଦ କରି ପୁଣି ଖୋଲନ୍ତୁ।",
    "Use the country I'm in": "ମୁଁ ଯେଉଁ ଦେଶରେ ଅଛି ତାହା ବ୍ୟବହାର କରନ୍ତୁ",
