    "Search countries": "ଦେଶ ଖୋଜନ୍ତୁ",
    "Choose a country first.": "ପ୍ରଥମେ ଏକ ଦେଶ ବାଛନ୍ତୁ।",
    "Demora reads where you are once to find your country. It doesn't send your location.": "ଆପଣଙ୍କ ଦେଶ ଖୋଜିବାକୁ Demora ଥରେ ଦେଖେ ଆପଣ କେଉଁଠି। ଏହା ଆପଣଙ୍କ ଲୋକେସନ୍ ପଠାଏ ନାହିଁ।",
    "Location from an accessory can't set a country": "ଆକ୍ସେସରିର ଲୋକେସନ୍ ଦେଶ ଠିକ୍ କରିପାରେ ନାହିଁ",
    "Credits": "ଶ୍ରେୟ",
