    "Country borders": "ଦେଶ ସୀମାନ୍ତ",
    "No country matches.": "କୌଣସି ଦେଶ ମେଳ ଖାଉନାହିଁ।",
    "Close enough to %@ to count for a block": "ବ୍ଲକ୍ ପାଇଁ ଗଣାଯିବା ପାଇଁ %@ ର ଯଥେଷ୍ଟ ପାଖରେ",
