    "Block %@ until %@?": "%@ କୁ %@ ପର୍ଯ୍ୟନ୍ତ ବ୍ଲକ୍ କରିବେ?",
    "Block %@ for %@?": "%@ କୁ %@ ପାଇଁ ବ୍ଲକ୍ କରିବେ?",
    "The block is on until %@.": "ବ୍ଲକ୍ %@ ପର୍ଯ୍ୟନ୍ତ ଚାଲୁ ଅଛି।",
    "This block is on until %@.": "ଏହି ବ୍ଲକ୍ %@ ପର୍ଯ୍ୟନ୍ତ ଚାଲୁ ଅଛି।",
    "The block starts at %@.": "ବ୍ଲକ୍ %@ ରେ ଆରମ୍ଭ ହୁଏ।",
    "Checked again. Review it again to start.": "ପୁଣି ଯାଞ୍ଚ ହେଲା। ଆରମ୍ଭ କରିବାକୁ ପୁଣି ଦେଖନ୍ତୁ।",
    "Your clock was changed recently. The block can start once it's set right again.": "ଆପଣଙ୍କ ଘଣ୍ଟା ସମ୍ପ୍ରତି ବଦଳାଯାଇଥିଲା। ପୁଣି ଠିକ୍ ହେଲେ ବ୍ଲକ୍ ଆରମ୍ଭ ହୋଇପାରିବ।",
    "Leaving doesn't end it. Ending it early waits like any looser change.": "ସ୍ଥାନ ଛାଡ଼ିଲେ ଏହା ଶେଷ ହୁଏ ନାହିଁ। ଏହାକୁ ଆଗରୁ ଶେଷ କରିବା ଯେକୌଣସି ଢିଲା ବଦଳ ଭଳି ଅପେକ୍ଷା କରେ।",
    "Its time blocks on its own, without a check-in.": "ଏହାର ସମୟ ଚେକ୍-ଇନ୍ ବିନା ନିଜେ ନିଜେ ବ୍ଲକ୍ କରେ।",
    "It waits your stricter delay, like New session. It's in Changes.": "ନୂଆ ସେସନ୍ ଭଳି ଏହା ଆପଣଙ୍କ କଡ଼ା ଅପେକ୍ଷା କରେ। ଏହା ବଦଳ ରେ ଅଛି।",
    "A block from this rule is already on.": "ଏହି ନିୟମର ଏକ ବ୍ଲକ୍ ଆଗରୁ ଚାଲୁ ଅଛି।",
    "The block couldn't start safely. iOS may not be able to track another session right now. Nothing changed.": "ବ୍ଲକ୍ ସୁରକ୍ଷିତ ଭାବେ ଆରମ୍ଭ ହୋଇପାରିଲା ନାହିଁ। iOS ଏବେ ଆଉ ଏକ ସେସନ୍ ଟ୍ରାକ୍ କରିପାରୁନଥାଇପାରେ। କିଛି ବଦଳି ନାହିଁ।",
    "Review": "ଦେଖନ୍ତୁ",
    "Then runs until %@.": "ତା’ପରେ %@ ପର୍ଯ୍ୟନ୍ତ ଚାଲେ।",
    "starts a block": "ଏକ ବ୍ଲକ୍ ଆରମ୍ଭ କରେ",
    "This block won't start.": "ଏହି ବ୍ଲକ୍ ଆରମ୍ଭ ହେବ ନାହିଁ।",
    "This window closes before your stricter wait ends.": "ଆପଣଙ୍କ କଡ଼ା ଅପେକ୍ଷା ଶେଷ ହେବା ପୂର୍ବରୁ ଏହି ଝରକା ବନ୍ଦ ହୁଏ।",
    "A change to this rule lands first. Check in after it lands.": "ଏହି ନିୟମର ଏକ ବଦଳ ପ୍ରଥମେ ଲାଗୁ ହୁଏ। ତାହା ଲାଗୁ ହେଲା ପରେ ଚେକ୍ ଇନ୍ କରନ୍ତୁ।",
    "Its rule changed while it waited. Cancel it in Changes, then check in again.": "ଅପେକ୍ଷା ସମୟରେ ଏହାର ନିୟମ ବଦଳିଗଲା। ବଦଳ ରେ ଏହାକୁ ବାତିଲ୍ କରନ୍ତୁ, ତା’ପରେ ପୁଣି ଚେକ୍ ଇନ୍ କରନ୍ତୁ।",
    // Fixes batch F3–F5 (2026-11-15)
